SELECT 'moj-all-verified-judgments-review-002-chunk-167' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ab01fec8-ec0f-588f-89ad-71e3e4e9cffe","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -قطعة أرض -إفراغ األب لالبن قطعة أرض للحصول على قرض صندوق التنمية العقاري -وفاة الوالد -مطالبة الورثة بإعادة األرض إلى أماك الوالد ألن البيع صوري -فقدان بينة الدعوى -عدم قبول شهادة عمودي النسب بعضهم لبعض -املثبت مق دم على النايف -صرف النظر عن الدعوى واخاء سبيل املدعى","document_number":"3458358","case_number":"3493307","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"عقار -قطعة أرض -إفراغ األب لالبن قطعة أرض للحصول على قرض صندوق التنمية العقاري -وفاة الوالد -مطالبة الورثة بإعادة األرض إلى أماك الوالد ألن البيع صوري -فقدان بينة الدعوى -عدم قبول شهادة عمودي النسب بعضهم لبعض -املثبت مق دم على النايف -صرف النظر عن الدعوى واخاء سبيل املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3458358 :‬تاريخه ‪1434/3/9 :‬هـ رقم‬\n                                ‫الدعوى ‪3493307 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 35335996‬تاريخه‪1435/7/30 :‬هـ‬\n\n\n       ‫عقــار‪ -‬قطعــة أرض ‪ -‬إفــراغ األب لالبــن قطعــة أرض للحصــول علــى‬\n       ‫قــرض صنــدوق التنميــة العقــاري ‪ -‬وفــاة الوالــد ‪ -‬مطالبــة الورثــة‬\n       ‫بإعــادة األرض إلــى أمــاك الوالــد ألن البيــع صــوري ‪ -‬فقــدان بينــة‬\n       ‫الدعــوى ‪ -‬عــدم قبــول شــهادة عمــودي النســب بعضهــم لبعــض ‪ -‬املثبــت‬\n       ‫مق ــدم علــى النــايف ‪ -‬صــرف النظــر عــن الدعــوى واخــاء ســبيل املدعــى‬\n                                                                          ‫عليهــا ‪.‬‬\n\n\n\n\n       ‫قــال صاحــب الــزاد ( ال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض‬\n                      ‫وال شــهادة أحــد الزوجــن لصاحبــة وتقبــل عليهــم )‬\n                                             ‫قاعدة‪ :‬املثبت مقدم على النايف‬\n\n\n\n       ‫ادعــت املدعيــة بــأن والدهــا ميلــك أرضــا ذكــرت وصفهــا وأنــه قــام‬\n       ‫بإفراغهــا ألخيهــا املدعــى عليــه مــن أجــل أن يأخــذ قرض ـ ًا مــن صنــدوق‬\n       ‫التنميــة العقــاري‪ -‬تــويف والدهــا ولــم يرجــع املدعــى عليــه األرض إلــى‬\n       ‫ملــك والدهمــا‪ -‬طلبــت املدعيــة إلــزام املدعــى عليــه بإعــادة هــذه األرض‬\n       ‫الــى ملــك والدهمــا‪ -‬أنكــر املدعــى عليــه مــا ذكرتــه املدعيــة ودفــع بأنه‬\n       ‫اشــتري األرض موضــع الدعــوى مــن والــدة بعشــرة أالف ريــال وســلمها‬\n\n‫‪367‬‬\n\f‫لوالــده مبوجــب صــك املبايعــة‪ -‬جــرى اإلطــاع علــى صــك املبايعــة وهــو‬\n‫مطابــق ملــا ذكــره املدعــى عليــه‪ -‬قــررت املدعيــة أن هــذا البيــع صــوري‪-‬‬\n‫جــرى ســؤال املدعيــة البينــة علــى أن البيــع صــوري‪ -‬قــررت أنــه ال بينــة‬\n‫لديهــا وطلبــت ميــن املدعــى عليــه علــى نفــي ذلــك‪ -‬حلــف املدعــى عليــه‬\n‫اليمــن‪ -‬صــدر احلكــم بصــرف النظــر عــن دعــوى املدعيــة‪ -‬قدمــت‬\n‫املدعيــة الئحــة اعتراضيــة وذكــرت يف الئحتهــا أن لديهــا بينــه علــى‬\n‫دفعهــا بــأن البيــع صــوري‪ -‬أعيــد فتــح اجللســة وأحضــرت املدعيــة‬\n‫شــاهدين أحدهمــا ابــن أختهــا والثانــي عامــل املزرعــة عنــد والدهمــا‬\n‫رحمــة اهلل وشــهدا بــأن البيــع صــوري‪ -‬قــرر املدعــى عليــه بــأن لديــة‬\n‫بينــة تشــهد بــأن البيــع حقيقــي جــرى فيــه تســليم الثمــن وليــس صوريـاً‪-‬‬\n‫احضــر ثالثــة شــهدوا ‪ -‬جــري تعديــل الشــهود‪ -‬حيــث إن بينــه املثبــت‬\n‫مقدمــه علــى بينــة النــايف قــرر فضيلــة القاضــي اســتمراره علــى حكمــه‬\n‫االول‪ -‬قــررت املدعيــة اســتمراره يف املعارضــة علــى احلكــم ‪-‬صــدق‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبع‪/‬املســاعد برقــم ‪ 3493307‬وتاريــخ ‪1434/02/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34478714‬وتاريــخ ‪ 1434/02/25‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/03/09‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 00‬‬\n‫وفيهــا حضــرت املدعيــة ‪...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم ‪...‬واملعرف بها من قبل أخيها ‪...‬ســعودي اجلنســية مبوجب الســجل‬\n\n                                                                                   ‫‪368‬‬\n\f      ‫املدنــي رقم‪......‬وحضــر حلضورهــا املدعــى عليــه ‪...‬وقــررت املدعيــة قائلــة‬\n      ‫إن والــدي ميلــك األرض الواقعــة يف شــارع األربعــن خلــف مطعــم ‪...‬وقــد‬\n      ‫قــام بإفــراغ هــذه األرض ألخــي ‪...‬ألجــل أن يأخــذ قــرض مــن صنــدوق‬\n      ‫التنميــة العقــاري ثــم تــويف والــدي ولــم يرجــع ‪...‬األرض إلــى ملــك والــدي‬\n      ‫أطلــب احلكــم عليــه وإلزامــه بإعــادة هــذه األرض إلــى أمــاك والــدي‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه عمــا ذكرتــه املدعيــة أجــاب قائــا‬\n      ‫بــأن مــا ذكرتــه املدعيــة غيــر صحيــح والصحيــح أن هــذه األرض‬\n      ‫اشــتريتها مــن والــدي مببلــغ عشــرة آالف ريــال وســلمت لوالــدي املبلــغ‬\n      ‫مبوجــب صــك املبايعــة رقم‪48‬يف‪1397/2/5‬ه ـ الصــادر مــن كتابــة‬\n      ‫عــدل ينبــع هكــذا أجــاب فجــرى منــي اإلطــاع علــى الصــك املذكــور‬\n      ‫فوجدتــه طبــق مــا ذكــر املدعــى عليــه وبعــرض ذلــك علــى املدعيــة قالــت‬\n      ‫مــا ذكــره املدعــى عليــه غيــر صحيــح والبيــع الــذي حصــل بيــع صــوري‬\n      ‫ولــم يســتلم والــدي مبلــغ األرض هكــذا قالــت فســألت املدعيــة هــل‬\n      ‫لديــك بينــة علــى أن البيــع بيعــا صوريــا وأن والــدك لــم يســتلم املبلــغ قالــت‬\n      ‫ال ‪ ،‬وأطلــب ميينــه هكــذا أجابــت وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫حلــف قائــا (واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة‬\n      ‫أن العقــار الواقــع يف شــارع األربعــن ملــك لــي اشــتريته مــن والــدي مببلــغ‬\n      ‫عشــرة آالف ريــال وســلمت املبلــغ كامــا لوالــدي) هكــذا حلــف وبنــاء‬\n      ‫علــى مــا ســبق مــن الدعــوى واإلجابــة واطالعــي علــى الصــك الصــادر‬\n      ‫مــن كتابــة عــدل ينبــع املذكــور أعــاه ومبــا أن املدعيــة لــم تقــم البينــة‬\n      ‫علــى أن البيــع صــوري وليمــن املدعــى عليــه لــذا فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعيــة وأخليــت ســبيل املدعــى عليــه هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعيــة قــررت اعتراضهــا بالئحــة‬\n\n\n‫‪369‬‬\n\f‫اعتراضيــة فأفهمــت بــأن لهــا مــدة ثالثــن يومــا تبــدأ مــن هــذا اليــوم فــإذا‬\n‫مضــت املــدة ولــم تتقــدم بشــيء فــإن احلكــم يكتســب القطعيــة ويســقط‬\n‫حقهــا يف االعتــراض فأبــدت فهمهــا لذلــك كمــا جــرى تســليمها صــورة‬\n‫مــن صــك احلكــم ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/09‬ه ـ ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق‪ 1434/04/03‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة وفيهــا حضــرت املدعيــة واملدعــى عليــه وقــد تقدمــت املدعيــة‬\n‫بالئحتهــا االعتراضيــة واملكونــة مــن ورقتــن وقــد ذكــرت أن لديهــا‬\n‫بينــات لــذا قــررت النظــر فيهــا فســألت املدعية عن بينتهــا فقالت إن لدي‬\n‫شــهود يشــهدون علــى أن البيــع صــوري وهمــا ابــن أختــي ‪...‬وعامــل مزرعــة‬\n‫والــدي ‪...‬فســألت الشــاهد ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم‪...‬واملولــود يف‪1397/2/11‬ه ـ ولــدى ســؤاله عمــا لديــه قــال أشــهد‬\n‫هلل أننــي ســمعت جــدي ‪ ...‬والــد املدعيــة واملدعــى عليــه يقــول إننــي لــم‬\n‫أبــع األرض مــدار الدعــوى علــى ابنــي ‪...‬وإمنــا أفرغــت لــه ألجــل اســتخراج‬\n‫قــرض مــن الصنــدوق العقــاري ولــم أســتلم منــه أي مبلــغ هكــذا شــهد‬\n‫كمــا جــرى ســؤال الشــاهد ‪...‬بنجالديشــي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقم‪...‬والــذي يعمــل حتــت كفالــة والــد املدعيــة واملدعــى عليــه‬\n‫عــن شــهادته فأجــاب وهــو يعــرف اللغــة العربيــة جيــدا أننــي أعمــل حتــت‬\n‫كفالــة ‪...‬مــدة ســبعة عشــر ســنة وقــد ســمعت كفيلــي يقــول إننــي لــم أبع‬\n‫علــى ابنــي ‪...‬ولــم أســتلم منــه شــيء فيمــا يخــص األرض الواقعــة بشــارع‬\n‫األربعــن هكــذا شــهد وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n‫عليــه قــال إن شــهادتهم غيــر صحيحــة وأمــا الشــاهد األول فهو ابن أختي‬\n‫ويشــهد لوالدتــه وال أقبــل شــهادته وأمــا الشــاهد الثانــي فــا يعــرف شــيئا‬\n\n\n                                                                                        ‫‪370‬‬\n\f      ‫فطلبــت مــن املدعيــة إحضــار معدلــن للشــاهد ‪...‬فأحضــرت كال مــن‬\n      ‫‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...‬و‪... ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقم‪...‬ولــدى ســؤالهما عمــا لديهمــا مــن شــهادة‬\n      ‫قــاال نشــهد بــاهلل أن الشــاهد ‪...‬بنجالديشــي اجلنســية ثقــة عــدل مقبــول‬\n      ‫الشــهادة كمــا أضافــت املدعيــة قائلــة إن مــن ضمــن الصــك الــذي قدمه‬\n      ‫املدعــى عليــه انتقــال جــزء منــه ألخــي ‪ ...‬وقــد أقــر أخــي ‪ ...‬بشــهادة أخــي‬\n      ‫املدعــى عليــه ‪...‬أن األرض مــدار الدعــوى لوالــدي أطلــب اإلطــاع علــى‬\n      ‫اإلقــرار كمــا أطلــب إحضــار شــهود املبايعــة الذيــن شــهدوا لــدى كاتــب‬\n      ‫العــدل كمــا قــرر املدعــى عليــه بــأن لديــه شــهود يشــهدون علــى صحــة‬\n      ‫املبايعــة وأن والــده اســتلم املبلــغ فطلبــت منــه إحضارهــم فوعــد بذلــك‬\n      ‫ولــذا رفعــت اجللســة ويف يــوم األحــد املوافــق‪ 1434/04/07‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09:30‬وفيهــا حضــرت املدعيــة واملدعــى عليــه وقــد‬\n      ‫أحضــر املدعــى عليــه شــهود املبايعــة لــدى كاتــب العــدل وهــم ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬واملولــود يف ‪1343/07/01‬هـ ـ‬\n      ‫ولــدى ســؤاله عمــا لديــه مــن شــهادة قــال ( أشــهد هلل اننــي شــاهدت ‪...‬‬\n      ‫وهــو يســلم والــده عشــرة آالف ريــال عنــد كاتــب العــدل وال أعلــم ســببها‬\n      ‫هكــذا شــهد ) كمــا حضــر الشــاهد ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬واملولــود يف ‪1358/07/01‬هـ ـ ويســكن يف حــي‬\n      ‫‪...‬ولــدى ســؤاله عمــا لديــه مــن شــهاده قــال ( اشــهد هلل اننــي ســمعت ‪...‬‬\n      ‫والــد املتداعــن اقــر عنــد كاتــب العــدل قائــا اننــي بعــت االرض التــي‬\n      ‫بشــارع االربعــن علــى ابنــي ‪...‬واننــي اســتلمت مبلــغ عشــرة آالف ريــال‬\n      ‫هكــذا شــهد) كمــا أحضــر الشــاهد ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬املولــود يف ‪1375/07/01‬ه ـ ومتقاعــد عــن العمــل‬\n\n\n‫‪371‬‬\n\f‫ويســكن يف ج‪ 19/‬ولــدى ســؤاله عمــا لديــه مــن شــهادة قــال ( اشــهد‬\n‫هلل اننــي ســمعت والــدي املتداعــن يقــول اننــي بعــت االرض التــي بشــارع‬\n‫االربعــن مــدار الدعــوى علــى ابنــي ‪...‬مببلــغ عشــرة آالف ريــال واننــي‬\n‫اســتلمت املبلــغ كامــا هكــذا شــهد ) وبعــرض الشــهود وشــهادتهم‬\n‫علــى املدعيــة قــال امــا الشــاهدان ‪...‬و‪...‬ال نعلــم عنهمــا شــيئا وامــا‬\n‫شــهادتهما فهــي متناقضــة وامــا الشــاهد ‪...‬فهــو زوج أختــي ‪...‬وال نقبــل‬\n‫شــهادته فطلبــت مــن املدعــى عليــه إحضــار معدلــن للشــهود فأحضــر‬\n‫‪ ......‬ســعودي اجلنســية مبوجب الســجل املدني رقم ‪...‬و‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬ولــدى ســؤاله عمــا لديهمــا قــاال نشــهد‬\n‫هلل ان الشــهود ‪...‬و‪...‬و‪...‬ثقــات عــدول مقبولــوا الشــهادة هكــذا شــهد‬\n‫وبنــاء علــى مــا ســبق مــن اعتــراض املدعيــة وإحضارهــا شــهود يشــهدون‬\n                                                                   ‫بصوريــة البيــع‬\n‫وكان أحــد الشــهود ابــن اختهــا وإلحضــار املدعــى عليــه شــهود املبايعــة‬\n‫التــي متــت عنــد كاتــب العــدل وشــاهدا آخــر وهــو زوج أختــه وألنــه ال‬\n‫تقبــل شــهادة عمــودي النســب وتقبــل عليهــم كمــا قــال صاحــب الــزاد (‬\n‫ال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض وال شــهادة أحد الزوجني‬\n‫لصاحبــه وتقبــل عليهــم ) والن املثبــت مقــدم علــى الثانــي لــذا لــم يظهر لي‬\n‫ســوى مــا حكمــت بــه وبعــرض احلكــم علــى املدعيــة قــررت اعتراضهــا‬\n‫بالئحــة اعتراضيــه فأفهمتهــا بــأن لهــا مــدة ثالثــن يومــا تبــدأ مــن هــذا‬\n‫اليــوم واذا مضــت املــدة ولــم تتقــدم خاللهــا بشــيء فأنــه يســقط حقهــا يف‬\n‫طلــب االعتــراض ويكتســب احلكــم القطعيــة كمــا قــرر املدعــى عليــه‬\n‫قناعتــه باحلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/07‬ه ـ‬\n\n\n                                                                                      ‫‪372‬‬\n\f      ‫ويف يــوم اإلثنــن املوافــق‪ 1434/05/06‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرة والنصــف وقــد قدمــت املدعيــة الئحتهــا االعتراضيــة واملكونــة‬\n      ‫مــن ســت ورقــات ولــم أجــد فيهــا مــا يؤثــر علــى ماحكمــت بــه‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/05/06‬ه ـ ‪.‬‬\n      ‫ويف يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫احلاديــة عشــر وفيهــا حضــرت املدعيــة ‪ ...‬برفقــة املعــرف بهــا ‪...‬واملدعــى‬\n      ‫عليــه ‪......‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مالحظــا عليهــا‬\n      ‫بالقــرار رقــم ‪ 34245051‬يف ‪1434/6/19‬ه ـ وهــذا نــص احلاجــة منــه‬\n      ‫(وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n      ‫لناظــر القضيــة إلعــادة االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن‬\n      ‫املدعيــة ومناقشــة مــا ورد يف هــذه الالئحــة بحضــور الطرفــن مناقشــة‬\n      ‫دقيقــة وســماع مــا لــدى املدعيــة مــن إثبــات وقــد أشــارت املدعيــة أنهــا‬\n      ‫تطالــب باســم ورثــة والدهــا فهــل لديهــا حصــر ورثــة ألبيهــا ووكالــة مــن‬\n      ‫الورثــة أو أن الدعــوى خاصــة بهــا ومحاولــة الصلــح بــن األســر بواســطة‬\n      ‫أهــل اخليــر أن أمكــن واهلل املوفــق وصلــى اهلل علــى بنينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم ‪ .‬أ ‪ .‬ه ـ بختــم وتوقيــع رئيس وأعضاء الدائرة احلقوقية‬\n      ‫اخلامســة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة وجوابــا على‬\n      ‫مــا ذكــره أصحــاب الفضيلــة ســألت املدعيــة هــل هــذه الدعــوى خاصــة‬\n      ‫بــك أم عــن الورثــة فقالــت ال بــل هــي عــن نفســي وعــن بعــض الورثــة وهــم‬\n      ‫والدتــي ‪...‬وأخوانــي األشــقاء وهــم ‪...‬و‪ ...‬فطلبــت منــه إحضــار حصــر‬\n      ‫إرث والدهــا و وكاالت عــن الورثــة فوعــدت بذلــك فســألت املتداعيــن‬\n      ‫هــل ترغبــان بالصلــح فرفضــا ذلــك وملناقشــة الالئحــة وإحضــار املدعيــة‬\n\n\n‫‪373‬‬\n\f‫حلصــر الورثــة و الــوكاالت عــن الورثــة رفعــت اجللســة‪ ،‬ويف يــوم األربعــاء‬\n‫املوافــق‪ 1434/08/03‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر وفيهــا‬\n‫حضــرت املدعيــة ‪...‬واملعــرف بهــا مــن قبــل أخيهــا ‪...‬وقــد أحضــرت صــك‬\n‫حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 3351256‬وتاريــخ‬\n‫‪1433/1/29‬ه ـ واملتضمــن وفــاة ‪ ...‬يف ‪1433/1/12‬ه ـ وانحصــار ورثتــه‬\n‫يف زوجتــه ‪...‬ويف أوالده منهــا ‪...‬و‪ ...‬ويف أوالده املرزوقــن لــه مــن زوجتــه‬\n‫‪...‬واملتوفــاة قبلــه وهــم ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬كمــا جــرى االطــاع علــى‬\n‫وكالــة املدعيــة عــن أختهــا ‪ ....‬وأخيهــا ‪ ...‬مبوجــب الوكالــة الصادرة من‬\n‫كتابــة عــدل ينبــع برقــم ‪ 34975681‬يف ‪1434/7/22‬ه ـ كمــا جــرى‬\n‫االطــاع علــى وكالــة املدعيــة عــن والدتهــا ‪...‬مبوجــب الوكالــة رقــم‬\n‫‪ 34975808‬يف ‪1434/7/22‬ه ـ واملخــول لهــا يف جميــع الــوكاالت حــق‬\n‫الصلــح والتنــازل واإلبــراء واإلقــرار واملدافعــة واملرافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا وقبــول األحــكام وجوابــا علــى املالحظــة األولــى فإنــه قــد‬\n‫جــرى اطالعــي علــى الالئحــة االعتراضيــة ســابقا ولــم أجــد فيهــا ما يؤثر‬\n‫علــى مــا حكمــت بــه وآمــل مــن أصحــاب الفضيلــة حفظهــم اهلل حتديــد‬\n‫املؤثــر يف الالئحــة حتــى تتــم مناقشــته هــذا مــا لــزم اجلــواب عنــه وقــررت‬\n‫بعــث املعاملــة حملكمــة االســتئناف‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ‪... /‬القاضــي باحملكمــة العامــة بينبــع املســجل‬\n‫بعــدد ‪ 3458358‬وتاريــخ ‪1434/03/09‬ه ـ املتضمــن دعــوى‪ ... /‬ضــد‪/‬‬\n\n\n                                                                                      ‫‪374‬‬\n\f      ‫‪...‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة‬\n      ‫ضبط ــه والئحتــه االعتراضيــة تق ــرر باألكثريــة املوافق ــة عل ــى احلكــم‬\n      ‫بعــد اإليضــاح األخيــر‪ .‬وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                        ‫وعل ــى آل ــه وصحب ــه وســلم ‪،،،،،،،،،‬‬\n\n\n\n\n‫‪375‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":367,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"05fc345b10188bce9cecee7f1dea4e211f0dee3cead6ed2e50b564bef55c5bd3","normalized_text_hash":"80acab14f35ec172c270c53a897a8b56ed8da86fe034024b598fd6d356b7f7e1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p367-3458358"},{"id":"8b0ef999-bc67-5edc-86c7-d1feb34ebb9a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء قطعة أرض -انطباق صكن على عقار واحد ( ازدواجية الصكوك ) -االستفسار عن الصكوك وتسلسلها -احلكم بإلغاء أحد الصكن السبقية الصك األخر قولة النبي صلى اهلل عليه وسلم حلكيم بن حزام رضي اهلل عنه التبع ماليس عنك","document_number":"3417544","case_number":"32391074","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة ...ختم وتوقيع عليه فقد أمرت بإثباته على ضبطه وسجله","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"عقار -شراء قطعة أرض -انطباق صكن على عقار واحد ( ازدواجية الصكوك ) -االستفسار عن الصكوك وتسلسلها -احلكم بإلغاء أحد الصكن السبقية الصك األخر قولة النبي صلى اهلل عليه وسلم حلكيم بن حزام رضي اهلل عنه التبع ماليس عنك","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3417544 :‬‬\n                   ‫َر ْق ُم الدعوى‪32391074 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34201758‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n‫عقــار‪ -‬شــراء قطعــة أرض ‪ -‬انطبــاق صكــن علــى عقار واحــد ( ازدواجية‬\n‫الصكــوك ) ‪ -‬االستفســار عــن الصكــوك وتسلســلها‪ -‬احلكــم بإلغاء أحد‬\n                                    ‫الصكــن الســبقية الصك األخر‬\n\n\n\n‫قولــة النبــي صلــى اهلل عليــه وســلم حلكيــم بــن حــزام رضــي اهلل عنــه‬\n                                                    ‫التبــع ماليــس عنــك‬\n\n\n\n\n‫ادعــى املدعــى بــأن مــن اجلــاري يف ملكــة قطعــة أرض ذكــر وصفهــا‬\n‫وأبــرز صــك متلكــه لهــا ‪ ،‬وتبــن أن بيــد املدعــى عليــه صــكا آخــر علــى‬\n‫ذات األرض‪ -‬طلــب املدعــى احلكــم بالغــاء صــك املدعــى عليــه‪ -‬صــادق‬\n‫املدعــى عليــه وكالــه علــى ماجــاء يف الدعــوى ودفــع بــأن موكلــه ميلــك‬\n‫األرض محــل النــزاع مبوجــب صــك صــادر مــن كتابــة العــدل‪ -‬وقــرر‬\n‫عــدم موافقتــه علــى طلــب املدعــي بالغــاء صــك موكلــه‪ -‬جــرت عــده‬\n‫مكاتبــات واستفســارات لكتابــة العــدل لبيــان تسلســل الصكــوك وما‬\n‫بنيــت عليــه‪ -‬بعــد ورود اجلــواب علــى االستفســارات املطلوبــة تبــن أن‬\n‫احــد املواطنــن بــاع األرض محــل الدعــوى مرتــن ولكــون البيــع الثانــي‬\n‫باطــل لقــول النبــي صلــى اهلل عليــه وســلم حلكيــم بن حــزام ال تبع ماليس‬\n\n                                                                                 ‫‪376‬‬\n\f      ‫عنــدك‪ -‬وهــذه الطريــق هــي التــي وصــل امللــك فيهــا للمدعــى عليــه لــذا‬\n      ‫صــدر احلكــم بعــدم اســتحقاق املدعــى عليــه لقطعــه األرض محــل النزاع‬\n      ‫وقــرر القاضــي التهميــش علــى صــك املدعــى عليــه بااللغــاء كمــا ثبــت‬\n      ‫صحــة متلــك املدعــى لقطعــة االرض محــل النــزاع‪ -‬قــرر املدعــى عليــه‬\n                       ‫عــدم القناعــة‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n      ‫برقــم ‪ 32391074‬وتاريــخ ‪ 1432/09/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 321144324‬وتاريــخ ‪ 1432/09/03‬ه ـ حضــر املدعــي ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضــوره ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬عــن ‪...‬مبوجــب الوكالــة رقــم‬\n      ‫‪ 3987‬يف ‪1433/01/12‬ه ـ فادعــى قائــا يف دعــواه إن مــن اجلــاري يف‬\n      ‫ملكــي وحتــت تصــريف قطعــة األرض رقــم ‪ / 203‬أ مــن املخطــط رقــم‬\n      ‫‪/245‬ب‪1401/‬هـ لعام ‪1401‬هـ الواقع يف حي ‪ ...‬مبحافظة جدة املسجلة‬\n      ‫بالصــك رقــم ‪ ...‬يف ‪1404/09/06‬ه ـ الصــادر مــن كتابــة العــدل األولــى‬\n      ‫مبحافظــة جــدة يحدهــا مــن الشــرق القطعــة رقــم ‪ 202‬بطــول خمســة‬\n      ‫وعشــرين متــرا ومــن الشــمال شــارع عــرض خمســة عشــر متــرا بطــول‬\n      ‫خمســة وعشــرين متــرا ومــن اجلنــوب القطعــة رقــم ‪ 208‬بطــول خمســة‬\n      ‫وعشــرين متــرا ومــن الغــرب القطعــة رقــم ‪ 204‬بطــول خمســة وعشــرين‬\n      ‫متــرا وقــد اشــتريتها مــن املدعــو ‪...‬بتاريــخ ‪1432/03/04‬ه ـ ثــم تبــن لــي‬\n\n‫‪377‬‬\n\f‫أن بيــد املدعــى عليــه صــكا صــادرا من كتابــة العدل على ذات األرض‬\n‫أطلــب احلكــم بإلغــاء صــك املدعــى عليــه هــذه دعواي وبعــرض الدعوى‬\n‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه كلــه صحيــح جملــة‬\n‫وتفصيــا ولكــن موكلــي ميلــك األرض محــل النــزاع ذاتهــا املوصوفــة يف‬\n‫دعــوى املدعــي مبوجــب الصــك رقــم ‪ ....‬يف ‪1432/07/02‬ه ـ الصــادر من‬\n‫كتابــة العــدل األولــى مبحافظــة جــدة وأمــا طلــب املدعــي إلغــاء الصــك‬\n‫فــا نوافــق عليــه هكــذا أجــاب فجــرى االطــاع علــى صكــي امللكيــة‬\n‫التــي أبرزهــا الطرفــان فوجــد أنهــا كمــا ذكــر الطرفــان فقــررت بعــث‬\n‫الصكــن الــى كتابــة العــدل األولــى مبحافظــة جــدة لتزويدنــا بصــورة‬\n‫ضوئيــة مــن ســجلهما ومــا عليهمــا مــن تهميشــات واالفــادة عــن تسلســلها‬\n‫اخللفــي مفصــا ويف جلســة اخــرى حضــر الطرفــان وقــد كانــت جــرت‬\n‫الكتابــة لفضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لتزويدنا‬\n‫بصــورة ضوئيــة مــن ســجل الصكــن ومــا عليهمــا من تهميشــات مبوجب‬\n‫خطابنــا رقــم ‪ 33137022‬يف ‪1433/01/19‬ه ـ فوردنــا خطــاب فضيلتــه‬\n‫رقــم ‪ 33207836‬يف ‪1433/02/29‬ه ـ ونــص احلاجــة منــه ( أنــه بالرجــوع‬\n‫لســجل الصــك رقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ جلــد ‪/3/119‬ت ظهــر‬\n‫أنــه يشــتمل علــى القطعــة رقــم ‪/203‬أ ضمــن املخطــط املعتمــد باللوحــة‬\n‫رقــم ‪/245‬ب‪ 1401/‬وهــو متلــك الســيد ‪...‬وعلــى ســجله عــدة شــروحات‬\n‫وهــي ‪ -1 :‬شــرح بانتقــال ملكيــة كامــل احملــدود جلهــة ‪ ... /‬بتاريــخ‬\n‫‪1428/03/15‬ه ـ ‪ -2‬شــرح بانتقــال ملكيــة احملــدود جلهــة ‪... /‬بتاريــخ‬\n‫‪1432/03/04‬ه ـ ‪ -3‬شــرح بانتقــال ملكيــة كامــل احملــدود جلهــة‬\n‫‪ ... /‬بتاريــخ ‪1432/04/16‬ه ـ ) إلــى ماجــاء فيــه (وبالرجــوع لســجل‬\n‫الصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه ـ جلــد ‪/5/46‬ت ظهــر أنــه‬\n\n\n                                                                                  ‫‪378‬‬\n\f      ‫يشــتمل علــى القطعــة رقــم ‪/203‬أ ضمــن املخطــط املعتمــد باللوحــة‬\n      ‫رقــم ‪/245‬ب‪ 1401/‬وهــو متلــك ‪...‬وعلــى ســجله شــرح بانتقــال ملكيــة‬\n      ‫كامــل احملــدود جلهــة ‪... /‬الســيد بتاريــخ ‪1425/11/29‬ه ـ ثــم انتقــل‬\n      ‫جلهــة ‪...‬بالصــك اآللــي رقــم ‪ 320205004789‬وتاريــخ ‪1432/07/02‬ه ـ‬\n      ‫وأن هــذا الصــك محجــوز مبوجــب شــرح فضيلــة رئيــس كتابــة العــدل‬\n      ‫األولــى مبحافظــة جــدة رقــم ‪ 37130‬يف ‪1432/07/03‬ه ـ املتضمــن فيــه‬\n      ‫يوقــف صــك احلاســب حلــن رفــع االزدواجيــة ) كمــا وجــد برفــق خطــاب‬\n      ‫فضيلتــه إفــادة مــن مســاعد مديــر الســجالت ونصهــا (فضيلــة رئيــس‬\n                               ‫كتابــة العــدل األولــى مبحافظــة جــدة ســلمه اهلل ‪.‬‬\n      ‫الســام عليكــم ورحمــة اهلل وبركاتــه وبعــد‪ :‬بشــأن الصــك رقــم‬\n      ‫‪ 5948‬جلــد ‪/2/119‬ت يف ‪1404/09/06‬ه ـ والــذي يتضمــن القطعــة‬\n      ‫رقــم ‪/203‬أ عليــه ازدواجيــة بالصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه ـ‬\n      ‫جلــد ‪/5/46‬ت الــذي صــدر صــك آلــي رقــم ‪ 320505004789‬يف‬\n      ‫‪1432/07/02‬ه ـ عليــه نفيــد فضيلتكــم بــأن ســبب االزدواجيــة هــو‬\n      ‫أن القطعــة ‪/203‬أ مســتنده هــو الصــك رقــم ‪ 107‬يف ‪1404/03/16‬ه ـ‬\n      ‫ولكــن اثبــت علــى ســجل الصــك رقــم ‪ 106‬يف ‪1404/03/16‬هـ مخطط‬\n      ‫‪ 3/3‬صحيفــة ‪ 37‬ومت تــدارك ذلــك مــن قبــل اللجنــة الســابقة ‪ ...‬و‪ ...‬و‪...‬‬\n      ‫ونقلــه إلــى مســتنده الصحيــح ‪ 107‬مخطــط ‪ 3/5‬صحيفــة ‪ 7‬دون ذكــر‬\n      ‫تاريــخ أمــا بخصــوص الصــك رقــم ‪ 2058‬يف ‪1425/10/29‬ه ـ جلــد‬\n      ‫‪/5/46‬ت فيســتند علــى الصــك رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ جلــد ‪1‬‬\n      ‫‪ 13/‬ومهمــش عليــه بذلــك علمــا بــأن الصــك رقــم ‪ 85‬عليــه شــرح مــن‬\n      ‫قبــل الشــيخ ‪...‬يتضمــن األتــي ‪ /‬بنــاء علــى قــرار اللجنــة رقــم ‪ 245‬يف‬\n      ‫‪1431/06/02‬ه ـ فقــد جــرى أخــذ إقــرار البائــع واملشــتري باطــن هــذا‬\n\n\n‫‪379‬‬\n\f‫الصــك علــى العــدول عــن بيــع القطــع املتبقيــة باطــن الصــك نظــرا ألنهــا‬\n‫ســبق وأن أفرغــت مــن الســابق وأن هــذا البيــع وقــع يف غيــر محلــه وذلــك‬\n‫حســبما دون صحيفــة األوراق رقــم ‪ 30،31، 29‬جلــد ‪ 13/148‬يف‬\n‫‪1432/02/15‬ه ـ انتهــى وعلــى ســجل الصــك رقــم ‪ 85‬صــور مــن قــرار‬\n‫اللجنــة ‪ 249‬يف ‪1431/06/10‬ه ـ القطعــة ‪ 203‬ليســت مــن ضمنهــا علمــا‬\n‫بــأن القطعــة ‪/203‬أ ضمــن الصــك رقــم ‪ 85‬ومهمــش علــى مســتنده مــن‬\n‫قبــل الشــيخ ‪...‬علــى املخطــط ‪ 3/5‬صحيفــة ‪ 8‬ومت علــى ســجل مســتنده‬\n‫‪ 1075‬مخطــط ‪/4/1‬ث صحيفــة ‪ 188‬شــرح مــن قبــل الشــيخ ‪...‬بالعــدول‬\n‫عــن بيــع القطــع ومــن ضمنهــا القطعــة رقــم ‪ 283‬بنــاء علــى قــرار اللجنــة‬\n‫‪ 245‬يف ‪1431/06/02‬ه ـ وحســب مــادون باإلقــرار ‪131،130،129‬‬\n‫جلــد ‪ 13/148‬يف ‪1432/02/15‬ه ـ هــذا مــا لدينــا مــن واقــع الســجالت‬\n‫طرفنــا هــذا وقــد مت وضــع صــورة مــن خطابنــا هــذا علــى ســجل الصــك‬\n‫‪ 5948‬امللحــق رواس ‪ 34‬صحيفــة ‪ 19‬ونأمــل تعميــد مــن يلــزم بعــدم‬\n‫التصــرف للصــك اآللــي ‪ 320505004789‬يف ‪1432/07/02‬ه ـ حتــى‬\n‫يتــم معاجلــة موضــوع االزدواجيــة لالطــاع والتوجيــه) كمــا وجــد مــن‬\n‫ضمــن املرفقــات صــورة مــن قــرار جلنــة دراســة الصكــوك رقــم ‪ 242‬قــي‬\n‫‪1431/06/01‬ه ـ وبعــد االطــاع عليهــا وجــد ان القطعــة محــل النــزاع‬\n‫رقــم ‪ 203‬مــن اجلــزء أ غيــر موافقــة ملســتندها ومبــا أنــه لــم يتبــن مــن هــذا‬\n‫اخلطــاب هــل مســتند هذيــن الصكــن واحــد أم ال فقــد جــرى منــا إعــادة‬\n‫مخاطبــة فضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لإلفــادة‬\n‫عــن ذلــك مبوجــب خطابنــا رقــم ‪ 33317869‬يف ‪1433/04/05‬ه ـ‬\n‫فوردنــا خطــاب فضيلتــه رقــم ‪ 33681695‬يف ‪1433/04/21‬ه ـ ونــص‬\n‫احلاجــة منــه (عليــه نفيــد فضيلتكــم أن القطعــة املــراد االستفســار‬\n\n\n                                                                                         ‫‪380‬‬\n\f      ‫عنهــا هــي القطعــة رقــم ‪/203‬أ والتــي ضمــن املخطــط املعتمــد باللوحــة‬\n      ‫رقــم ‪/245‬ب‪1401/‬ه ـ وهــي مــن ضمــن الصــك رقــم ‪ 107‬وتاريــخ‬\n      ‫‪1404/03/16‬ه ـ جلــد ‪ ، 3/1‬أن القطعــة رقــم ‪/203‬أ صــدر عليهــا‬\n      ‫صكــن وهــي كمــا يلــي‪ -1 :‬الصــك رقــم ‪ 5948‬جلــد ‪/3/119‬ت‬\n      ‫وتاريخ‪1404/09/06‬ه ـ مــن كاتــب العــدل الســابق بهــذه اإلدارة الشــيخ‬\n      ‫‪ ،... /‬وهــو الصــك األقــدم إال أنهــا لــم تهمــش علــى مســتندها الصحيــح‬\n      ‫وهــو الصــك رقــم ‪ 107‬وإمنــا همشــت عــن طريــق اخلطــأ بالصــك رقــم ‪106‬‬\n      ‫جلــد ‪ 3/1‬وتاريــخ ‪1404/03/16‬ه ـ وقــد مت تــدارك اخلطــأ عــن طريــق‬\n      ‫اللجنــة بهــذه اإلدارة فقامــت اللجنــة بتصحيــح اخلطــأ ونقــل تهميــش‬\n      ‫القطعــة مــن ســجل الصــك رقــم ‪ 106‬إلــى ســجل الصــك رقــم ‪107‬‬\n      ‫علمــا أن الصــك رقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ جلــد ‪/3/119‬ت قــد‬\n      ‫تداولتــه األيــدي بالبيــع والشــراء حتــى اســتقر يف ملــك ‪...‬وذلــك بتاريــخ‬\n      ‫‪1432/04/16‬ه ـ وال زال يف ملــك ‪...‬حتــى تاريخــه‪ -2 .‬الصــك رقــم ‪85‬‬\n      ‫وتاريــخ ‪1425/06/32‬ه ـ جلــد ‪ 13/1‬الصــادر مــن كاتــب العــدل بهــذه‬\n      ‫اإلدارة الشــيخ ‪...‬ويشــتمل علــى عــدة قطــع مــن ضمنهــا القطعــة رقــم‬\n      ‫‪/203‬ا وقــد تداولتهــا األيــدي بالبيــع والشــراء حتــى اســتقرت القطعــة‬\n      ‫يف ملــك ‪....‬بالصــك اآللــي رقــم ‪ 320505004789‬يف ‪1432/07/02‬ه ـ‬\n      ‫) ومبــا أن الصــك املدعــى عليــه يعتمــد علــى الصــك رقــم ‪ 2508‬يف‬\n      ‫‪1425/10/29‬ه ـ الــذي يعتمــد على الصك رقم ‪ 85‬يف ‪1425/06/23‬هـ‬\n      ‫ومبــا انــه لــم يتبــن مــن خطابــات كتابــة العــدل التسلســل اخللفــي للصــك‬\n      ‫رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ لــذا فقــد قــررت مخاطبــة كتابــة العــدل‬\n      ‫لإلفــادة عــن ذلــك ويف جلســة اخــرى حضــر الطرفــان وقــد كانــت جــرت‬\n      ‫الكتابــة لفضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لتوضيــح‬\n\n\n‫‪381‬‬\n\f‫التسلسل اخللفي للصك رقم ‪ 85‬يف ‪1425/06/23‬هـ مع تزويدنا بصورة‬\n‫ضوئيــة مــن ســجله ومــا عليــه مــن تهميشــات وذلــك مبوجــب خطابنــا رقــم‬\n‫‪ 331221442‬يف ‪1433/07/26‬ه ـ فوردنــا خطابهــم رقــم ‪331513548‬‬\n‫يف ‪1433/08/19‬ه ـ ونــص احلاجــة منــه ( وإن التسلســل اخللفــي للصــك‬\n‫رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ جلــد ‪ 13/1‬هــو الصــك الصــادر مــن‬\n‫احملكمــة الشــرعية الكبــرى برقــم ‪ 27‬يف ‪1400/08/10‬ه ـ جلــد‬\n‫‪ 5/1‬ونرفــق لفضيلتكــم صــورة ضوئيــة مــن ســجل الصــك رقــم ‪ 85‬يف‬\n‫‪1425/06/23‬ه ـ جلــد ‪ 13/1‬وكذلــك صــورة ضوئيــة مــن ســجل صــك‬\n‫املخطــط رقــم ‪ 107‬وتاريــخ ‪1404/03/16‬ه ـ ومــا عليهــا مــن تهميشــات‬\n‫وشــروحات باالنتقــال وكذلــك صــورة ضوئيــة مــن ســجل الصــك رقــم‬\n‫‪ 151‬وتاريــخ ‪1401/04/25‬ه ـ وصــورة ضوئيــة مــن ســجل الصــك رقــم‬\n‫‪ 141‬يف ‪1401/03/12‬ه ـ وصــورة ضوئيــة مــن ســجل الصــك رقــم ‪142‬‬\n‫يف ‪1401/03/11‬ه ـ وكذلــك صــورة ضوئيــة مــن تهميــش القطعــة رقــم‬\n‫‪/203‬أ باخلطــأ علــى ســجل الصــك رقــم ‪ 106‬وأيضــا صــورة ضوئيــة مــن‬\n‫تهميــش القطعــة رقــم ‪/203‬أ علــى ســجل الصــك الصحيــح رقــم ‪ 107‬بعد‬\n‫تعديــل اخلطــأ مــن قبــل اللجنــة كمــا نفيــد فضيلتكــم أن الصكــن‬\n‫رقــم ‪ 5948‬يف ‪/3/119‬ت والصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه جلــد‬\n‫‪/5/46‬ت والذيــن يشــتمالن علــى القطعــة رقــم ‪/203‬أ مســتندها واحــد‬\n‫وهــو الصــك رقــم ‪)107‬فجــرى االطــاع علــى الصــور الضوئيــة لســجالت‬\n‫الصكــوك املشــار إليهــا يف اخلطــاب ونــص احلاجــة منــه أعــاه فتبــن‬\n‫اآلتــي ‪ :‬أن القطعــة محــل النــزاع وهــي ذات الرقــم ‪/203‬أ مــن املخطــط‬\n‫املعتمــد باللوحــة رقــم ‪/245‬ب‪1401/‬ه ـ املســجلة بالصــك رقــم ‪ 107‬يف‬\n‫‪1404/03/16‬ه ـ قــد انتقلــت من جهــة ‪...‬إلى جهة ‪...‬يف ‪1404/03/16‬هـ‬\n\n\n                                                                                ‫‪382‬‬\n\f      ‫ثــم بيعــت وأفرغــت مرتــان ‪ -1‬بيعــت بتاريــخ ‪1404/09/06‬ه جلهــة‬\n      ‫‪...‬وصــدر بهــا صــك مســتقل برقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ ثــم انتقلــت‬\n      ‫بتاريــخ ‪1428/03/15‬ه ـ جلهــة ‪ ،...‬ثــم انتقلــت بتاريــخ ‪1432/02/04‬ه ـ‬\n      ‫جلهــة ‪ ، ...‬ثــم انتقلــت أخيــرا بتاريــخ ‪1432/04/16‬ه ـ جلهــة املدعــي ‪....‬‬\n      ‫‪ -2‬بيعــت بتاريــخ ‪1425/06/23‬ه ـ مــع مجموعــة قطــع مــن املخطــط‬\n      ‫نفســه جلهــة ‪ ...‬وصــدر لهــا وللقطــع التــي بيعــت معهــا صــك برقــم ‪ 85‬يف‬\n      ‫‪1425/06/23‬هـ ثم انتقلت بتاريخ ‪1425/10/29‬هـ إلى جهة ‪ ...‬وصدر‬\n      ‫للقطعــة محــل النــزاع صــك مســتقل برقــم ‪ 2508‬يف ‪1425/10/29‬ه‬\n      ‫ثــم انتقلــت بتاريــخ ‪1425/11/29‬ه ـ جلهــة ‪...‬ثــم انتقلــت أخيــرا بتاريــخ‬\n      ‫‪1432/07/02‬ه ـ إلــى جهــة املدعــى عليــه ‪...‬وصــدر لهــذه القطعــة محــل‬\n      ‫النــزاع صــك آلــي برقــم ‪ 320205004789‬يف ‪1432/07/02‬ه ـ ( وهــو‬\n      ‫الــذي بيــد املدعــى عليــه ) كمــا تبــن أن ســبب االزدواجيــة هــو قيــام‬\n      ‫املدعــو ‪...‬ببيــع هــذه القطعــة مرتــن ‪ ،‬وأنــه عندمــا مت البيــع األول‬\n      ‫جلهــة ‪...‬لــم يهمــش علــى املســتند الصحيــح للقطعــة محــل النــزاع وهــو‬\n      ‫الصــك رقــم ‪ 107‬يف ‪1404/03/16‬ه ـ وإمنــا همــش خطــأ علــى ســجل‬\n      ‫الصــك رقــم ‪ ...‬يف ‪1404/03/16‬ه ـ مــن قبــل كتابــة العــدل ولــم يتــم‬\n      ‫تــدارك ذلــك إال بقــرار اللجنــة املختصــة بفحــص الصكــوك رقــم ‪ ...‬يف‬\n      ‫‪1431/06/02‬ه ـ كمــا أن ممــا يؤيــد ذلــك أن القطــع املباعــة مــن ‪...‬على‬\n      ‫‪....‬يف الصــك رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ ‪ -‬وعددهــا إحــدى عشــرة‬\n      ‫قطعــة ‪ -‬لــم ُيفــرغ منهــا ســوى قطعتــان ‪ :‬إحداهمــا القطعــة محــل النــزاع‬\n      ‫‪ ،‬وأنــه مت التهميــش علــى ســجل هــذا الصــك بتاريــخ ‪1432/02/15‬ه ـ‬\n      ‫بأنــه ( مت أخــذ إقــرار البائــع ‪ ...‬واملشــتري ‪...‬علــى العــدول عــن بيــع القطــع‬\n      ‫املتبقيــة نظــرا ألنهــا ســبق وأن أفرغــت مــن الســابق وأن هــذا البيــع قــد‬\n\n\n‫‪383‬‬\n\f‫وقــع يف غيــر محلــه )أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبعــد االطــاع علــى خطابــات فضيلــة رئيــس كتابــة العــدل األولــى‬\n‫مبحافظــة جــدة املرصــودة أعــاه وبعــد االطــاع علــى الصــور الضوئيــة‬\n‫لســجالت الصكــوك املشــار أليهــا أعــاه كلهــا ومتعنهــا ودراســتها وملــا‬\n‫كان املدعــو ‪...‬قــد بــاع قطعــة األرض محــل النــزاع علــى املدعــو ‪...‬بتاريــخ‬\n‫‪1404/09/06‬ه ـ ثــم تناقلــت األيــدي هــذا البيــع حتــى وصــل إلــى املدعــي‬\n‫‪...‬ثــم باعهــا املدعــو ‪...‬مــرة أخــرى علــى املدعــو ‪...‬بتاريــخ ‪1425/06/23‬هـ‬\n‫ثــم تناقلــت األيــدي هــذا البيــع حتــى وصــل إلــى املدعــى عليــه ‪...‬ونظــرا‬\n‫لكــون البيــع الثانــي بيــع باطــل لكــون املدعــو ‪ ...‬قــد بــاع علــى املدعــو‬\n‫‪...‬مــاال ميلــك وقــد قــال احلبيــب صلــى اهلل عليــه وســلم حلكيــم بــن حــزام‬\n‫رضــي اهلل عنــه ( ال تبــع مــا ليــس عنــدك ) لــذا كلــه فقــد ثبــت لــدي‬\n‫عــدم اســتحقاق املدعــى عليــه أصالــة ‪...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬لقطعــة األرض محــل النــزاع وقــررت التهميــش‬\n‫علــى صكــه ذي الرقــم ‪ 320205004789‬يف ‪1432/07/02‬ه ـ الصــادر‬\n‫مــن كتابــة العــدل األولــى مبحافظــة جــدة باإللغــاء كمــا ثبــت لــدي‬\n‫صحــة متلــك املدعــي ‪...‬لقطعــة األرض محــل النــزاع ومبــا تقــدم حكمــت‬\n‫وأفهمــت املدعــى عليــه وكالــة بــأن ملوكلــه الرجــوع علــى مــن باعــه يف‬\n‫املطالبــة بالثمــن وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة‬\n‫وطلــب التمييــز فأجيــب لطلبــه وجــرى إفهامــه بتعليمــات االعتــراض‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                      ‫حــرر يف ‪1434/01/19‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل فضيلــة‬\n\n\n                                                                                     ‫‪384‬‬\n\f      ‫القاضــي ‪ ...‬أثنــاء تواجــده يف الــدورة التدريبيــة ففــي يــوم الثالثــاء املوافــق‬\n      ‫‪1434/03/17‬ه ـ افتتحــت اجللســة بالالئحــة االعتراضيــة املكونــة مــن‬\n      ‫صفحتــن املقيــدة برقــم ‪ 34/410226‬يف ‪1434/02/18‬ه ـ وقــد اطلــع‬\n      ‫عليهــا القاضــي ‪...‬وشــرح عليهــا بأنــه لــم يجــد بهــا مايؤثــر علــى ماحكــم‬\n      ‫بــه فقــررت بعــث املعاملــة حملكمــة االســتئناف حســب النظــام وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                             ‫حــرر يف ‪1434/03/17‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫يــوم االثنــن املوافــق ‪1434/05/27‬ه ـ افتتحــت اجللســة بعــد أن عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34201758‬‬\n      ‫وتاريــخ ‪1434/04/30‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقة علــى احلكم واهلل املوفق)‬\n      ‫قاضــي اســتئناف ‪...‬ختــم وتوقيــع قاضــي اســتئناف ‪...‬ختــم وتوقيــع رئيــس‬\n      ‫الدائــرة ‪...‬ختــم وتوقيــع عليــه فقــد أمــرت بإثباتــه علــى ضبطــه وســجله‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/27‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا احلكــم الص ــادر مــن‬\n      ‫فضي ــلة الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل‬\n      ‫بعــدد ‪ 3417544‬وتاريــخ ‪1434/1/20‬هـ ـ املتضمــن دعــوى ‪ ...‬ضــد ‪...‬يف‬\n                                                ‫أرض احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n\n\n‫‪385‬‬\n\f                 ‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق ‪.‬‬\n‫وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى آل ــه وصحب ــه وس ــلم‬\n                                            ‫‪،،،،،،،،،،،،،،‬‬\n\n\n\n\n                                                                                   ‫‪386‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":376,"source_page_end":386,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"03dcfdf24e1f75b591c7d7b6b8ff393823cd1f862dd8152356264e5e3c6e00be","normalized_text_hash":"39e7ef7758f3bc4697dceb9b4a98b7478cc534e5a4983fbdc1de7dbcf432d33a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p376-3417544"},{"id":"5a7da9e4-88ad-593e-9fba-3ea6bce3e8f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء بيت مرهون -فك الرهن مبوجب مخالصة مع املرهون له -تخلف املدعى عليه البائع وعدم معرفة عنوانه -طلب املدعى عليه عن طريق اجلهات الرسمية واجلريدة وإيقاف خدماته- القضاء بالشاهد واليمن -احلكم بثبوت أن البيت محل الدعوى ملك للمدعي -املدعي عليه الغائب على حجته متى حضر .","document_number":"261568","case_number":"33126862","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام وذكر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"عقار -شراء بيت مرهون -فك الرهن مبوجب مخالصة مع املرهون له -تخلف املدعى عليه البائع وعدم معرفة عنوانه -طلب املدعى عليه عن طريق اجلهات الرسمية واجلريدة وإيقاف خدماته- القضاء بالشاهد واليمن -احلكم بثبوت أن البيت محل الدعوى ملك للمدعي -املدعي عليه الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/8 :‬هـ َر ْق ُم‬\n                              ‫ُ‬               ‫َر ْق ُم َّ‬\n                                  ‫الص ِّك‪261568 :‬‬\n                                   ‫الدعوى‪33126862 :‬‬\n               ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                      ‫‪ 341747031‬تاريخه‪1434/11/6 :‬هـ‬\n\n\n      ‫عقــار‪ -‬شــراء بيــت مرهــون‪ -‬فــك الرهــن مبوجــب مخالصــة مــع املرهون‬\n      ‫لــه‪ -‬تخلــف املدعــى عليــه البائــع وعــدم معرفــة عنوانــه‪ -‬طلــب املدعــى‬\n      ‫عليــه عــن طريــق اجلهــات الرســمية واجلريــدة وإيقــاف خدماتــه‪-‬‬\n      ‫القضــاء بالشــاهد واليمــن ‪ -‬احلكــم بثبــوت أن البيــت محــل الدعــوى‬\n         ‫ملــك للمدعــي ‪ -‬املدعــي عليــه الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫مــا يف صحيــح مســلم مــن حديــث ابــن عبــاس رضــي اهلل عنهمــا أن النبي‬\n                                  ‫صلــى اهلل عليــه وســلم قضــى بشــاهد وميني‬\n\n\n\n      ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــترى مــن املدعــى عليــه بيت ـ ًا (‬\n      ‫ذكــر وصفــة ومســتندا التملــك) بثمــن ذكــر قــدره وانــه جــرى تســليمه‬\n      ‫ا واســتلم موكلــه البيــت يف ‪1409/1/14‬ه ـ ‪ -‬كان الصــك‬             ‫كام ـ ً‬\n      ‫مرهون ـ ًا لشــركة أرامكــو ثــم جــرى فــك الرهــن عنــه مبوجــب الصــك‬\n      ‫الصــادر مــن احملكمــة العامــة بالدمــام وذكــر رقمــه وتاريخــه‪ -‬لــم‬\n      ‫يفــرغ املدعــى عليــه البيــت واختفــي عــن األنظــار وال يعــرف لــه محــل‬\n      ‫إقامــة‪ -‬طلــب املدعــى وكالــة إفــراغ العقــار محــل الدعــوى ملوكلــه‪-‬‬\n      ‫جــرى االطــاع علــى الصــك املذكــور ورصــد مضمــون الصــك ‪ -‬جــرى‬\n      ‫االستفســار عــن ســجل صــك البيــت موضــع الدعــوى وهــو ســاري‬\n‫‪387‬‬\n\f‫املفعــول‪ -‬جــرى الكتابــة للجهــة املعنيــة للبحــث والتحــري عــن املدعــى‬\n‫عليــه وإيقــاف خدماتــه واإلعــان يف اجلريــدة‪ -‬جــرى االطــاع علــى عقــد‬\n‫البيــع ورصــد مضمونــة‪ -‬حضــر أحد شــهود العقد وشــهد بصحته‪ -‬جرى‬\n‫تعديــل الشــاهد‪ -‬حلــف املدعــى أصالــة اليمــن تكملــة لبينتــه‪ -‬أبــرز‬\n‫املدعــى ســندات قبــض الثمــن وأرفقــت صــورة مصدقــه منهــا باملعاملــة‪-‬‬\n‫بنــاء علــى ماجــاء يف الدعــوى والشــاهد املعــدل واليمــن املكملــة وعقــد‬\n‫املبايعــة وملــا يف صحيــح مســلم مــن حديــث ابــن عبــاس رضــي اهلل عنهمــا‬\n‫أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن لــذا فقــد صــدر‬\n‫احلكــم بثبــوت أن البيــت محــل الدعــوى املذكــور ملــك للمدعــي انتقلــت‬\n‫ملكيتــه إليــه مبوجــب املبايعــة املذكــورة والغائــب علــى حجتــه متــى‬\n                         ‫حضــر‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 33126862‬وتاريــخ ‪ 1433/02/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33331989‬وتاريــخ ‪ 1433/02/20‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/03/15‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬الوكيــل الشــرعي عــن ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة عــدل الدمــام الثانيــة برقــم ‪ 15363‬يف ‪1431/3/17‬ه ـ وادعــى‬\n‫علــى الغائــب عــن مجلــس احلكــم ‪...‬قائــا يف دعــواه عليــه إن موكلــي‬\n‫قــد اشــترى مــن املدعــى عليــه البيــت الواقــع علــى قطعــة األرض رقــم‬\n\n                                                                                   ‫‪388‬‬\n\f      ‫‪/222‬د مــن مخطــط ‪ 71‬بالدمــام اململــوك لــه بالصــك رقــم ‪1/904‬ش يف‬\n      ‫‪1395/9/9‬ه ـ الصــادر مــن كتابــة عــدل الدمــام بثمــن قــدره أربعمائــة‬\n      ‫ألــف ريــال وقــد اســتلم الثمــن كامــا واســتلم موكلــي البيــت يف‬\n      ‫‪1409/1/14‬ه ـ ومنــذ هــذا التاريــخ وهــو ســاكن فيــه وقــد كان الصك‬\n      ‫مرهونــا لشــركة أرامكــو ثــم جــرى فــك الرهــن عنــه مبوجــب مخالصــة‬\n      ‫بــن موكلــي والشــركة مبوجــب احلكــم الصــادر مــن احملكمــة‬\n      ‫العامــة بالدمــام برقــم ‪ 3/72‬يف ‪1427/4/23‬ه ـ إال أن املدعــى عليــه‬\n      ‫لــم يقــم بإفــراغ العقــار ملوكلــي وقــد اختفــى املدعــى عليــه ولــم نعــرف‬\n      ‫لــه محــل إقامــة وقــد خاطــب قاضــي األحســاء اجلهــات الرســمية ولــم‬\n      ‫يتوصــل إلــى محــل إقامتــه لــذا فإننــي أطلــب إفــراغ العقــار محــل الدعــوى‬\n      ‫ملوكلــي هــذه دعــواي ثــم جــرى رفــع اجللســة لدراســة املعاملــة ومخاطبــة‬\n      ‫اجلهــات الرســمية إن اقتضــى األمــر ذلــك ويف جلســة أخــرى حضــر‬\n      ‫املدعــي وكالــة وقــد جــرى الرجــوع إلــى املعاملــة فوجــدت علــى اللفــة‬\n      ‫رقــم ‪ 9‬و ‪ 10‬الصــك الصــادر مــن فضيلــة القاضــي الشــيخ ‪...‬مــن هــذه‬\n      ‫احملكمــة بالرقــم املشــار إليــه بعاليــه املتعلــق بدعــوى شــركة ‪...‬ضــد‬\n      ‫املدعــي أصالــة ‪...‬وممــا جــاء يف الصــك أن املدعــى عليــه ‪...‬اقتــرض مــن‬\n      ‫الشــركة بصفتــه أحــد موظفيهــا وبنــى البيــت محــل الدعــوى وأنــه رهــن‬\n      ‫البيــت لصالــح الشــركة ثــم باعــه علــى املدعــي هنــا قبــل ســداد القــرض‬\n      ‫وأن ‪...‬مســافر خــارج اململكــة منــذ مــدة طويلــة ويقــال أنــه هاجــر وتــرك‬\n      ‫البلــد بالكليــة وال يعــرف مــكان جهتــه وانتهــت القضيــة باصطــاح‬\n      ‫الطرفــن علــى أن يدفــع املدعــى عليــه للشــركة املدعيــة مائــة وخمســن‬\n      ‫ألــف ريــال ويكــون مخالصــة نهائيــة بينهمــا كمــا وجــدت علــى اللفــة‬\n      ‫رقــم ‪ 24‬خطــاب مديــر األحــوال املدنيــة يف األحســاء رقــم ‪ 1481‬يف‬\n\n\n‫‪389‬‬\n\f‫‪1432/12/25‬ه ـ ويتضمــن أن عنــوان املدعــى عليــه بالنظــام طرفهــم‬\n‫الدمــام حــي النخيــل كمــا وجــدت علــى اللفــة رقــم ‪ 32‬خطــاب رئيــس‬\n‫كتابــة العــدل األولــى بالدمــام رقــم ‪ 12133‬يف ‪1433/1/4‬ه ـ ويتضمــن‬\n‫أن صــك العقــار محــل الدعــوى ســاري املفعــول ملالكــه ‪ ...‬كمــا وجــدت‬\n‫علــى اللفــة رقــم ‪ 38‬خطــاب مديــر جــوازات محافظــة األحســاء رقــم ‪294‬‬\n‫يف ‪1433/1/19‬ه ـ ويتضمــن أنــه باالستفســار عــن ســفرات املذكــور لــم‬\n‫يتضــح أي معلومــات حيــث إن ســجل احلــدود غيــر موجــود لهــذا الشــخص‬\n‫حســب البرنــت املرفــق كمــا وجــدت علــى اللفــة رقــم ‪ 41‬خطــاب‬\n‫مديــر شــعبة ســجن األحســاء رقــم ‪ 2/11/927/9‬يف ‪1433/1/18‬ه ـ‬\n‫ويتضمــن أن املدعــى عليــه غيــر نزيــل لديهــم وكنــت قــد خاطبــت مديــر‬\n‫شــرطة الدمــام للبحــث عــن املذكــور والتعميــم عليــه وهــل هــو ســجني‬\n‫لديهــم فوردنــي خطابــه رقــم ‪ 2/5118/7/5/21‬يف ‪1433/3/17‬ه ـ‬\n‫ويتضمــن أن املذكــور غيــر ســجني لديهــم كمــا أنــه جــرت مخاطبــة‬\n‫أمــارة املنطقــة الشــرقية للبحــث عــن املذكــور وإيقــاف خدماتــه فتــم‬\n‫إيقافهــا مبوجــب خطــاب مديــر شــرطة الدمــام رقــم‪12812/7/5/21‬‬\n‫يف ‪1433/7/26‬ه ـ ولــم يراجــع املدعــى عليــه حتــى تاريخــه كمــا أنــه‬\n‫قــد مت اإلعــان يف جريــدة ‪...‬يف عددهــا رقــم ‪ 20034‬الصــادر يف يــوم‬\n‫الثالثــاء ‪1433/1/18‬ه ـ مــن قبــل محكمــة األحســاء ولــم يراجــع أحــد‬\n‫ومــا جــاء خبــر عــن املدعــى عليــه لــذا فقــد طلبــت البينــة مــن املدعــي‬\n‫علــى دعــواه فأبــرز عقــد مبايعــة صــادر مــن مكتــب ‪ ...‬للخدمــات‬\n‫العقاريــة ويتضمــن مايلــي ‪ :‬جنــس املبــاع ‪ :‬بيــت مكــون مــن دور واحــد‬\n‫مقــام علــى األرض رقــم ‪/222‬ب يف ‪ 71‬اســم املالــك ‪ ... :‬اســم املشــتري‬\n‫‪... :‬ومقــدار القيمــة ‪ :‬أربعمائــة ألــف ريــال‪ .‬حــدود املبــاع ‪ :‬شــرقا القطعــة‬\n\n\n                                                                                      ‫‪390‬‬\n\f      ‫رقــم ‪ 224‬شــماال القطعــة رقــم ‪ 221‬غربــا شــارع ‪15‬م جنوبــا ممــر نافــذ‬\n      ‫‪8‬م مبوجــب الصــك رقــم ‪ 33‬وتاريــخ ‪1406/6/3‬ه ـ الصــادر مــن كتابــة‬\n      ‫عــدل الدمــام كمــا تضمــن أن املبلــغ الباقــي ثالثمائــة ألــف ريــال وأول‬\n      ‫قســط يف تاريــخ ‪1409/2/2‬ه ـ انتهــى املقصــود منــه شــاهد ‪...‬شــاهد ‪...‬‬\n      ‫املشــتري البائــع وبســؤال املدعــي وكالــة عــن شــهوده قــال إن أحدهمــا‬\n      ‫تــويف رحمــه اهلل والثانــي ‪...‬الزال موجــودا وأطلــب رفــع اجللســة إلحضــاره‬\n      ‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــي أصالــة ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وأحضــرا معهمــا للشــهادة ‪...‬‬\n      ‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫قــال أشــهد أن املدعــي ‪...‬اشــترى البيــت املذكــور يف الدعــوى يف حــي‬\n      ‫‪ 71‬بالدمــام ملالكــه ‪...‬وكان ذلــك يف تاريــخ ‪1409/01/14‬ه ـ مببلــغ‬\n      ‫أربعمائــة ألــف ريــال وقــد كتبــت املبايعــة بينهمــا يف مكتبــي العقــاري‬\n      ‫بيــدي بهــذا أشــهد وعليــه أوقــع كمــا أحضــر املدعــي معدلــن لشــاهده‬\n      ‫وهمــا كل مــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬و‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وباستشــهادهما شــهدا‬\n      ‫بثقــة وعدالــة الشــاهد كمــا أبــرز املدعــي ســندات قبــض باملبالــغ التــي‬\n      ‫دفعهــا للمدعــى عليــه جــرى إرفــاق صــور منهــا مصدقــة باملعاملــة لذا فقد‬\n      ‫قــررت أخــذ ميــن املدعــي أصالــة مــع بينتــه وبعــرض اليمــن عليــه اســتعد‬\n      ‫بهــا وحلــف قائــا واهلل العظيــم عالــم الغيــب والشــهادة أننــي اشــتريت‬\n      ‫البيــت محــل الدعــوى مــن املدعــى عليــه ‪...‬بأربعمائــة ألــف ريــال ودفعتهــا‬\n      ‫لــه واهلل العظيــم هكــذا حلــف وكان قــد وردنــي كذلــك خطــاب‬\n      ‫مديــر شــرطة الدمــام رقــم ‪ 2/11600/7/5/21‬يف ‪1434/06/19‬ه ـ‬\n      ‫املتضمــن أنــه بالبحــث يف ســجالت الســجناء املودعــن شــعبة إصالحيــة‬\n\n\n‫‪391‬‬\n\f‫الدمــام لــم يعثــر علــى املذكــور ضمــن الســجناء حســب كتابهــم املرفــق‬\n‫رقــم ‪ 1547‬يف ‪1434/5/6‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n‫وبنــاء علــى شــهادة الشــاهد املعــدل شــرعا املذكــورة بعاليــه ومــا جــاء يف‬\n‫عقــد املبايعــة املشــار إليــه وملــا يف صحيــح مســلم مــن حديــث ابــن عبــاس‬\n‫رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن‬\n‫وألن املدعــي حلــف علــى صفــة مــا ذكــر بعاليــه فبنــاء علــى كل مــا‬\n‫تقــدم فقــد ثبــت لــدي أن البيــت محــل الدعــوى املذكــورة حــدوده بعاليــه‬\n‫ملــك للمدعــي ‪ ...‬انتقلــت ملكيتــه إليــه مبوجــب املبايعــة املذكــورة‬\n‫بعاليــه وبذلــك حكمــت والغائــب علــى حجتــه متــى حضــر وســيجري‬\n‫بعــث املعاملــة حملكمــة االســتئناف لتدقيقهــا كاملتبــع وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/07/04‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق‪ 1434/11/13‬ه ـ‬\n‫افتتحــت اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية برقــم ‪ 341747031‬يف ‪1434/11/6‬ه ـ وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n‫‪ 34350285‬يف ‪1434/11/4‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/11/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1747031‬ش‪ 2‬وتاريــخ‬\n‫‪1434/7/18‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة‬\n\n\n                                                                                    ‫‪392‬‬\n\f      ‫الدمــام برقــم ‪ 33/331989‬وتاريــخ ‪1434/7/16‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ‪... /‬املســجل برقــم ‪34261568‬‬\n      ‫وتاريــخ ‪1434/7/8‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة إفــراغ‬\n      ‫عقــار وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫حكــم فضيلتــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه‬\n                                                   ‫وســلم حــرر يف ‪1434/11/4‬ه ـ‬\n\n\n\n\n‫‪393‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":387,"source_page_end":393,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4adc461ef0b87bf223bc95815d7507a9d9fbba30f7635c32fdd04350b2ab4897","normalized_text_hash":"d0e2094dc13ec2b8ab1ec217146b173356c8167d8d4e174c2b913e2d4fa63223","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p387-261568"},{"id":"7b99c638-dcac-5b5e-9538-147bc90df23c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء فيا و قطعة أرض -إفراغ صوري -شراء غير املواطن لعقار وتسجيله باسم مواطن -طلب املقاصة القضائية -احلكم بإفراغ العقار للمستثمر غير مواطن املادة األولى من نظام متلك غير السعودي للعقار واستثماره","document_number":"33255495","case_number":"28505","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/18","year":"1434","subject":"عقار -شراء فيا و قطعة أرض -إفراغ صوري -شراء غير املواطن لعقار وتسجيله باسم مواطن -طلب املقاصة القضائية -احلكم بإفراغ العقار للمستثمر غير مواطن املادة األولى من نظام متلك غير السعودي للعقار واستثماره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/18 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33255495 :‬‬\n                       ‫َر ْق ُم الدعوى‪28505 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34193593‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n‫عقــار‪ -‬شــراء فيــا و قطعــة أرض ‪ -‬إفــراغ صــوري ‪ -‬شــراء غيــر املواطــن‬\n‫لعقــار وتســجيله باســم مواطــن‪ -‬طلــب املقاصــة القضائيــة‪ -‬احلكــم‬\n                                 ‫بإفــراغ العقــار للمســتثمر غيــر مواطــن‬\n\n\n\n\n           ‫املادة األولى من نظام متلك غير السعودي للعقار واستثماره‬\n\n\n\n\n‫ادعــى املدعــى وكالــة علــى املدعــى عليهــم بــأن موكلــه اشــتري عقاريــن‬\n‫متالصقــن ودفــع ثمنهمــا وســجلهما باســم مــورث املدعــى عليهــم كــون‬\n‫األجنبــي وقــت تاريــخ الشــراء ال يحــق لــه متلــك العقــار وأن العقاريــن‬\n‫املذكــوران حتــت يــد موكلــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــى وذكــر املدعــى عليــه وكالــة بــأن العقاريــن املذكوريــن ملــك‬\n‫خــاص ملــورث موكليــه وأنــه جعــل للمدعــى أصالــة حــق الســكن فقــط‬\n‫ألنــه كان شــريك ًا ملــورث موكليــه وأنــه قبــل ســبع ســنوات تقريب ـ ًا‬\n‫قــام موكلــوه بشــراء حصــة املدعــى أصالــة مــن الشــركة وترتــب عليهــا‬\n‫ضريبــة دخــل مت تســليمها ملصلحــة الــزكاة‪ -‬طلــب املدعــى عليــه وكالــة‬\n‫ألــزام املدعــى أصالــة بتســليم مبلــغ الضريبــة ملوكليــه‪ -‬قــرر املدعــى‬\n‫وكالــه أن الصحيــح مــا جــاء يف دعــواه ومســألة الضريبــة ال عالقــة لهــا‬\n\n                                                                                ‫‪394‬‬\n\f      ‫بهــذه الدعــوى وللمدعــى عليــه وكالــة إقامــه دعــوى مســتقل بهــا‪ -‬أبــرز‬\n      ‫املدعــى وكالــة أقــرار ًا خطيـ ًا منســوب ًا ملــورث املدعــى عليهــم يتضمــن أن‬\n      ‫العقاريــن موضــع الدعــوى ملــك للمدعــى‪ -‬كمــا أبــرز عقــد تنــازل صــادر‬\n      ‫مــن وكيــل املدعــى عليهــم يتضمن تنازلهم عــن العقارين موضع الدعوى‬\n      ‫حيــث ســبق أن اشــتراهما املدعــى مــن مالــه اخلــاص‪ -‬بعــرض هذيــن‬\n      ‫االقراريــن علــى املدعــي عليــه وكالــة صــادق عليــه‪ -‬جــرت الكتابــة‬\n      ‫للهيئــة العامــة لالســتثمار لإلفــادة عــن املوافقــة لتملــك املدعــى للعقاريــن‬\n      ‫املذكوريــن‪ -‬وردت اإلجابــة بأنــه ال مانــع اســتخدام املنــزل املقــام عليــه‬\n      ‫كســكن خــاص لصاحــب املصنــع ( املدعــى) صــدر احلكــم بإثبــات أن‬\n      ‫كامــل العقاريــن موضــع الدعــوى ومــا أقيــم عليهمــا مــن بنــاء هــو ملــك‬\n      ‫خــاص للمدعــى أصالــة‪ -‬لــم يقتنــع املدعــى عليهــم وكالــة‪ -‬لوحــظ علــى‬\n      ‫احلكــم مــن محكمــة االســتئناف مبالحظــات أهمهــا االستفســار عــن‬\n      ‫ســريان مفعــول الصــك وأن يكــون إثبــات التملــك باســم املصنــع ‪ -‬جــرى‬\n      ‫االستفســار عــن ســريان مفعــول الصــك‪ -‬رجــع القاضــي عــن حكمــة‬\n      ‫وثبــت لديــه متلــك املصنــع للعقاريــن املوصوفــن يف الدعــوى‪ -‬صــدق‬\n                                                   ‫احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 28505‬وتاريــخ ‪ 1430/06/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 3089594‬وتاريــخ ‪ 1430/06/13‬ه ـ و يف يــوم االحــد‬\n      ‫املوافــق ‪1432/9/7‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n\n‫‪395‬‬\n\f‫املدني رقم ‪ ...‬ورخصة محاماة رقم (‪ )26/143‬وتاريخ ‪1426/9/12‬هـ‬\n‫الوكيــل الشــرعي عــن املدعــي ‪ ...‬مبوجــب الوكالــة الشــرعية الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بالريــاض رقــم ‪ 211244000844‬وتاريــخ‬\n‫‪1430/6/6‬ه ـ وحضــر حلضــوره ‪ ...‬الوكيــل الشــرعي عــن ‪ ...‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل جــدة الثانيــة برقــم ‪ 18809‬يف ‪1428/2/27‬ه ـ جلــد ‪ 5747‬و‪...‬‬\n‫املذكــور وكل املدعــي باألصالــة عــن نفســه وبالوكالــة عــن ‪ ...‬و‬\n‫‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة الصــادرة مــن بيــروت‬\n‫برقــم ‪1424/145‬ه ـ يف ‪1424/6/29‬ه ـ واملصــادق عليهــا مــن اجلهــات‬\n‫املختصــة وادعــى االول قائــا لقــد اشــترى موكلــي فيــا بحــي ‪ ...‬بتاريــخ‬\n‫‪1413/5/30‬ه ـ واملقامــة علــى قطعــة االرض رقــم ‪ 83‬باملخطــط رقــم‬\n‫‪ 1371‬مببلــغ وقــدره مليونــا ري ـ ــال مــن مالكهــا ‪ ...‬كمــا اشــترى قطعــة‬\n‫االرض املجــاورة للقطعــة املذكــورة رقــم ‪ 82‬باملخطــط املشــار إليــه‬\n‫مببلــغ وقــدره مليــون ومئــة ألــف ريــال مــن مالكتهــا ‪ ...‬وقــد مت افــراغ‬\n‫القطعتــن املشــار إليهمــا باســم مــورث موكلــي املدعــى عليــه ‪ ...‬وذلــك‬\n                                  ‫نظــرا لكــون موكلــي أجنبــي اجلنســية‬\n\n\n\n\n                                                                                  ‫‪396‬‬\n\f      ‫ويف التاريــخ املذكــور ال يحــق لألجنبــي متلــك العقــار فتــم االفــراغ‬\n      ‫صوريــا ملــورث موكلــي املدعــى عليــه وقــد اســتلم موكلــي العقــار‬\n      ‫املذكــور يف حينــه ومــا زال حتــت يديــه وســاكن فيــه وحيــث أن‬\n      ‫التعليمــات أخيــرا جتيــز متلــك االجنبــي لــذا فإننــي أطلــب اثبــات شــراء‬\n      ‫موكلــي لالرضــن املذكورتــن ومــا اقيــم عليهــا مــن بنــاء وافــراغ‬\n      ‫االرضــن ملوكلــي هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب‬\n      ‫قائــا انــه بالرجــوع إلــى املســتندات التــي وجــدت بحــوزة موكلينــي‬\n      ‫أقــدم هــذا الــرد‪ -1‬اإلقــرار املــؤرخ يف ‪1413/05/30‬ه ـ والصــادر مــن‬\n      ‫مــورث موكلينــي أشــار فيــه صراحــة إلــى أن الفيــا مــكان االدعــاء‬\n      ‫بــأن الشــراء قــد مت مــن أمــوال الشــركة كســكن خــاص بــه حيــث‬\n      ‫كان املدعــي شــريك ًا بهــا إلــى حــن تخارجــه (مرفــق رقــم ‪ )1‬وهــي‬\n      ‫الوثيقــة الشــرعية التــي تثبــت كيفيــة إمتــام الشــراء ‪-2 .‬عقــد التنــازل‬\n      ‫عــن الفيــا املــؤرخ يف ‪1425/02/23‬ه ـ مــن وكيــل ورثــة املرحــوم ‪- ...‬‬\n      ‫لــم تتــم اإلشــارة فيــه إلــى ســند الشــراء الصــادر مــن الشــركة‪-3 .‬مت‬\n      ‫إنهــاء الشــركة مبوجــب نظــام الشــركات بعــد وفــاة مــورث موكلينــي‬\n      ‫وقامــت الشــركة بســداد كافــة االلتزامــات املاليــة التــي ترتبــت علــى‬\n      ‫التخــارج باســم جميــع الشــركاء عنــد إنهــاء هــذه الشــراكة واملدعــي‬\n      ‫علــى علــم بكافــة اجلوانــب املاليــة للشــركة واملطالبــات التــي عليهــا ‪.‬‬\n      ‫‪-4‬الشــركة قامــت بســداد مبلــغ ( ‪ ) 1.865.584‬فقــط مليــون وثمامنائــة‬\n      ‫وخمســة وســتون ألــف وخمســمائة وأربعــة وثمانــون ريــال ملصلحــة‬\n      ‫الــزكاة والدخــل مبوجــب أمــر التحصيــل ‪ 248692‬إبــراء لذمتــه مــن‬\n      ‫أمــوال الشــركة املســتحقة ملصلحــة الــزكاة والدخــل كضريبــة علــى‬\n      ‫الشــريك األجنبــي ‪-5 .‬املدعــي لــم يقــر بهــذه القيمــة املتعلقــة بالــزكاة‬\n\n\n‫‪397‬‬\n\f‫والتــي مت احتســابها مــن قبــل املصلحــة (مرفــق رقــم ‪-6 . ) 2‬علــى املدعــي‬\n‫تقــدمي البينــة التــي تثبــت ســداده لقيمــة الفيــا مــن أموالــه اخلاصــة لــذا‬\n‫فاننــي اطلــب عمــل مقاصــة قضائيــة اســتناد ًا إلــى نــص املــادة الثمانــون‬\n‫يف فقرتهــا ( أ) مــن نظــام املرافعــات الشــرعية ملطالبــة املدعــي بســداد‬\n‫مبلــغ وقــدره ( ‪ ) 1.865.584‬فقــط مليــون وثمامنائــة وخمســة وســتون‬\n‫ألــف وخمســمائة وأربعــة وثمانــون ريــال مت ســدادها عنــه ملصلحــة‬\n‫الــزكاة والدخــل للشــركة التــي ســددتها كضريبــة عــن الشــريك‬\n‫األجنبــي ‪ .‬هكــذا اجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال ان‬\n‫مــا ذكــره املدعــى عليــه يف اجابتــه دعــوى ال عالقــة لهــا باملنــزل املدعــى‬\n‫بــه وانــا ال اقــر مــا ذكــره وال انكــره وعليــه ان يتقــدم بدعــوى مســتقلة‬\n‫فبــاب الشــرع مفتــوح فجــرى افهامــه بــان عليــه االجابــة علــى مــا ذكــره‬\n‫املدعــى عليــه باجابــة مالقيــه فقــال ان جميــع مــا ذكــره املدعــى عليــه‬\n‫يف اجابتــه غيــر صحيــح والصحيــح مــا ذكرتــه يف دعــواي وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال الصحيــح مــا ذكرتــه وعندمــا مت‬\n‫شــراء حصــة مــوكل املدعــي يف الشــركة بقــي العقــار املذكــور معلقــا‬\n‫وقــد وافــق موكلــي علــى تســليم العقــار ملــوكل املدعــي اذا مت تصفيــة‬\n‫مــا بذمتــه مــن التزامــات ماليــة للدولــة وســداد االلتزامــات مــن قبــل‬\n‫الشــركة املذكــورة اعــاه وبعــرض ذلــك علــى املدعــي وكالــة قــال مــا‬\n‫ذكــره املدعــى عليــه غيــر صحيــح وبســؤال املدعــى عليــه وكالــة هــل‬\n‫لديــه بينــة علــى صحــة مــا ذكــره يف اجابتــه فقــال نعــم وســوف احضرهــا‬\n‫يف اجللســة القادمــة ويف يــوم الثالثــاء املوافــق‪ 1433/05/18‬ه ـ لــدي‬\n‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض افتتحــت اجللســة وفيهــا‬\n‫حضــر الطرفــان وبتــاوة مــا مت ضبطــه عليهمــا صادقــا عليــه وحيــث‬\n\n\n                                                                                      ‫‪398‬‬\n\f      ‫لــم تتضــح لــي اجابــة املدعــى عليــه وكالــة لــذا طلبــت منــه اإلجابــة عــن‬\n      ‫دعــوى املدعــي وكالــة فقــال إن مــا ذكــره املدعــي وكالــة يف دعــواه‬\n      ‫مــن العقاريــن الفلــة واألرض اللذيــن ذكــر موقعهمــا صحيــح وهما باســم‬\n      ‫مــورث موكلــي ومــا ذكــره أنهمــا ملــك ملوكلــه وكتبهــا باســم مــورث‬\n      ‫موكلــي ألنــه أجنبــي وال يحــق لــه التلمــك غيــر صحيــح والصحيــح أنهــا‬\n      ‫ملــك ملــورث موكلــي خالــص وإمنــا جعــل للمدعــي أصالــة حــق الســكن‬\n      ‫فيهــا فقــط ألنــه كان شــريكا ملــورث موكلــي يف شــركة ‪ ...‬وقبــل‬\n      ‫ســبع ســنوات تقريبــا قــام موكلــي بشــراء حصتــه مــن الشــركة وترتــب‬\n      ‫عليــه ضريبــة دخــل مت تســليمها ملصلحــة الــزكاه والدخــل مببلــغ قــدره‬\n      ‫مليــون وثمــان مئــة وخمــس وســتون ألــف وخمــس مئــة وأربعــة وثمانــون‬\n      ‫ريــال نطلــب الزامــه بتســليم هــذا املبلــغ ملوكلــي هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا ذكرتــه مــن متلــك موكلــي‬\n      ‫للعقاريــن املذكوريــن مــن مالــه اخلــاص ولــدي البينــة وأمــا ماذكــره مــن‬\n      ‫دفــع ضريبــة الدخــل فهــذه دعــوى مســتقلة ال عالقــة لهــا بدعــواي هكذا‬\n      ‫قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ال مانــع لــدي مــن‬\n      ‫اقامــة دعــوى مســتقلة يف مطالبتــه مببلــغ ضريبــة الدخــل واســأله البينــة‬\n      ‫علــى دعــواه وبطلــب البينــة مــن املدعــي وكالــة ابــرز أصــل ورقــة مؤرخــه‬\n      ‫يف ‪1413/5/30‬ه ـ وهــذا نصهــا اقــرار يوضــح ‪ ...‬أن صكــي الفلــة‬\n      ‫الواقعــة بحــي ‪ ...‬والتــي مت شــراؤها مــن ‪ ...‬مببلــغ ثالثــة ماليــن ريــال ومت‬\n      ‫افراغهــا لــدى كاتــب عــدل الريــاض بســجالت األرقــام التاليــة ‪4/673‬‬\n      ‫مــن ‪ 95‬جلــد وتاريــخ ‪1402/4/29‬ه ـ و ‪ /3/455‬تاريــخ ‪1401/4/26‬ه ـ‬\n      ‫أن هــذه الفلــة املقامــة علــى هاتــن القطعتــن همــا ملــك خــاص لــأخ ‪...‬‬\n      ‫أردنــي اجلنســية حيــث يعمــل معنــا شــريكا يف شــركة ‪ ...‬مت شــراؤها‬\n\n\n‫‪399‬‬\n\f‫لســكنه اخلــاص باســمنا حتــى يتــم احلصــول علــى اجــازة التملــك لــه‬\n‫مــن قبــل اجلهــات املختصــة وخوفــا مــن مفاجــأت احليــاة فإننــي اقــرر أن‬\n‫هذيــن الصكــن ملــك خالــص لــه وقــد تعهــد الرجــل بانهــاء اجــراءات‬\n‫معاملتــه مــن الداخليــة كمــا نصــت بذلــك األنظمــة كتبتــه بخــط يــدي‬\n‫وأنــا بكامــل قــواي العقليــة والبدنيــة واهلل علــى مــا أقــول شــهيد ‪...‬‬\n‫وتوقيعــه مــؤرخ يف ‪1413/5/30‬ه ـ ا‪.‬ه ـ كمــا أبــرز اصــل عقــد تنــازل‬\n‫علــى مطبوعــات مصنــع ‪ ...‬النتــاج الظــروف والبطاقــات البالســتيكية‬\n‫هــذا نصــه ( بعــون اهلل تعالــى يف هــذا اليــوم الثالثــاء املوافــق ‪/2/23‬‬\n‫‪1425‬ه ـ مت االتفــاق بــن كل مــن االطــراف التاليــة الطــرف االول ورثــة‬\n‫املرحــوم ‪ ...‬ســعودي اجلنســية مبوجــب حفيظــة النفــوس رقــم ‪ ...‬وتاريــخ‬\n‫‪1384/10/14‬ه ـ وميثلهــم الســيد ‪ ...‬ســعودي اجلنســية مبوجــب بطاقــة‬\n‫االحــوال املدنيــة رقــم ‪ ...‬وتاريــخ ‪1417/1/21‬ه ـ وكيــا عــن الورثــة‬\n    ‫مبوجــب الوكالــة رقــم ‪1424/145‬بتاريــخ ‪1424/6/29‬ه ـ واملرفــق‬\n‫صــورة منــه الطــرف الثانــي الســيد ‪ ...‬اردنــي اجلنســية مبوجــب جــواز‬\n‫ســفر رقــم ‪ ...‬وتاريــخ ‪ 2003/2/18‬واقامــة رقــم ‪ 2007214196‬صــادرة‬\n‫مــن الريــاض بتاريــخ ‪1423/7/13‬ه ـ علــى ان يتنــازل الطــرف االول عــن‬\n‫ملكيــة الفيــا القائمــة علــى مخطــط ‪ ...‬رقــم ‪ 1371‬بتاريــخ ‪1400‬ه ـ يف‬\n‫القطعتــن رقــم ‪ 83،82‬والتــي يحدهمــا مــن الغــرب القطعتــن ‪85،84‬‬\n‫ومــن اجلنــوب شــارع ‪15‬ومــن الشــرق شــارع ‪ 15‬ومــن الشــمال قطعــة رقــم‬\n‫‪ 81‬حيــث ان العقــار املشــار اليــه يف هــذا التنــازل ســبق وان اشــتراه‬\n‫الســيد ‪ ...‬مــن مالــه اخلــاص يف حيــاة املرحــوم ‪ ...‬وعلــى هــذا مت االتفــاق‬\n‫وان اهلل خيــر الشــاهدين الطــرف االول املتنــازل ورثــة املرحــوم ‪ ...‬وينــوب‬\n‫عنهــم ‪ ...‬مبوجــب صــك الوكالــة توقيعــه الطــرف الثانــي املتنــازل لــه‬\n\n\n                                                                                    ‫‪400‬‬\n\f      ‫‪ ...‬املســتثمر يف مصنــع ‪ ...‬توقيعــه وختمــه شــاهد اول ‪ ...‬توقيعــه شــاهد‬\n      ‫ثانــي ‪ ...‬توقيعــه ) ا‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‬\n      ‫االقــرار اخلطــي االول صــادر مــن مــورث موكلــي وبخــط يــده فعــا‬\n      ‫والتوقيــع توقيعــه وليــس لــدي اعتــراض عليــه ولكــن اطلــب اثبــات ان‬\n      ‫مبلــغ العقاريــن ســلم ملــورث موكلــي وقــدره ثالثــة ماليــن ريــال وامــا‬\n      ‫اقــرار التنــازل الــذي ذكــره صحيــح ايضــا وصــادر مــن موكلــي ‪...‬‬\n      ‫اصالــة عــن نفســه وبوكالتــه عــن بقيــة الورثــة وهــو مخــول يف وكالتــه‬\n      ‫بالتنــازل ولكــن كتــب هــذا التنــازل بنــاء علــى الورقــة االولــى وال زلــت‬\n      ‫اطلــب اثبــات تســليم مبلــغ العقاريــن مــن قبــل املدعــي اصالــة هكــذا‬\n      ‫قــرر هــذا وقــد ســبق الكتابــة حملافــظ الهيئــة العامــة لالســتثمار‬\n      ‫لالفــادة عــن موافقتــه علــى متلــك املدعــي اصالــة للعقاريــن املذكوريــن‬\n      ‫باخلطــاب رقــم ‪ 32/196953‬وتاريــخ ‪1432/3/13‬ه ـ فــورد جــواب‬\n      ‫وكيــل احملافــظ والرئيــس التنفيــذي للعمليــات للخطــاب رقــم ‪23888‬‬\n      ‫وتاريــخ ‪1432/4/23‬ه ـ املتضمــن بانــه ال مانــع لــدى الهيئــة العامــة مــن‬\n      ‫اســتثمار مــن متلــك مصنــع ‪ ...‬للعقــار لغــرض اســتخدام املنــزل املقــام‬\n      ‫عليــه كســكن خــاص لصاحــب املصنــع ‪ ...‬ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واالجابــة املتضمنــة انــكار املدعــى عليــه وكالــة لدعــوى‬\n      ‫املدعــي وكالــة مــن ان موكلــه متلــك العقاريــن املذكوريــن يف الدعــوى‬\n      ‫مــن مالــه اخلــاص واثبــت املدعــي وكالــة باالقــرار اخلطــي الصــادر مــن‬\n      ‫مــورث املدعــى عليهــم اصالــة املرصــود نصــه بعاليــه واملتضمــن اقــراره‬\n      ‫بــان العقاريــن املذكوريــن ملــك خالــص للمدعــي اصالــة وكذلــك مــا‬\n      ‫ابــرزه مــن تنــازل وكيــل الورثــة واقــراره بــان املدعــي اصالــة ســبق وان‬\n      ‫اشــترى العقاريــن املذكوريــن مــن مالــه اخلــاص يف حيــاة مورثهــم وهــو‬\n\n\n‫‪401‬‬\n\f‫مخــول بالتنــازل وصــادق علــى ذلــك املدعــى عليــه وكالــة وقــد جــرى‬\n‫االطــاع علــى وكالتــه املذكــور رقمهــا وتاريخهــا ووجدتهــا تخولــه‬\n‫املدافعــة واملرافعــة والتنــازل واالقــرار وملوافقــة اجلهــة املصــدرة لترخيــص‬\n‫املدعــي اصالــة وهــي الهيئــة العامــة لالســتثمار لتملكــه باســم املصنــع‬\n‫اململــوك لــه و بنــاء علــى املــادة االولــى مــن نظــام متلــك غيــر الســعوديني‬\n‫للعقــار واســتثماره لــذا فقــد ثبــت لــدي ان كامــل العقاريــن املوصوفــن‬\n‫للدعــوى ومــا اقيــم عليهمــا مــن بنــاء هــو ملــك خــاص باملدعــي اصالــة‬\n‫وبذلــك حكمــت وســيهمش علــى صــك امللكيــة بذلــك بعــد اكتســاب‬\n‫احلكــم الصفــة القطعيــة والتأكــد مــن ســريان مفعــول الصكــن مــن‬\n‫اجلهــة املصــدرة لــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة‬\n‫القناعــة واملدعــى عليــه عدمهــا وطلــب االســتئناف واجيــب لطلبــه وافهــم‬\n‫بــان لــه مــدة االعتــراض ثالثــن يومــا ابتــداء مــن اليــوم ويســقط حقــه يف‬\n‫االعتــراض بعــد انتهــاء املــدة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/05/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنني املوافق‪ 1434/01/26‬هـ افتتحت‬\n‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪331405806‬‬\n‫وتاريــخ ‪1433/7/26‬ه ـ شــرحا على خطاب رئيس محكمة االســتئناف‬\n‫رقــم ‪ 1176538‬وتاريــخ ‪1433/7/22‬ه ـ وبرفقهــا قــرار الدائــرة االولــى‬\n‫املســجل برقــم ‪ 33326610‬وتاريــخ ‪1433/7/5‬ه ـ واملتضمــن مــا نصــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة‬\n‫لوحــظ مــا يلــي اوال لــم يطلــب مــن املدعــى عليــه وكالــة حصــر ورثــة‬\n‫مــورث موكلــه وشــركاه ويــدون مضمونــه ويرفــق صــورة طبــق االصــل‬\n‫منــه باملعاملــة ثانيــا لــم يستفســر عــن ســريان مفعــول صكــوك التملــك‬\n\n\n                                                                                       ‫‪402‬‬\n\f      ‫وهــل هــي صاحلــة لالعتمــاد عليهــا يف االفــراغ ام ال ثالثــا حكــم فضيلتــه‬\n      ‫بثبــوت متلــك املدعــي للعقاريــن املوصوفــن يف الدعــوى ومــا حكــم بــه ال‬\n      ‫يتفــق مــع مــا ورده مــن الهيئــة العامــة لالســتثمار مــن ان يكــون اثبــات‬\n      ‫التملــك باســم مصنــع ‪ ...‬فعلــى فضيلتــه مالحظــة مــا ذكــر واكمــال‬\n      ‫مــا يلــزم نحــوه واهلل املوفــق ا‪.‬ه ـ وعليــه فقــد حضــر الطرفــان يف هــذه‬\n      ‫اجللســة وبطلــب صــك حصــر الورثــة مــن املدعــى عليــه وكالــة ابــرز‬\n      ‫الصــك الصــادر مــن ‪ 29/123‬وتاريــخ ‪1422/7/20‬ه ـ وانحصــار ورثتــه‬\n      ‫يف زوجتــه ‪ ...‬واوالده ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ومرفــق صــورة مصدقــة‬\n      ‫منــه يف املعاملــة وبالنســبة للمالحظــة الثانيــة فقــد جــرى االستفســار‬\n      ‫عــن ســريان مفعــول الصــك رقــم ‪1402/4/29 4/673‬ه ـ فوردنــا جــواب‬\n      ‫كتابــة العــدل االولــى برقــم ‪ 331748535‬وتاريــخ ‪1433/10/17‬هـ ـ و‬\n      ‫باالستفســار عــن الصــك رقــم ‪ 3/455‬يف ‪1401/4/26‬ه ـ وردنــا جــواب‬\n      ‫كتابــة العــدل االولــى رقــم ‪ 331748570‬وتاريــخ ‪1433/10/17‬ه ـ‬\n      ‫ووجدتهمــا انهمــا ال يــزاالن ســاريا املفعــول وبالنســبة للمالحظــة الثالثــة‬\n      ‫فلوجاهــة مــا ذكــره اصحــاب الفضيلــة فقــد رجعــت عــن حكمــي بــان‬\n      ‫العقاريــن املوصوفــن يف الدعــوى ملــك للمدعــي اصالــة وثبــت لــدي متلــك‬\n      ‫مصنــع ‪ ...‬للعقاريــن املوصوفــن يف الدعــوى وبذلــك حكمــت وبعرضــه‬\n      ‫علــى الطرفــن قنــع بــه املدعــي وكالــة وامــا املدعــى عليــه وكالــة فــا‬\n      ‫زال علــى اعتراضــه وامــرت باحلــاق ذلــك بالصــك وســجله واعادتــه مــع‬\n      ‫كامل اوراق املعاملة حملكمة االستئناف وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/26‬هـ‬\n      ‫احلمــد هلل وحــده وبعــدويف يــوم االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعه ‪ 2،30‬وقــد وردنــا خطــاب فضيلــة رئيــس احملكمــة‬\n\n\n‫‪403‬‬\n\f‫العامــه املســاعد برقــم ‪ 34547760‬وتاريــخ ‪1434/3/3‬ه ـ شــرحا علــى‬\n‫خطــاب فضيلــة رئيــس محكمــة االســتئناف املســاعد رقــم ‪34278175‬‬\n‫وتاريــخ ‪1434/2/30‬ه ـ املرفــق بــه قــرار الدائــرة احلقوقيــة االولــى رقــم‬\n‫‪ 3445567‬وتاريــخ ‪1434/2/24‬ه ـ املتضمــن ( وباالطــاع علــى مــا‬\n‫أجــاب بــه فضيلــة القاضــي وأحلقــه بذيــل الصــك وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم ‪ 33326610‬وتاريــخ ‪1433/7/5‬ه ـ يلحــظ أن فضيلتــه‬\n‫لــم يــدون مضمــون وكالتــي املدعــي واملدعــى عليــه وهــل تخوالنهمــا‬\n‫الســير يف الدعــوى واإلقــرار كمــا لوحــظ أن فضيلتــه قــال يف حيثيــات‬\n‫احلكــم ( وقــد جــرى اإلطــاع علــى وكالتــه املذكــور رقمهــا وتاريخهــا‬\n‫ووجدتهــا تخولــه املدافعــه واملرافعــه والتنــازل واإلقــرار ) ولــم يذكــر‬\n‫صراحــة الوكالــة املشــار إليهــا والبــد مــن ذلــك كمــا لوحــظ أن فضيلته‬\n‫لــم يــدون مضمــون الوكالــة رقــم ‪ 1424/145‬وتاريــخ ‪1424/6/29‬ه ـ‬\n‫فلمالحظــة ماذكــر وإحلــاق مايتــم بالضبــط والصــك وســجله وإعــادة‬\n‫املعاملــة ‪ .‬واهلل املوفــق ) ا‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة بأنــه جــرى‬\n‫إطالعــي علــى وكالــة املدعــي والتــي حتمــل الرقــم ‪21124400844‬‬\n‫وتاريــخ ‪1430/6/6‬ه ـ تخولــه املطالبــة واملرافعــة واملخاصمــة وإقامــة‬\n‫الدعــوى ضــد ‪ ...‬ولــه حــق االقــرار واإلنــكار والصلــح كمــا جــرى‬\n‫إطالعــي علــى وكالــة املدعى عليه رقــم ‪ 18809‬وتاريخ ‪1428/2/27‬هـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجــده الــذي وكلــه ‪ ...‬أصالــة عــن‬\n‫نفســه وبوكالــة عــن ‪ ...‬وأوالدهــا كل مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد‬\n‫‪ ...‬مبوجــب الوكالــة الصــادرة مــن بيــروت برقــم ‪1424/145‬ه ـ يف‬\n‫‪1424/6/29‬ه ـ واملخــول لــه فيهــا حــق املطالبــة واملدافعــة واملخاصمــة‬\n‫والصلــح والتنــازل واإلقــرار واإلنــكار وأمــا مــا مضمونــه الوكالــة رقــم‬\n\n\n                                                                                    ‫‪404‬‬\n\f      ‫‪1424/145‬ه ـ فهــو ماذكــر يف نــص الوكالــة الســابقه لــذا فلــم يظهــر‬\n      ‫لــي مايؤثــر علــى ماحكمــت بــه وأمــرت باحلــاق ذلــك يف الصــك وســجله‬\n      ‫وإعادتــه إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنــن املوافق‪1434/05/27‬ه ـ افتتحت‬\n      ‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلة الرئيس برقــم ‪ 34944208‬وتاريخ‬\n      ‫‪1434/5/11‬هـ شــرحا على خطاب فضيلة رئيس محكمة االســتئناف‬\n      ‫رقــم ‪ 34547760‬وتاريــخ ‪1434/4/6‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة‬\n      ‫االولــى املســجل برقــم ‪ 34193593‬وتاريــخ ‪1434/4/21‬ه ـ املتضمــن‬\n      ‫« وباالطــاع علــى مــا اجــاب بــه فضيلتــه علــى قرارنــا رقــم ‪3445567‬‬\n      ‫وتاريــخ ‪1434/2/24‬ه ـ تقــرر الدائــرة مــا يلــي اوال املوافقــة علــى رجوعــه‬\n      ‫عــن حكمــه املــؤرخ يف ‪1433/5/18‬ه ـ ثانيــا لــم يظهــر مــا يوجــب‬\n      ‫النقــض بعــد االجــراء االخيــر بتاريــخ ‪1434/1/26‬ه ـ « قاضــي اســتئناف‬\n      ‫‪ ...‬ختمــه وتوقيعــه قاضــي االســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪ ...‬ختمــه وتوقيعــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيق‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪34547760‬‬\n      ‫وتاريــخ ‪1434/4/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ... /‬برقــم ‪ 33255495‬وتاريخ‪1433/5/18‬ه ـ واخلــاص بدعــوى ‪... /‬‬\n      ‫وكالــة ضــد ‪ ... /‬وكالــة بشــأن مطالبــة املدعــي إثبــات شــراء موكليــه‬\n      ‫لألرضيــن املذكورتــن بالصــك واملتضمــن حكــم فضيلتــه إثبــات أن‬\n\n\n‫‪405‬‬\n\f‫كامــل العقاريــن املوصوفــن بالدعــوى ومــا أقيــم عليهمــا مــن بنــاء هــو‬\n‫ملــك خــاص باملدعــي أصالــة وبذلــك حكــم وباإلطــاع علــى مــا أجــاب‬\n‫بــه فضيلتــه علــى قرارنــا رقــم ‪ 3445567‬وتاريــخ ‪1434/2/24‬ه ـ تقــرر‬\n‫الدائــرة مــا يلــي‪ :‬أوالً‪ :‬املوافقــة علــى رجوعــه عــن حكمــه املــؤرخ يف‬\n‫‪1433/5/18‬ه ـ ‪ .‬ثاني ـاً‪ :‬لــم يظهــر مــا يوجــب النقــض بعــد اإلجــراء‬\n                                             ‫األخيــر بتاريــخ ‪1434/1/26‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪406‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":394,"source_page_end":406,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8df4ffff2bb5769c29a5e05406f2f26e5ef0e61ceec913538283d88fc94ca692","normalized_text_hash":"1be8a41e9daa3038562406c5134b58a779661da11e759ff1aae3f562df07a9d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p394-33255495"},{"id":"35bfa6e4-1718-5e12-8269-581bc313fb52","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -طلب إثبات متلك -بيع ما ال ميلك -بيع املجهول - جهالة موقع األرض -حكم برد دعوى .","document_number":"34208586","case_number":"33325715","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/07","year":"1434","subject":"عقار -طلب إثبات متلك -بيع ما ال ميلك -بيع املجهول - جهالة موقع األرض -حكم برد دعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34208586:‬تاريخه ‪1434/05/07:‬ه‬\n                        ‫رقم الدعوى ‪33325715:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34254308:‬تاريخه‪1434/06/28:‬هـ‬\n\n\n      ‫عقــار ‪ -‬طلــب إثبــات متلــك ‪ -‬بيــع مــا ال ميلــك ‪ -‬بيــع املجهــول ‪-‬‬\n                                ‫جهالــة موقــع األرض ‪ -‬حكــم بــرد دعــوى ‪.‬‬\n\n\n\n\n                         ‫قوله صلى اهلل عليه وسلم (( التبع ما ليس عندك ))‬\n\n\n\n\n      ‫دعــوى املدعــي وكالــة ضــد املدعــى عليــه أن املدعــي أصالــة قــد اشــترى‬\n      ‫مــن املدعــى عليــه أرضـ ًا موصوفــة يف نــص القضيــة مببلــغ وقــدره ســتون‬\n      ‫ألــف ريــال وبعــد قبضــه جــزء مــن الثمــن تبــن أن القطعــة متداخلــة مــع‬\n      ‫أمــاك الغيــر فتــم اســتبدالها مــع قطعــة أخــرى وطلــب املدعــى وكالــة‬\n      ‫إثبــات متلــك موكلــه لــأرض البديلــة وســوف يكمــل باقــي الثمــن ‪-‬‬\n      ‫أجــاب املدعــى عليــه أن دعــوى املدعــي وكالــة غيــر صحيحــة ‪ -‬قــرر‬\n      ‫املدعــي وكالــة أن موكلــه لــم يكــن يعلــم موقــع األرض البديلــة ‪-‬‬\n      ‫قــرر ناظــر القضيــة بــأن املدعــي وكالــة قــرر بــأن املدعــي أصالــة قــد‬\n      ‫اشــترى أرضـ ًا منزوعــة ليســت يف ملــك املدعــى عليــه وقــد قصــد أرضـ ًا‬\n      ‫غيــر معلومــة ولقولــه صلــى اهلل عليــه وســلم (( التبــع مــا ليــس عنــدك‬\n      ‫)) ونهيــه عــن بيــع املجهــول فقــد ثبــت لــدى ناظــر القضيــة بطــان بيــع‬\n      ‫األرض محــل الدعــوى ورد دعــوى املدعــي ‪ -‬قــرر املدعــي وكالــة عــدم‬\n\n‫‪407‬‬\n\f‫القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة‬\n                                                          ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة ففــي يــوم الثالثــاء املوافق‪1433/06/24‬ه ـ حضــر‬\n‫‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل عــن ‪/‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املدينــة الثانيــة برقــم‬\n‫‪ 7776/ 32743‬يف ‪1433/5/9‬ه ـ وادعــى علــى احلاضــر معــه ‪ /‬ســعودي‬\n‫ا يف دعــواه إن موكلــي قــد‬      ‫اجلنســية مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n‫اشــترى قطعــة أرض رقــم ‪........‬مــن مخطــط ‪ ........‬بثمــن قــدره ســتون‬\n‫ألــف ريــال مــن املدعــى عليــه وبعــد دفعــه جلــزء مــن الثمــن وقــدره اثنــان‬\n‫وخمســون ألــف ريــال تبــن أن القطعــة املشــار إليهــا متداخلــة مــع أمــاك‬\n‫للغيــر فتــم اســتبدالها مــن قبــل األمانــة بالقطعــة رقــم ‪........‬مــن مخطــط‬\n‫‪........‬لــذا أطلــب منكــم احلكــم بإثبــات موكلــي لــأرض املذكــورة‬\n‫علمـ ًا أن موكلــي مســتعد بدفــع الباقــي مــن الثمــن وقــدره ثمانيــة آالف‬\n‫ا مــا‬\n     ‫ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n‫ذكــره املدعــي غيــر صحيــح والصحيــح أن أخ مــوكل املدعــي حضــر‬\n‫إلــي وطلــب منــي شــراء األرض ذات الرقــم ‪........‬مــن ‪........‬لصالــح إخوانــه‬\n‫القصــر وذلــك لكونهــم بحاجــة إلــى أرض فقلــت لــه أنــه يوجــد أرض‬\n‫مخصصــة لــي يف مخطــط ‪........‬وال زالــت حتــت اإلجــراء وأرغــب يف‬\n‫بيعهــا علــى إخوانــك القصــر وبعــد ذلــك تبــن لــي أنــه يرغــب يف شــراء‬\n‫األرض ألخيــه املدعــي أصالــة وملــا علمــت بذلــك أبلغتهــم بفســخي للبيــع‬\n\n                                                                                      ‫‪408‬‬\n\f      ‫وعــدم إمتامــه علم ـ ًا أن قطعــة األرض املدعــى بهــا صــدر لهــا صــك رقــم‬\n      ‫‪ 340106006940‬يف ‪1433/5/11‬ه ـ مــن كتابــة العــدل األولــى يف‬\n      ‫املدينــة املنــورة باســم هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أفــاد‬\n      ‫ا مــا ذكــره املدعــى عليــه غيــر صحيــح هكــذا أجــاب ثــم أبــرز‬        ‫قائ ـ ً‬\n      ‫املدعــى عليــه الصــك املشــار إليــه للقطعــة املدعــى بهــا فوجــدت فيــه مــا‬\n      ‫نصــه « فــإن قطعــة األرض رقــم ‪........‬مــن املخطــط رقــم ‪/ 1‬ف ‪1411/‬‬\n      ‫الواقــع يف حــي ‪/........‬ب مبدينــة املدينــة املنــورة وحدودهــا وأطوالهــا‬\n      ‫كالتالــي ‪ :‬شــما ًال مواقــف ســيارات بطــول ‪ :‬مــن شــرق إلــى غــرب ‪12‬‬\n      ‫م اثنــي عشــر متــر ًا ثــم مبيــل خفيــف إلــى القبلــة ‪ 17.32‬م ســبعة عشــر‬\n      ‫متــر ًا واثنــان وثالثــون ســنتمتر ًا ‪ ،‬وجنوب ـاً‪ :‬شــارع بعــرض ‪ 30‬م بطــول ‪:‬‬\n      ‫‪ 27‬ســبعة وعشــرون متــر ًا ‪ ،‬وشــرق ًا ‪ :‬القطعــة رقــم ‪ 217‬بطــول ‪27.27 :‬‬\n      ‫ســبعة وعشــرون متــر ًا وســبعة وعشــرون ســنتمتر ًا وغرب ـ ًا ‪ :‬القطعــة‬\n      ‫رقــم ‪ 219‬بطــول ‪ 18.46 :‬ثمانيــة عشــر متــر ًا وســتة وأربعــون ســنتمتر ًا‬\n      ‫ومســاحتها ‪ 669.28 :‬ســتمائة وتســعة وســتون متــر ًا مربع ـ ًا وثمانيــة‬\n      ‫وعشــرون ســنتمتر ًا مربع ـ ًا فقــط واملســتند يف إفراغهــا علــى األمــر‬\n      ‫ـاء علــى قــرار التخصيــص الصــادر‬     ‫الســامي ‪........‬يف ‪1386/5/8‬ه ـ ‪ .‬وبنـ ً‬\n      ‫مــن أمــارة مدينــة املدينــة املنــورة رقــم ‪ 26872‬يف ‪1433/3/15‬ه ـ املبلــغ‬\n      ‫بخطــاب أمانــة مدينــة املدينــة املنــورة رقــم ‪........‬يف ‪1433/4/18‬ه ـ قــد‬\n      ‫أصبحــت يف ملــك ‪ /‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم وعليــه‬\n      ‫ا مــا جــاء يف‬ ‫جــرى التصديــق « أ ‪.‬ه ـ وبعرضــه علــى املدعــي أجــاب قائـ ً‬\n      ‫الصــك صحيــح ولكــن املذكــور قــد باعهــا علــى املدعــى عليــه هكــذا‬\n      ‫ا مــا ذكــره املدعــي‬    ‫أجــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫غيــر صحيــح واألرض التــزال ولــم يبعهــا علــي هكــذا أجــاب ولــذا فقــد‬\n\n\n‫‪409‬‬\n\f‫قــررت إدخــال املذكــور لســماع مــا لديــه ورفعــت اجللســة ويف جلســة‬\n‫أخــرى لــدي أنــا القاضــي يف احملكمــة العامــة باملدينــة املنــورة القائــم‬\n‫بأعمــال املكتــب القضائــي اخلامــس حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه فســألت املدعــي وكالــة هــل كان موكلــك يعلــم موقــع األرض‬\n‫التــي ستســتبدل بهــا األرض املنزوعــة والتــي مت الشــراء مــن أجلهــا قــال‬\n‫ال لــم يكــن يعلــم مكانهــا وإمنــا كان يعلــم أن األرض التــي اشــتراها‬\n‫منزوعــة لوقوعهــا يف ملــك شــخص آخــر وســيعوض عنهــا بقطعــة أخــرى‬\n‫وطلــب موكلــي هــو أن تفــرغ األرض اجلديــدة باســمه واشــترى موكلــي‬\n‫األرض املنزوعــة لقلــة ثمنهــا بســبب أنهــا منزوعــة فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة قــد ذكــر بــأن موكلــه‬\n‫اشــترى أرض ـ ًا منزوعــة ليســت يف ملــك املدعــى عليــه وقصــده أرض ـ ًا‬\n‫غيــر معلومــة ولقولــه صلــى اهلل عليــه وســلم «ال تبــع مــا ليــس عنــدك»‬\n‫ونهيــه عــن بيــع املجهــول لذلــك كلــه فقــد ثبــت لــدي أن البيــع محــل‬\n‫الدعــوى بيــع باطــل ومبوجبــه فقــد رددت دعــوى املدعــي وكالــة وأخليــت‬\n‫ســبيل املدعــى عليــه وبــه حكمــت وبعرضــه علــى الطرفــن قنــع بــه‬\n‫املدعــى عليــه ولــم يقنــع بــه املدعــي وكالــة فأفهــم مبقتضــى تعليمــات‬\n‫االســتئناف‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1434/5/5‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪،‬‬\n‫فلــدي أنــا القاضــي يف احملكمــة العامــة باملدينــة املنــورة القائــم بأعمــال‬\n‫املكتــب القضائــي اخلامــس ‪ ،‬يف يــوم الثالثــاء املوافــق ‪1434/8/9‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الواحــدة وخمــس وأربعــون دقيقــة ظهــر ًا فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف يف مكــة املكرمــة باخلطــاب‬\n\n\n                                                                                     ‫‪410‬‬\n\f      ‫رقــم ( ‪ ) 33/884087‬يف ‪1434/7/2‬ه ـ ‪ ،‬وقيــدت بأســاس احملكمــة‬\n      ‫برقــم ( ‪ ) 33/884087‬يف ‪1434/7/8‬ه ـ ‪ ،‬مرفقـ ًا بهــا اإلعــام الصادر‬\n      ‫مــن فضيلــة ناظــر القضيــة برقــم ( ‪ ) 34208586‬يف ‪1434/5/7‬ه ـ ‪،‬‬\n      ‫مظهــر ًا بالقــرار الصــادر مــن الدائرة احلقوقية األولى برقم ( ‪34254308‬‬\n      ‫) يف ‪1434/6/28‬ه ـ ‪ ،‬واملتضمــن مــا نــص احلاجــة منه مايلي‪ « /‬بدراســة‬\n      ‫احلكــم ‪ ،‬وصــورة ضبطــه ‪ ،‬والالئحــة االعتراضية ‪ ،‬تقررت باألكثرية‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬وبــاهلل تعالــى التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة املكلــف‬\n      ‫برقــم ‪ 33884087‬وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n      ‫واملســجل بعــدد ‪ 34208586‬وتاريــخ ‪1434/5/7‬هـ ـ واملتضمــن دعــوى‪/‬‬\n                                         ‫ضــد‪ /‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n      ‫باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n‫‪411‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":407,"source_page_end":411,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3f8f0a5b5c930d709873b76a7dc8583b617db65902ff90211918a9eccf0aac33","normalized_text_hash":"b74e6a5a0500ad2c48193235d05a0adfaf5cbacf1aa44e5b1d114709e82d9e35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p407-34208586"},{"id":"c5459272-5c69-50c0-933f-56c506f63ca1","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء منحة أرض مبوجب تذكره مراجعة -عدم وجود منحة -بيع املعدوم -بيع ما ال ميلك -أوامر املنح ليست من احلقوق املعنوية املجردة التي يجيز بعض احلنفية بيعها -بطان البيع ورد الثمن .","document_number":"33330892","case_number":"333676","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/7","year":"1434","subject":"عقار -شراء منحة أرض مبوجب تذكره مراجعة -عدم وجود منحة -بيع املعدوم -بيع ما ال ميلك -أوامر املنح ليست من احلقوق املعنوية املجردة التي يجيز بعض احلنفية بيعها -بطان البيع ورد الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33330892 :‬تاريخه ‪1433/7/7 :‬هـ‬\n                      ‫رقم الدعوى ‪333676 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34221029:‬تاريخه‪1434/05/25:‬هـ‬\n\n\n‫عقــار ‪ -‬شــراء منحــة أرض مبوجــب تذكــره مراجعــة ‪ -‬عــدم وجــود‬\n‫منحــة ‪ -‬بيــع املعــدوم ‪ -‬بيــع مــا ال ميلــك ‪ -‬أوامــر املنــح ليســت مــن‬\n‫احلقــوق املعنويــة املجــردة التــي يجيــز بعــض احلنفيــة بيعهــا ‪ -‬بطــان‬\n                                                       ‫البيــع ورد الثمــن ‪.‬‬\n\n\n\n\n‫حديــث حكيــم بــن حــزام أن النبــي صلــى اهلل عليــه وســلم قــال ( التبــع‬\n                                                           ‫مــا ليــس عنــدك )‬\n\n\n\n\n‫ادعــى املدعــى أنــه اشــترى مــن املدعــى عليــه أمــر منحــة أرض مبوجــب‬\n‫تذكــره مراجعــة مبوجــب العقــد املبــرم وأنــه ســلم املدعــى عليــه الثمــن‪-‬‬\n‫وأن املدعــى عليــه وعــد بإعطــاء األمــر الســامي بعــد شــهر مــن تاريــخ‬\n‫العقــد‪ -‬حيــث مضــى علــى العقــد قرابــة الســنتني لــذا طلــب املدعــى إلزام‬\n‫املدعــى عليــه بإعــادة املبلــغ الــذى اســتلمه منــه‪ -‬قــرر املدعــى عليــه بأنــه‬\n‫حضــر لــه شــخص أخــر واســمي نفســه باســم املدعــى واشــترى منــه أمــر‬\n‫املنحــة وأنــه لــم يتــم حتديــد مــده معينــة لتســليم أمــر املنحــة‪ -‬قــرر املدعــى‬\n‫عليــه أنــه غيــر مســتعد بإعــادة املبلــغ ألن البيــع مت‪ -‬قــرر املدعــى أنــه‬\n‫هــو الــذى اشــترى بنفســه والشــخص املذكــور صديقــه‪ -‬مت االطــاع‬\n\n                                                                                           ‫‪412‬‬\n\f      ‫علــى عقــد البيــع ورصــد مضمونــه‪ -‬صــادق الطرفــان علــى أن أمــر املنحــة‬\n      ‫لــم يصــدر بعــد‪ -‬نهــى النبــي صلــى اهلل عليــه وســلم عــن بيــع مــاال ميلــك‬\n      ‫وبيــع أوامــر املنــح مــن هــذا القبيــل لــذا صــدر احلكــم ببطــان عقــد‬\n      ‫البيــع املذكــور والــزام املدعــى عليــه بــأن يدفــع للمدعــى املبلــغ املدعــى‬\n      ‫بــه‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                           ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي القائــم بعمــل املكتــب‬\n      ‫الســادس عشــر يف احملكمــة العامــة بالطائــف وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة بالطائف‪/‬املكلف برقم‬\n      ‫‪ 333676‬وتاريــخ ‪ 1433/01/01‬ه ـ املقيــدة باحملكمــة برقــم ‪338478‬‬\n      ‫وتاريــخ ‪ 1433/01/01‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/03/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10 : 06‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر حلضــوره وكيــل املدعــى‬\n      ‫عليــه ‪ ...‬ســجل مدنــي ‪ ...‬وأبــرز وكالتــه الصــادرة مــن كتابــة عــدل‬\n      ‫الثانيــة بالطائــف برقــم ‪16615‬يف ‪1433/03/20‬ه ـ وادعــى قائــا لقــد‬\n      ‫اشــتريت منــه منحــة أرض مبوجــب تذكــرة مراجعــة رقــم القيــد ‪16523‬‬\n      ‫وتاريــخ ‪1431/03/10‬ه ـ ومبوجــب العقــد املبــرم بيننــا رقــم ‪ 54‬حيــث‬\n      ‫أوعدنــي بإعطائــي األمــر الســامي الكــرمي بعــد شــهر مــن تاريــخ العقــد‬\n      ‫‪1431/08/28‬ه ـ ولــم يــويف مبــا أوعدنــي هــذه دعــواي وأبــرز صــورة‬\n      ‫مــن عقــد املبايعــة متضمنــا توقيــع البائــع ‪ ...‬وتوقيــع املشــتري ‪ ...‬وأبــرز‬\n      ‫صــورة مــن تذكــرة مراجعــة طلــب أرض ســكنية باســم ‪ ...‬وبعــرض‬\n\n‫‪413‬‬\n\f‫الدعــوى علــي وكيــل املدعــى عليــه أجــاب قائــا أنــا ال أعــرف ‪ ...‬وقــد‬\n‫جاءنــي رجــل يدعــى ‪ ...‬وقــال أن ‪ ...‬يريــد شــراء منحــة أرض تخصنــي يف‬\n‫الديــوان امللكــي وقــد قمنــا ببيعــة وكتابــة ورقــة مبايعــة وأعطانــا ســبعة‬\n‫وثالثــن ألــف وخمســمائة ريــال وغيــر مســتعد بإعــادة املبلــغ لــه ألن البيــع‬\n‫مت وال أريــد فســخه ولــم نعــده بوقــت محــدد لتســليمه األرض هكــذا‬\n‫أجــاب وعليــه رفعــت القضيــة للتأمــل وحــدد بهــا موعــد يــوم اإلثنــن‬\n‫بتاريــخ ‪1433/05/24‬ه ـ الســاعة العاشــرة صباحــا واهلل املوفــق وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                            ‫يف ‪ 1433/03/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪1433/01/01‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافق‪1433/05/24‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 29‬وفيهــا حضــر‬\n‫الطرفــان وحضــر والــد املدعــى عليــه وكيلــه ‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل الطائــف الثانيــة رقــم ‪ 16615‬وتاريــخ ‪1433/03/20‬ه ـ اجللــد‬\n‫‪ 5674‬وقــال املدعــي لقــد وعدنــي املدعــى عليــه مبــا ذكــرت قبــل العقــد‬\n‫و‪ ...‬صديقــي وأخبرنــي عــن املنحــة لكنــه لــم يشــتري عنــي بــل أنــا الــذي‬\n‫اشــتريت بنفســي فقــال املدعــى عليــه لــم أعــده مبــا ذكــر والعقــد مت‬\n‫قبــل قرابــة ســنتني فلمــاذا ســكت طــوال هــذه املــدة واملنحــة ال زالــت‬\n‫يف الســرا بالديــوان وبالرجــوع للعقــد املشــار إليــه وجــدت عبــارة نصهــا‬\n‫البيعــة ورقــة منحــة وعلــى البائــع تســوية الوكالــة وبســؤال الطرفــن‬\n\n\n                                                                                     ‫‪414‬‬\n\f      ‫عــن معنــى هــذا قــال املدعــي معناهــا أن املدعــى عليــه البائــع يحضــر‬\n      ‫لــي األمــر الســامي ويعطينــي وكالــة ملتابعــة املنحــة فقــال املدعــى عليــه‬\n      ‫بــل معناهــا أنــي اعطيــه وكالــة ملتابعــة املنحــة والتــي هــي املبيــع وأمــا‬\n      ‫إحضــار األمــر الســامي فــا يلزمنــي والعقــد صريــح وقــد رضــي بــه‬\n      ‫وبســؤال املدعــي عــن بينتــه علــى أن املدعــى عليــه وعــده مبــا ذكــر قبــل‬\n      ‫العقــد وأنــه التــزم لــه بإحضــار األمــر الســامي قــال بينتــي شــهود العقــد‬\n      ‫وســأحضرهم اجللســة القادمــة فرفعــت اجللســة لذلــك وتأجلــت إلــى يــوم‬\n      ‫االثنــن املوافــق ‪1433/07/07‬ه ـ الســاعة التاســعة والنصــف وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪1433/05/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪1433/01/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم االثنــن‬\n      ‫املوافق‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا حضــر‬\n      ‫املدعــي وحضــر حلضــوره املدعــى عليــه ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬وحضــر والــد املدعــى عليــه ووكيلــه وقال املدعي‬\n      ‫لــم أمتكــن مــن إحضــار بينتــي ألنهــم مــن جماعتــه ويخشــون القطيعــة إن‬\n      ‫شــهدوا فلذلــك امتنعــوا وليــس لــدي بينــة أخــرى وال أقبــل ميــن املدعــي‬\n      ‫وهنــاك دعــوى مماثلــه مــن أخــي ضــد املدعــى عليــه لــدى القاضــي ‪...‬‬\n      ‫وقــد حكــم فيهــا علــى املدعــى عليــه ثــم أبــرز صــورة الصــك الصــادر‬\n      ‫مــن القاضــي ‪ ...‬ألخيــه ضــد املدعــى عليــه فــإذا هــو برقــم ‪33312643‬‬\n      ‫وتاريــخ ‪1433/06/23‬ه ـ ويتضمــن احلكــم غيابيــا ضــد املدعــى عليــه‬\n\n\n‫‪415‬‬\n\f‫بإعــادة املبلــغ للمدعــي وجــاء يف الدعــوى أنــه باعــه منحــه فتبــن بــأن‬\n‫الورقــة ورقــة مراجعــة للديــوان وليســت منحــه وبســؤال الطرفــن عــن‬\n‫املبيــع أفــادا بأنــه مجــرد ورقــة منحــه لــم حتصــل بعــد وعليه فبنــاء على ما‬\n‫تقــدم مــن الدعــوى املتضمنــة مصادقــة املدعــى عليــه علــى دعــوى املدعــي‬\n‫باملبايعــة علــى الصفــة املدعــى بهــا وإنــكاره االشــتراط احملــدد للمــدة‬\n‫وملــا جــاء يف احلكــم القضائــي بواقعــة مماثلــة وألن املنحــة لــم حتصــل‬\n‫بعــد فــإن بيعهــا مــن قبيــل بيــع املعــدوم كالســمك يف املــاء والطيــر يف‬\n‫الهــواء مــع عــدم القــدرة علــى تســليمها وعــدم متــام ملــك البائــع لهــا وقــد‬\n‫نهــى النبــي صلــى اهلل عليــه وســلم حكيــم بــن حــزام رضــي اهلل عنــه عــن‬\n‫ذلــك وقــال (ال تبــع مــا ليــس عنــدك) وليســت مــن قبيــل احلقــوق املعنويــة‬\n‫املجــردة التــي يجيــز بعــض احلنفيــة بيعهــا ألن احلــق غيــر معلــوم وال ثابــت‬\n‫فيهــا فهــي مــن قبيــل الغــرر وحصولهــا غيــر متيقــن وقــد نهــى النبــي صلــى‬\n‫اهلل عليــه وســلم عــن بيــع املعــدوم والغــرر ونهــى اهلل ســبحانه وتعالــى قبــل‬\n‫ذلــك عــن أكل املــال بالباطــل وعليــه فقــد حكمــت ببطــان هــذا البيــع‬\n‫وألزمــت املدعــى عليــه بــأن يــرد للمدعــي الثمــن املدعــى بــه وقــدره ســبعة‬\n‫وثالثــون ألــف وخمســمائة ريــال وبعــرض احلكــم علــى الطرفــن لــم‬\n‫يقنــع بــه املدعــي عليــه وطلــب االســتئناف وأســتعد بتقــدمي الئحــة فأجيــب‬\n‫لطلبــه وســلم صــورة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n‫يومــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1433/07/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ويف يــوم األحــد املوافق‪1433/08/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 00‬وقــد وردتنــا الالئحــة االعتراضيــة املقدمــة مــن ‪...‬‬\n\n\n                                                                                        ‫‪416‬‬\n\f      ‫واملقيــدة برقــم ‪ 331444174‬وتاريــخ ‪1433/07/30‬ه ـ واملكونــة مــن‬\n      ‫ورقــة واحــده وباإلطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت‬\n      ‫بــه وللبيــان جــرى رصــده وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪ 1433/01/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪ 1433/01/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/09/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــر وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 34297383‬وتاريــخ ‪1434/5/19‬ه ـ املرفــق معهــا قــرار رقــم‬\n      ‫‪ 34221029‬وتاريــخ ‪1434/5/25‬ه ـ املــدون علــى ظهــر الصــك املتضمــن‬\n      ‫« املوافقــة علــى احلكــم « وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/02‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫احملكمــة العامــة بالطائــف برقــم ‪ 34297383‬وتاريــخ ‪1434/05/12‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة‬\n      ‫العامــة بالطائــف املســجل برقــم ‪ 33330892‬وتاريــخ ‪1433/07/07‬ه ـ‬\n      ‫املتضمــن دعــوى ‪ ...‬ضــد ‪ ، ...‬وبدراســة الصــك وص ــورة ضبط ــه والئحتــه‬\n                      ‫اإلعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم واهلل املوفــق‪.‬‬\n                  ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم‪،،،،،‬‬\n\n\n‫‪417‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":412,"source_page_end":417,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44d84488f3aab70a260dbe7cdb13ca2dbc2e6629aab0a95755711abac0c84ee8","normalized_text_hash":"094148b4d63f950dd3dd06e6d9f3f775ec0e019525c19ceeee80c9d150b8acf6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p412-33330892"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ab01fec8-ec0f-588f-89ad-71e3e4e9cffe","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -قطعة أرض -إفراغ األب لالبن قطعة أرض للحصول على قرض صندوق التنمية العقاري -وفاة الوالد -مطالبة الورثة بإعادة األرض إلى أماك الوالد ألن البيع صوري -فقدان بينة الدعوى -عدم قبول شهادة عمودي النسب بعضهم لبعض -املثبت مق دم على النايف -صرف النظر عن الدعوى واخاء سبيل املدعى","document_number":"3458358","case_number":"3493307","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"عقار -قطعة أرض -إفراغ األب لالبن قطعة أرض للحصول على قرض صندوق التنمية العقاري -وفاة الوالد -مطالبة الورثة بإعادة األرض إلى أماك الوالد ألن البيع صوري -فقدان بينة الدعوى -عدم قبول شهادة عمودي النسب بعضهم لبعض -املثبت مق دم على النايف -صرف النظر عن الدعوى واخاء سبيل املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3458358 :‬تاريخه ‪1434/3/9 :‬هـ رقم‬\n                                ‫الدعوى ‪3493307 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 35335996‬تاريخه‪1435/7/30 :‬هـ‬\n\n\n       ‫عقــار‪ -‬قطعــة أرض ‪ -‬إفــراغ األب لالبــن قطعــة أرض للحصــول علــى‬\n       ‫قــرض صنــدوق التنميــة العقــاري ‪ -‬وفــاة الوالــد ‪ -‬مطالبــة الورثــة‬\n       ‫بإعــادة األرض إلــى أمــاك الوالــد ألن البيــع صــوري ‪ -‬فقــدان بينــة‬\n       ‫الدعــوى ‪ -‬عــدم قبــول شــهادة عمــودي النســب بعضهــم لبعــض ‪ -‬املثبــت‬\n       ‫مق ــدم علــى النــايف ‪ -‬صــرف النظــر عــن الدعــوى واخــاء ســبيل املدعــى‬\n                                                                          ‫عليهــا ‪.‬‬\n\n\n\n\n       ‫قــال صاحــب الــزاد ( ال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض‬\n                      ‫وال شــهادة أحــد الزوجــن لصاحبــة وتقبــل عليهــم )‬\n                                             ‫قاعدة‪ :‬املثبت مقدم على النايف‬\n\n\n\n       ‫ادعــت املدعيــة بــأن والدهــا ميلــك أرضــا ذكــرت وصفهــا وأنــه قــام‬\n       ‫بإفراغهــا ألخيهــا املدعــى عليــه مــن أجــل أن يأخــذ قرض ـ ًا مــن صنــدوق‬\n       ‫التنميــة العقــاري‪ -‬تــويف والدهــا ولــم يرجــع املدعــى عليــه األرض إلــى‬\n       ‫ملــك والدهمــا‪ -‬طلبــت املدعيــة إلــزام املدعــى عليــه بإعــادة هــذه األرض‬\n       ‫الــى ملــك والدهمــا‪ -‬أنكــر املدعــى عليــه مــا ذكرتــه املدعيــة ودفــع بأنه‬\n       ‫اشــتري األرض موضــع الدعــوى مــن والــدة بعشــرة أالف ريــال وســلمها‬\n\n‫‪367‬‬\n\f‫لوالــده مبوجــب صــك املبايعــة‪ -‬جــرى اإلطــاع علــى صــك املبايعــة وهــو‬\n‫مطابــق ملــا ذكــره املدعــى عليــه‪ -‬قــررت املدعيــة أن هــذا البيــع صــوري‪-‬‬\n‫جــرى ســؤال املدعيــة البينــة علــى أن البيــع صــوري‪ -‬قــررت أنــه ال بينــة‬\n‫لديهــا وطلبــت ميــن املدعــى عليــه علــى نفــي ذلــك‪ -‬حلــف املدعــى عليــه‬\n‫اليمــن‪ -‬صــدر احلكــم بصــرف النظــر عــن دعــوى املدعيــة‪ -‬قدمــت‬\n‫املدعيــة الئحــة اعتراضيــة وذكــرت يف الئحتهــا أن لديهــا بينــه علــى‬\n‫دفعهــا بــأن البيــع صــوري‪ -‬أعيــد فتــح اجللســة وأحضــرت املدعيــة‬\n‫شــاهدين أحدهمــا ابــن أختهــا والثانــي عامــل املزرعــة عنــد والدهمــا‬\n‫رحمــة اهلل وشــهدا بــأن البيــع صــوري‪ -‬قــرر املدعــى عليــه بــأن لديــة‬\n‫بينــة تشــهد بــأن البيــع حقيقــي جــرى فيــه تســليم الثمــن وليــس صوريـاً‪-‬‬\n‫احضــر ثالثــة شــهدوا ‪ -‬جــري تعديــل الشــهود‪ -‬حيــث إن بينــه املثبــت‬\n‫مقدمــه علــى بينــة النــايف قــرر فضيلــة القاضــي اســتمراره علــى حكمــه‬\n‫االول‪ -‬قــررت املدعيــة اســتمراره يف املعارضــة علــى احلكــم ‪-‬صــدق‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبع‪/‬املســاعد برقــم ‪ 3493307‬وتاريــخ ‪1434/02/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34478714‬وتاريــخ ‪ 1434/02/25‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/03/09‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 00‬‬\n‫وفيهــا حضــرت املدعيــة ‪...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم ‪...‬واملعرف بها من قبل أخيها ‪...‬ســعودي اجلنســية مبوجب الســجل‬\n\n                                                                                   ‫‪368‬‬\n\f      ‫املدنــي رقم‪......‬وحضــر حلضورهــا املدعــى عليــه ‪...‬وقــررت املدعيــة قائلــة‬\n      ‫إن والــدي ميلــك األرض الواقعــة يف شــارع األربعــن خلــف مطعــم ‪...‬وقــد‬\n      ‫قــام بإفــراغ هــذه األرض ألخــي ‪...‬ألجــل أن يأخــذ قــرض مــن صنــدوق‬\n      ‫التنميــة العقــاري ثــم تــويف والــدي ولــم يرجــع ‪...‬األرض إلــى ملــك والــدي‬\n      ‫أطلــب احلكــم عليــه وإلزامــه بإعــادة هــذه األرض إلــى أمــاك والــدي‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه عمــا ذكرتــه املدعيــة أجــاب قائــا‬\n      ‫بــأن مــا ذكرتــه املدعيــة غيــر صحيــح والصحيــح أن هــذه األرض‬\n      ‫اشــتريتها مــن والــدي مببلــغ عشــرة آالف ريــال وســلمت لوالــدي املبلــغ‬\n      ‫مبوجــب صــك املبايعــة رقم‪48‬يف‪1397/2/5‬ه ـ الصــادر مــن كتابــة‬\n      ‫عــدل ينبــع هكــذا أجــاب فجــرى منــي اإلطــاع علــى الصــك املذكــور‬\n      ‫فوجدتــه طبــق مــا ذكــر املدعــى عليــه وبعــرض ذلــك علــى املدعيــة قالــت‬\n      ‫مــا ذكــره املدعــى عليــه غيــر صحيــح والبيــع الــذي حصــل بيــع صــوري‬\n      ‫ولــم يســتلم والــدي مبلــغ األرض هكــذا قالــت فســألت املدعيــة هــل‬\n      ‫لديــك بينــة علــى أن البيــع بيعــا صوريــا وأن والــدك لــم يســتلم املبلــغ قالــت‬\n      ‫ال ‪ ،‬وأطلــب ميينــه هكــذا أجابــت وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫حلــف قائــا (واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة‬\n      ‫أن العقــار الواقــع يف شــارع األربعــن ملــك لــي اشــتريته مــن والــدي مببلــغ‬\n      ‫عشــرة آالف ريــال وســلمت املبلــغ كامــا لوالــدي) هكــذا حلــف وبنــاء‬\n      ‫علــى مــا ســبق مــن الدعــوى واإلجابــة واطالعــي علــى الصــك الصــادر‬\n      ‫مــن كتابــة عــدل ينبــع املذكــور أعــاه ومبــا أن املدعيــة لــم تقــم البينــة‬\n      ‫علــى أن البيــع صــوري وليمــن املدعــى عليــه لــذا فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعيــة وأخليــت ســبيل املدعــى عليــه هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعيــة قــررت اعتراضهــا بالئحــة‬\n\n\n‫‪369‬‬\n\f‫اعتراضيــة فأفهمــت بــأن لهــا مــدة ثالثــن يومــا تبــدأ مــن هــذا اليــوم فــإذا‬\n‫مضــت املــدة ولــم تتقــدم بشــيء فــإن احلكــم يكتســب القطعيــة ويســقط‬\n‫حقهــا يف االعتــراض فأبــدت فهمهــا لذلــك كمــا جــرى تســليمها صــورة‬\n‫مــن صــك احلكــم ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/09‬ه ـ ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق‪ 1434/04/03‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة وفيهــا حضــرت املدعيــة واملدعــى عليــه وقــد تقدمــت املدعيــة‬\n‫بالئحتهــا االعتراضيــة واملكونــة مــن ورقتــن وقــد ذكــرت أن لديهــا‬\n‫بينــات لــذا قــررت النظــر فيهــا فســألت املدعية عن بينتهــا فقالت إن لدي‬\n‫شــهود يشــهدون علــى أن البيــع صــوري وهمــا ابــن أختــي ‪...‬وعامــل مزرعــة‬\n‫والــدي ‪...‬فســألت الشــاهد ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم‪...‬واملولــود يف‪1397/2/11‬ه ـ ولــدى ســؤاله عمــا لديــه قــال أشــهد‬\n‫هلل أننــي ســمعت جــدي ‪ ...‬والــد املدعيــة واملدعــى عليــه يقــول إننــي لــم‬\n‫أبــع األرض مــدار الدعــوى علــى ابنــي ‪...‬وإمنــا أفرغــت لــه ألجــل اســتخراج‬\n‫قــرض مــن الصنــدوق العقــاري ولــم أســتلم منــه أي مبلــغ هكــذا شــهد‬\n‫كمــا جــرى ســؤال الشــاهد ‪...‬بنجالديشــي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقم‪...‬والــذي يعمــل حتــت كفالــة والــد املدعيــة واملدعــى عليــه‬\n‫عــن شــهادته فأجــاب وهــو يعــرف اللغــة العربيــة جيــدا أننــي أعمــل حتــت‬\n‫كفالــة ‪...‬مــدة ســبعة عشــر ســنة وقــد ســمعت كفيلــي يقــول إننــي لــم أبع‬\n‫علــى ابنــي ‪...‬ولــم أســتلم منــه شــيء فيمــا يخــص األرض الواقعــة بشــارع‬\n‫األربعــن هكــذا شــهد وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n‫عليــه قــال إن شــهادتهم غيــر صحيحــة وأمــا الشــاهد األول فهو ابن أختي‬\n‫ويشــهد لوالدتــه وال أقبــل شــهادته وأمــا الشــاهد الثانــي فــا يعــرف شــيئا‬\n\n\n                                                                                        ‫‪370‬‬\n\f      ‫فطلبــت مــن املدعيــة إحضــار معدلــن للشــاهد ‪...‬فأحضــرت كال مــن‬\n      ‫‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...‬و‪... ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقم‪...‬ولــدى ســؤالهما عمــا لديهمــا مــن شــهادة‬\n      ‫قــاال نشــهد بــاهلل أن الشــاهد ‪...‬بنجالديشــي اجلنســية ثقــة عــدل مقبــول‬\n      ‫الشــهادة كمــا أضافــت املدعيــة قائلــة إن مــن ضمــن الصــك الــذي قدمه‬\n      ‫املدعــى عليــه انتقــال جــزء منــه ألخــي ‪ ...‬وقــد أقــر أخــي ‪ ...‬بشــهادة أخــي‬\n      ‫املدعــى عليــه ‪...‬أن األرض مــدار الدعــوى لوالــدي أطلــب اإلطــاع علــى‬\n      ‫اإلقــرار كمــا أطلــب إحضــار شــهود املبايعــة الذيــن شــهدوا لــدى كاتــب‬\n      ‫العــدل كمــا قــرر املدعــى عليــه بــأن لديــه شــهود يشــهدون علــى صحــة‬\n      ‫املبايعــة وأن والــده اســتلم املبلــغ فطلبــت منــه إحضارهــم فوعــد بذلــك‬\n      ‫ولــذا رفعــت اجللســة ويف يــوم األحــد املوافــق‪ 1434/04/07‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09:30‬وفيهــا حضــرت املدعيــة واملدعــى عليــه وقــد‬\n      ‫أحضــر املدعــى عليــه شــهود املبايعــة لــدى كاتــب العــدل وهــم ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬واملولــود يف ‪1343/07/01‬هـ ـ‬\n      ‫ولــدى ســؤاله عمــا لديــه مــن شــهادة قــال ( أشــهد هلل اننــي شــاهدت ‪...‬‬\n      ‫وهــو يســلم والــده عشــرة آالف ريــال عنــد كاتــب العــدل وال أعلــم ســببها‬\n      ‫هكــذا شــهد ) كمــا حضــر الشــاهد ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬واملولــود يف ‪1358/07/01‬هـ ـ ويســكن يف حــي‬\n      ‫‪...‬ولــدى ســؤاله عمــا لديــه مــن شــهاده قــال ( اشــهد هلل اننــي ســمعت ‪...‬‬\n      ‫والــد املتداعــن اقــر عنــد كاتــب العــدل قائــا اننــي بعــت االرض التــي‬\n      ‫بشــارع االربعــن علــى ابنــي ‪...‬واننــي اســتلمت مبلــغ عشــرة آالف ريــال‬\n      ‫هكــذا شــهد) كمــا أحضــر الشــاهد ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬املولــود يف ‪1375/07/01‬ه ـ ومتقاعــد عــن العمــل‬\n\n\n‫‪371‬‬\n\f‫ويســكن يف ج‪ 19/‬ولــدى ســؤاله عمــا لديــه مــن شــهادة قــال ( اشــهد‬\n‫هلل اننــي ســمعت والــدي املتداعــن يقــول اننــي بعــت االرض التــي بشــارع‬\n‫االربعــن مــدار الدعــوى علــى ابنــي ‪...‬مببلــغ عشــرة آالف ريــال واننــي‬\n‫اســتلمت املبلــغ كامــا هكــذا شــهد ) وبعــرض الشــهود وشــهادتهم‬\n‫علــى املدعيــة قــال امــا الشــاهدان ‪...‬و‪...‬ال نعلــم عنهمــا شــيئا وامــا‬\n‫شــهادتهما فهــي متناقضــة وامــا الشــاهد ‪...‬فهــو زوج أختــي ‪...‬وال نقبــل‬\n‫شــهادته فطلبــت مــن املدعــى عليــه إحضــار معدلــن للشــهود فأحضــر‬\n‫‪ ......‬ســعودي اجلنســية مبوجب الســجل املدني رقم ‪...‬و‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬ولــدى ســؤاله عمــا لديهمــا قــاال نشــهد‬\n‫هلل ان الشــهود ‪...‬و‪...‬و‪...‬ثقــات عــدول مقبولــوا الشــهادة هكــذا شــهد‬\n‫وبنــاء علــى مــا ســبق مــن اعتــراض املدعيــة وإحضارهــا شــهود يشــهدون‬\n                                                                   ‫بصوريــة البيــع‬\n‫وكان أحــد الشــهود ابــن اختهــا وإلحضــار املدعــى عليــه شــهود املبايعــة‬\n‫التــي متــت عنــد كاتــب العــدل وشــاهدا آخــر وهــو زوج أختــه وألنــه ال‬\n‫تقبــل شــهادة عمــودي النســب وتقبــل عليهــم كمــا قــال صاحــب الــزاد (‬\n‫ال تقبــل شــهادة عمــودي النســب بعضهــم لبعــض وال شــهادة أحد الزوجني‬\n‫لصاحبــه وتقبــل عليهــم ) والن املثبــت مقــدم علــى الثانــي لــذا لــم يظهر لي‬\n‫ســوى مــا حكمــت بــه وبعــرض احلكــم علــى املدعيــة قــررت اعتراضهــا‬\n‫بالئحــة اعتراضيــه فأفهمتهــا بــأن لهــا مــدة ثالثــن يومــا تبــدأ مــن هــذا‬\n‫اليــوم واذا مضــت املــدة ولــم تتقــدم خاللهــا بشــيء فأنــه يســقط حقهــا يف‬\n‫طلــب االعتــراض ويكتســب احلكــم القطعيــة كمــا قــرر املدعــى عليــه‬\n‫قناعتــه باحلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/07‬ه ـ‬\n\n\n                                                                                      ‫‪372‬‬\n\f      ‫ويف يــوم اإلثنــن املوافــق‪ 1434/05/06‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرة والنصــف وقــد قدمــت املدعيــة الئحتهــا االعتراضيــة واملكونــة‬\n      ‫مــن ســت ورقــات ولــم أجــد فيهــا مــا يؤثــر علــى ماحكمــت بــه‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/05/06‬ه ـ ‪.‬‬\n      ‫ويف يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫احلاديــة عشــر وفيهــا حضــرت املدعيــة ‪ ...‬برفقــة املعــرف بهــا ‪...‬واملدعــى‬\n      ‫عليــه ‪......‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مالحظــا عليهــا‬\n      ‫بالقــرار رقــم ‪ 34245051‬يف ‪1434/6/19‬ه ـ وهــذا نــص احلاجــة منــه‬\n      ‫(وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n      ‫لناظــر القضيــة إلعــادة االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن‬\n      ‫املدعيــة ومناقشــة مــا ورد يف هــذه الالئحــة بحضــور الطرفــن مناقشــة‬\n      ‫دقيقــة وســماع مــا لــدى املدعيــة مــن إثبــات وقــد أشــارت املدعيــة أنهــا‬\n      ‫تطالــب باســم ورثــة والدهــا فهــل لديهــا حصــر ورثــة ألبيهــا ووكالــة مــن‬\n      ‫الورثــة أو أن الدعــوى خاصــة بهــا ومحاولــة الصلــح بــن األســر بواســطة‬\n      ‫أهــل اخليــر أن أمكــن واهلل املوفــق وصلــى اهلل علــى بنينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم ‪ .‬أ ‪ .‬ه ـ بختــم وتوقيــع رئيس وأعضاء الدائرة احلقوقية‬\n      ‫اخلامســة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة وجوابــا على‬\n      ‫مــا ذكــره أصحــاب الفضيلــة ســألت املدعيــة هــل هــذه الدعــوى خاصــة‬\n      ‫بــك أم عــن الورثــة فقالــت ال بــل هــي عــن نفســي وعــن بعــض الورثــة وهــم‬\n      ‫والدتــي ‪...‬وأخوانــي األشــقاء وهــم ‪...‬و‪ ...‬فطلبــت منــه إحضــار حصــر‬\n      ‫إرث والدهــا و وكاالت عــن الورثــة فوعــدت بذلــك فســألت املتداعيــن‬\n      ‫هــل ترغبــان بالصلــح فرفضــا ذلــك وملناقشــة الالئحــة وإحضــار املدعيــة‬\n\n\n‫‪373‬‬\n\f‫حلصــر الورثــة و الــوكاالت عــن الورثــة رفعــت اجللســة‪ ،‬ويف يــوم األربعــاء‬\n‫املوافــق‪ 1434/08/03‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر وفيهــا‬\n‫حضــرت املدعيــة ‪...‬واملعــرف بهــا مــن قبــل أخيهــا ‪...‬وقــد أحضــرت صــك‬\n‫حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 3351256‬وتاريــخ‬\n‫‪1433/1/29‬ه ـ واملتضمــن وفــاة ‪ ...‬يف ‪1433/1/12‬ه ـ وانحصــار ورثتــه‬\n‫يف زوجتــه ‪...‬ويف أوالده منهــا ‪...‬و‪ ...‬ويف أوالده املرزوقــن لــه مــن زوجتــه‬\n‫‪...‬واملتوفــاة قبلــه وهــم ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬كمــا جــرى االطــاع علــى‬\n‫وكالــة املدعيــة عــن أختهــا ‪ ....‬وأخيهــا ‪ ...‬مبوجــب الوكالــة الصادرة من‬\n‫كتابــة عــدل ينبــع برقــم ‪ 34975681‬يف ‪1434/7/22‬ه ـ كمــا جــرى‬\n‫االطــاع علــى وكالــة املدعيــة عــن والدتهــا ‪...‬مبوجــب الوكالــة رقــم‬\n‫‪ 34975808‬يف ‪1434/7/22‬ه ـ واملخــول لهــا يف جميــع الــوكاالت حــق‬\n‫الصلــح والتنــازل واإلبــراء واإلقــرار واملدافعــة واملرافعــة وســماع الدعــاوى‬\n‫والــرد عليهــا وقبــول األحــكام وجوابــا علــى املالحظــة األولــى فإنــه قــد‬\n‫جــرى اطالعــي علــى الالئحــة االعتراضيــة ســابقا ولــم أجــد فيهــا ما يؤثر‬\n‫علــى مــا حكمــت بــه وآمــل مــن أصحــاب الفضيلــة حفظهــم اهلل حتديــد‬\n‫املؤثــر يف الالئحــة حتــى تتــم مناقشــته هــذا مــا لــزم اجلــواب عنــه وقــررت‬\n‫بعــث املعاملــة حملكمــة االســتئناف‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ‪... /‬القاضــي باحملكمــة العامــة بينبــع املســجل‬\n‫بعــدد ‪ 3458358‬وتاريــخ ‪1434/03/09‬ه ـ املتضمــن دعــوى‪ ... /‬ضــد‪/‬‬\n\n\n                                                                                      ‫‪374‬‬\n\f      ‫‪...‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة‬\n      ‫ضبط ــه والئحتــه االعتراضيــة تق ــرر باألكثريــة املوافق ــة عل ــى احلكــم‬\n      ‫بعــد اإليضــاح األخيــر‪ .‬وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                        ‫وعل ــى آل ــه وصحب ــه وســلم ‪،،،،،،،،،‬‬\n\n\n\n\n‫‪375‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":367,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"05fc345b10188bce9cecee7f1dea4e211f0dee3cead6ed2e50b564bef55c5bd3","normalized_text_hash":"80acab14f35ec172c270c53a897a8b56ed8da86fe034024b598fd6d356b7f7e1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p367-3458358"},{"id":"8b0ef999-bc67-5edc-86c7-d1feb34ebb9a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء قطعة أرض -انطباق صكن على عقار واحد ( ازدواجية الصكوك ) -االستفسار عن الصكوك وتسلسلها -احلكم بإلغاء أحد الصكن السبقية الصك األخر قولة النبي صلى اهلل عليه وسلم حلكيم بن حزام رضي اهلل عنه التبع ماليس عنك","document_number":"3417544","case_number":"32391074","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة ...ختم وتوقيع عليه فقد أمرت بإثباته على ضبطه وسجله","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"عقار -شراء قطعة أرض -انطباق صكن على عقار واحد ( ازدواجية الصكوك ) -االستفسار عن الصكوك وتسلسلها -احلكم بإلغاء أحد الصكن السبقية الصك األخر قولة النبي صلى اهلل عليه وسلم حلكيم بن حزام رضي اهلل عنه التبع ماليس عنك","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3417544 :‬‬\n                   ‫َر ْق ُم الدعوى‪32391074 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34201758‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n‫عقــار‪ -‬شــراء قطعــة أرض ‪ -‬انطبــاق صكــن علــى عقار واحــد ( ازدواجية‬\n‫الصكــوك ) ‪ -‬االستفســار عــن الصكــوك وتسلســلها‪ -‬احلكــم بإلغاء أحد‬\n                                    ‫الصكــن الســبقية الصك األخر‬\n\n\n\n‫قولــة النبــي صلــى اهلل عليــه وســلم حلكيــم بــن حــزام رضــي اهلل عنــه‬\n                                                    ‫التبــع ماليــس عنــك‬\n\n\n\n\n‫ادعــى املدعــى بــأن مــن اجلــاري يف ملكــة قطعــة أرض ذكــر وصفهــا‬\n‫وأبــرز صــك متلكــه لهــا ‪ ،‬وتبــن أن بيــد املدعــى عليــه صــكا آخــر علــى‬\n‫ذات األرض‪ -‬طلــب املدعــى احلكــم بالغــاء صــك املدعــى عليــه‪ -‬صــادق‬\n‫املدعــى عليــه وكالــه علــى ماجــاء يف الدعــوى ودفــع بــأن موكلــه ميلــك‬\n‫األرض محــل النــزاع مبوجــب صــك صــادر مــن كتابــة العــدل‪ -‬وقــرر‬\n‫عــدم موافقتــه علــى طلــب املدعــي بالغــاء صــك موكلــه‪ -‬جــرت عــده‬\n‫مكاتبــات واستفســارات لكتابــة العــدل لبيــان تسلســل الصكــوك وما‬\n‫بنيــت عليــه‪ -‬بعــد ورود اجلــواب علــى االستفســارات املطلوبــة تبــن أن‬\n‫احــد املواطنــن بــاع األرض محــل الدعــوى مرتــن ولكــون البيــع الثانــي‬\n‫باطــل لقــول النبــي صلــى اهلل عليــه وســلم حلكيــم بن حــزام ال تبع ماليس‬\n\n                                                                                 ‫‪376‬‬\n\f      ‫عنــدك‪ -‬وهــذه الطريــق هــي التــي وصــل امللــك فيهــا للمدعــى عليــه لــذا‬\n      ‫صــدر احلكــم بعــدم اســتحقاق املدعــى عليــه لقطعــه األرض محــل النزاع‬\n      ‫وقــرر القاضــي التهميــش علــى صــك املدعــى عليــه بااللغــاء كمــا ثبــت‬\n      ‫صحــة متلــك املدعــى لقطعــة االرض محــل النــزاع‪ -‬قــرر املدعــى عليــه‬\n                       ‫عــدم القناعــة‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n      ‫برقــم ‪ 32391074‬وتاريــخ ‪ 1432/09/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 321144324‬وتاريــخ ‪ 1432/09/03‬ه ـ حضــر املدعــي ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضــوره ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬عــن ‪...‬مبوجــب الوكالــة رقــم‬\n      ‫‪ 3987‬يف ‪1433/01/12‬ه ـ فادعــى قائــا يف دعــواه إن مــن اجلــاري يف‬\n      ‫ملكــي وحتــت تصــريف قطعــة األرض رقــم ‪ / 203‬أ مــن املخطــط رقــم‬\n      ‫‪/245‬ب‪1401/‬هـ لعام ‪1401‬هـ الواقع يف حي ‪ ...‬مبحافظة جدة املسجلة‬\n      ‫بالصــك رقــم ‪ ...‬يف ‪1404/09/06‬ه ـ الصــادر مــن كتابــة العــدل األولــى‬\n      ‫مبحافظــة جــدة يحدهــا مــن الشــرق القطعــة رقــم ‪ 202‬بطــول خمســة‬\n      ‫وعشــرين متــرا ومــن الشــمال شــارع عــرض خمســة عشــر متــرا بطــول‬\n      ‫خمســة وعشــرين متــرا ومــن اجلنــوب القطعــة رقــم ‪ 208‬بطــول خمســة‬\n      ‫وعشــرين متــرا ومــن الغــرب القطعــة رقــم ‪ 204‬بطــول خمســة وعشــرين‬\n      ‫متــرا وقــد اشــتريتها مــن املدعــو ‪...‬بتاريــخ ‪1432/03/04‬ه ـ ثــم تبــن لــي‬\n\n‫‪377‬‬\n\f‫أن بيــد املدعــى عليــه صــكا صــادرا من كتابــة العدل على ذات األرض‬\n‫أطلــب احلكــم بإلغــاء صــك املدعــى عليــه هــذه دعواي وبعــرض الدعوى‬\n‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه كلــه صحيــح جملــة‬\n‫وتفصيــا ولكــن موكلــي ميلــك األرض محــل النــزاع ذاتهــا املوصوفــة يف‬\n‫دعــوى املدعــي مبوجــب الصــك رقــم ‪ ....‬يف ‪1432/07/02‬ه ـ الصــادر من‬\n‫كتابــة العــدل األولــى مبحافظــة جــدة وأمــا طلــب املدعــي إلغــاء الصــك‬\n‫فــا نوافــق عليــه هكــذا أجــاب فجــرى االطــاع علــى صكــي امللكيــة‬\n‫التــي أبرزهــا الطرفــان فوجــد أنهــا كمــا ذكــر الطرفــان فقــررت بعــث‬\n‫الصكــن الــى كتابــة العــدل األولــى مبحافظــة جــدة لتزويدنــا بصــورة‬\n‫ضوئيــة مــن ســجلهما ومــا عليهمــا مــن تهميشــات واالفــادة عــن تسلســلها‬\n‫اخللفــي مفصــا ويف جلســة اخــرى حضــر الطرفــان وقــد كانــت جــرت‬\n‫الكتابــة لفضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لتزويدنا‬\n‫بصــورة ضوئيــة مــن ســجل الصكــن ومــا عليهمــا من تهميشــات مبوجب‬\n‫خطابنــا رقــم ‪ 33137022‬يف ‪1433/01/19‬ه ـ فوردنــا خطــاب فضيلتــه‬\n‫رقــم ‪ 33207836‬يف ‪1433/02/29‬ه ـ ونــص احلاجــة منــه ( أنــه بالرجــوع‬\n‫لســجل الصــك رقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ جلــد ‪/3/119‬ت ظهــر‬\n‫أنــه يشــتمل علــى القطعــة رقــم ‪/203‬أ ضمــن املخطــط املعتمــد باللوحــة‬\n‫رقــم ‪/245‬ب‪ 1401/‬وهــو متلــك الســيد ‪...‬وعلــى ســجله عــدة شــروحات‬\n‫وهــي ‪ -1 :‬شــرح بانتقــال ملكيــة كامــل احملــدود جلهــة ‪ ... /‬بتاريــخ‬\n‫‪1428/03/15‬ه ـ ‪ -2‬شــرح بانتقــال ملكيــة احملــدود جلهــة ‪... /‬بتاريــخ‬\n‫‪1432/03/04‬ه ـ ‪ -3‬شــرح بانتقــال ملكيــة كامــل احملــدود جلهــة‬\n‫‪ ... /‬بتاريــخ ‪1432/04/16‬ه ـ ) إلــى ماجــاء فيــه (وبالرجــوع لســجل‬\n‫الصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه ـ جلــد ‪/5/46‬ت ظهــر أنــه‬\n\n\n                                                                                  ‫‪378‬‬\n\f      ‫يشــتمل علــى القطعــة رقــم ‪/203‬أ ضمــن املخطــط املعتمــد باللوحــة‬\n      ‫رقــم ‪/245‬ب‪ 1401/‬وهــو متلــك ‪...‬وعلــى ســجله شــرح بانتقــال ملكيــة‬\n      ‫كامــل احملــدود جلهــة ‪... /‬الســيد بتاريــخ ‪1425/11/29‬ه ـ ثــم انتقــل‬\n      ‫جلهــة ‪...‬بالصــك اآللــي رقــم ‪ 320205004789‬وتاريــخ ‪1432/07/02‬ه ـ‬\n      ‫وأن هــذا الصــك محجــوز مبوجــب شــرح فضيلــة رئيــس كتابــة العــدل‬\n      ‫األولــى مبحافظــة جــدة رقــم ‪ 37130‬يف ‪1432/07/03‬ه ـ املتضمــن فيــه‬\n      ‫يوقــف صــك احلاســب حلــن رفــع االزدواجيــة ) كمــا وجــد برفــق خطــاب‬\n      ‫فضيلتــه إفــادة مــن مســاعد مديــر الســجالت ونصهــا (فضيلــة رئيــس‬\n                               ‫كتابــة العــدل األولــى مبحافظــة جــدة ســلمه اهلل ‪.‬‬\n      ‫الســام عليكــم ورحمــة اهلل وبركاتــه وبعــد‪ :‬بشــأن الصــك رقــم‬\n      ‫‪ 5948‬جلــد ‪/2/119‬ت يف ‪1404/09/06‬ه ـ والــذي يتضمــن القطعــة‬\n      ‫رقــم ‪/203‬أ عليــه ازدواجيــة بالصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه ـ‬\n      ‫جلــد ‪/5/46‬ت الــذي صــدر صــك آلــي رقــم ‪ 320505004789‬يف‬\n      ‫‪1432/07/02‬ه ـ عليــه نفيــد فضيلتكــم بــأن ســبب االزدواجيــة هــو‬\n      ‫أن القطعــة ‪/203‬أ مســتنده هــو الصــك رقــم ‪ 107‬يف ‪1404/03/16‬ه ـ‬\n      ‫ولكــن اثبــت علــى ســجل الصــك رقــم ‪ 106‬يف ‪1404/03/16‬هـ مخطط‬\n      ‫‪ 3/3‬صحيفــة ‪ 37‬ومت تــدارك ذلــك مــن قبــل اللجنــة الســابقة ‪ ...‬و‪ ...‬و‪...‬‬\n      ‫ونقلــه إلــى مســتنده الصحيــح ‪ 107‬مخطــط ‪ 3/5‬صحيفــة ‪ 7‬دون ذكــر‬\n      ‫تاريــخ أمــا بخصــوص الصــك رقــم ‪ 2058‬يف ‪1425/10/29‬ه ـ جلــد‬\n      ‫‪/5/46‬ت فيســتند علــى الصــك رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ جلــد ‪1‬‬\n      ‫‪ 13/‬ومهمــش عليــه بذلــك علمــا بــأن الصــك رقــم ‪ 85‬عليــه شــرح مــن‬\n      ‫قبــل الشــيخ ‪...‬يتضمــن األتــي ‪ /‬بنــاء علــى قــرار اللجنــة رقــم ‪ 245‬يف‬\n      ‫‪1431/06/02‬ه ـ فقــد جــرى أخــذ إقــرار البائــع واملشــتري باطــن هــذا‬\n\n\n‫‪379‬‬\n\f‫الصــك علــى العــدول عــن بيــع القطــع املتبقيــة باطــن الصــك نظــرا ألنهــا‬\n‫ســبق وأن أفرغــت مــن الســابق وأن هــذا البيــع وقــع يف غيــر محلــه وذلــك‬\n‫حســبما دون صحيفــة األوراق رقــم ‪ 30،31، 29‬جلــد ‪ 13/148‬يف‬\n‫‪1432/02/15‬ه ـ انتهــى وعلــى ســجل الصــك رقــم ‪ 85‬صــور مــن قــرار‬\n‫اللجنــة ‪ 249‬يف ‪1431/06/10‬ه ـ القطعــة ‪ 203‬ليســت مــن ضمنهــا علمــا‬\n‫بــأن القطعــة ‪/203‬أ ضمــن الصــك رقــم ‪ 85‬ومهمــش علــى مســتنده مــن‬\n‫قبــل الشــيخ ‪...‬علــى املخطــط ‪ 3/5‬صحيفــة ‪ 8‬ومت علــى ســجل مســتنده‬\n‫‪ 1075‬مخطــط ‪/4/1‬ث صحيفــة ‪ 188‬شــرح مــن قبــل الشــيخ ‪...‬بالعــدول‬\n‫عــن بيــع القطــع ومــن ضمنهــا القطعــة رقــم ‪ 283‬بنــاء علــى قــرار اللجنــة‬\n‫‪ 245‬يف ‪1431/06/02‬ه ـ وحســب مــادون باإلقــرار ‪131،130،129‬‬\n‫جلــد ‪ 13/148‬يف ‪1432/02/15‬ه ـ هــذا مــا لدينــا مــن واقــع الســجالت‬\n‫طرفنــا هــذا وقــد مت وضــع صــورة مــن خطابنــا هــذا علــى ســجل الصــك‬\n‫‪ 5948‬امللحــق رواس ‪ 34‬صحيفــة ‪ 19‬ونأمــل تعميــد مــن يلــزم بعــدم‬\n‫التصــرف للصــك اآللــي ‪ 320505004789‬يف ‪1432/07/02‬ه ـ حتــى‬\n‫يتــم معاجلــة موضــوع االزدواجيــة لالطــاع والتوجيــه) كمــا وجــد مــن‬\n‫ضمــن املرفقــات صــورة مــن قــرار جلنــة دراســة الصكــوك رقــم ‪ 242‬قــي‬\n‫‪1431/06/01‬ه ـ وبعــد االطــاع عليهــا وجــد ان القطعــة محــل النــزاع‬\n‫رقــم ‪ 203‬مــن اجلــزء أ غيــر موافقــة ملســتندها ومبــا أنــه لــم يتبــن مــن هــذا‬\n‫اخلطــاب هــل مســتند هذيــن الصكــن واحــد أم ال فقــد جــرى منــا إعــادة‬\n‫مخاطبــة فضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لإلفــادة‬\n‫عــن ذلــك مبوجــب خطابنــا رقــم ‪ 33317869‬يف ‪1433/04/05‬ه ـ‬\n‫فوردنــا خطــاب فضيلتــه رقــم ‪ 33681695‬يف ‪1433/04/21‬ه ـ ونــص‬\n‫احلاجــة منــه (عليــه نفيــد فضيلتكــم أن القطعــة املــراد االستفســار‬\n\n\n                                                                                         ‫‪380‬‬\n\f      ‫عنهــا هــي القطعــة رقــم ‪/203‬أ والتــي ضمــن املخطــط املعتمــد باللوحــة‬\n      ‫رقــم ‪/245‬ب‪1401/‬ه ـ وهــي مــن ضمــن الصــك رقــم ‪ 107‬وتاريــخ‬\n      ‫‪1404/03/16‬ه ـ جلــد ‪ ، 3/1‬أن القطعــة رقــم ‪/203‬أ صــدر عليهــا‬\n      ‫صكــن وهــي كمــا يلــي‪ -1 :‬الصــك رقــم ‪ 5948‬جلــد ‪/3/119‬ت‬\n      ‫وتاريخ‪1404/09/06‬ه ـ مــن كاتــب العــدل الســابق بهــذه اإلدارة الشــيخ‬\n      ‫‪ ،... /‬وهــو الصــك األقــدم إال أنهــا لــم تهمــش علــى مســتندها الصحيــح‬\n      ‫وهــو الصــك رقــم ‪ 107‬وإمنــا همشــت عــن طريــق اخلطــأ بالصــك رقــم ‪106‬‬\n      ‫جلــد ‪ 3/1‬وتاريــخ ‪1404/03/16‬ه ـ وقــد مت تــدارك اخلطــأ عــن طريــق‬\n      ‫اللجنــة بهــذه اإلدارة فقامــت اللجنــة بتصحيــح اخلطــأ ونقــل تهميــش‬\n      ‫القطعــة مــن ســجل الصــك رقــم ‪ 106‬إلــى ســجل الصــك رقــم ‪107‬‬\n      ‫علمــا أن الصــك رقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ جلــد ‪/3/119‬ت قــد‬\n      ‫تداولتــه األيــدي بالبيــع والشــراء حتــى اســتقر يف ملــك ‪...‬وذلــك بتاريــخ‬\n      ‫‪1432/04/16‬ه ـ وال زال يف ملــك ‪...‬حتــى تاريخــه‪ -2 .‬الصــك رقــم ‪85‬‬\n      ‫وتاريــخ ‪1425/06/32‬ه ـ جلــد ‪ 13/1‬الصــادر مــن كاتــب العــدل بهــذه‬\n      ‫اإلدارة الشــيخ ‪...‬ويشــتمل علــى عــدة قطــع مــن ضمنهــا القطعــة رقــم‬\n      ‫‪/203‬ا وقــد تداولتهــا األيــدي بالبيــع والشــراء حتــى اســتقرت القطعــة‬\n      ‫يف ملــك ‪....‬بالصــك اآللــي رقــم ‪ 320505004789‬يف ‪1432/07/02‬ه ـ‬\n      ‫) ومبــا أن الصــك املدعــى عليــه يعتمــد علــى الصــك رقــم ‪ 2508‬يف‬\n      ‫‪1425/10/29‬ه ـ الــذي يعتمــد على الصك رقم ‪ 85‬يف ‪1425/06/23‬هـ‬\n      ‫ومبــا انــه لــم يتبــن مــن خطابــات كتابــة العــدل التسلســل اخللفــي للصــك‬\n      ‫رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ لــذا فقــد قــررت مخاطبــة كتابــة العــدل‬\n      ‫لإلفــادة عــن ذلــك ويف جلســة اخــرى حضــر الطرفــان وقــد كانــت جــرت‬\n      ‫الكتابــة لفضيلــة رئيــس كتابــة العــدل األولــى مبحافظــة جــدة لتوضيــح‬\n\n\n‫‪381‬‬\n\f‫التسلسل اخللفي للصك رقم ‪ 85‬يف ‪1425/06/23‬هـ مع تزويدنا بصورة‬\n‫ضوئيــة مــن ســجله ومــا عليــه مــن تهميشــات وذلــك مبوجــب خطابنــا رقــم‬\n‫‪ 331221442‬يف ‪1433/07/26‬ه ـ فوردنــا خطابهــم رقــم ‪331513548‬‬\n‫يف ‪1433/08/19‬ه ـ ونــص احلاجــة منــه ( وإن التسلســل اخللفــي للصــك‬\n‫رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ جلــد ‪ 13/1‬هــو الصــك الصــادر مــن‬\n‫احملكمــة الشــرعية الكبــرى برقــم ‪ 27‬يف ‪1400/08/10‬ه ـ جلــد‬\n‫‪ 5/1‬ونرفــق لفضيلتكــم صــورة ضوئيــة مــن ســجل الصــك رقــم ‪ 85‬يف‬\n‫‪1425/06/23‬ه ـ جلــد ‪ 13/1‬وكذلــك صــورة ضوئيــة مــن ســجل صــك‬\n‫املخطــط رقــم ‪ 107‬وتاريــخ ‪1404/03/16‬ه ـ ومــا عليهــا مــن تهميشــات‬\n‫وشــروحات باالنتقــال وكذلــك صــورة ضوئيــة مــن ســجل الصــك رقــم‬\n‫‪ 151‬وتاريــخ ‪1401/04/25‬ه ـ وصــورة ضوئيــة مــن ســجل الصــك رقــم‬\n‫‪ 141‬يف ‪1401/03/12‬ه ـ وصــورة ضوئيــة مــن ســجل الصــك رقــم ‪142‬‬\n‫يف ‪1401/03/11‬ه ـ وكذلــك صــورة ضوئيــة مــن تهميــش القطعــة رقــم‬\n‫‪/203‬أ باخلطــأ علــى ســجل الصــك رقــم ‪ 106‬وأيضــا صــورة ضوئيــة مــن‬\n‫تهميــش القطعــة رقــم ‪/203‬أ علــى ســجل الصــك الصحيــح رقــم ‪ 107‬بعد‬\n‫تعديــل اخلطــأ مــن قبــل اللجنــة كمــا نفيــد فضيلتكــم أن الصكــن‬\n‫رقــم ‪ 5948‬يف ‪/3/119‬ت والصــك رقــم ‪ 2508‬يف ‪1425/10/29‬ه جلــد‬\n‫‪/5/46‬ت والذيــن يشــتمالن علــى القطعــة رقــم ‪/203‬أ مســتندها واحــد‬\n‫وهــو الصــك رقــم ‪)107‬فجــرى االطــاع علــى الصــور الضوئيــة لســجالت‬\n‫الصكــوك املشــار إليهــا يف اخلطــاب ونــص احلاجــة منــه أعــاه فتبــن‬\n‫اآلتــي ‪ :‬أن القطعــة محــل النــزاع وهــي ذات الرقــم ‪/203‬أ مــن املخطــط‬\n‫املعتمــد باللوحــة رقــم ‪/245‬ب‪1401/‬ه ـ املســجلة بالصــك رقــم ‪ 107‬يف‬\n‫‪1404/03/16‬ه ـ قــد انتقلــت من جهــة ‪...‬إلى جهة ‪...‬يف ‪1404/03/16‬هـ‬\n\n\n                                                                                ‫‪382‬‬\n\f      ‫ثــم بيعــت وأفرغــت مرتــان ‪ -1‬بيعــت بتاريــخ ‪1404/09/06‬ه جلهــة‬\n      ‫‪...‬وصــدر بهــا صــك مســتقل برقــم ‪ 5948‬يف ‪1404/09/06‬ه ـ ثــم انتقلــت‬\n      ‫بتاريــخ ‪1428/03/15‬ه ـ جلهــة ‪ ،...‬ثــم انتقلــت بتاريــخ ‪1432/02/04‬ه ـ‬\n      ‫جلهــة ‪ ، ...‬ثــم انتقلــت أخيــرا بتاريــخ ‪1432/04/16‬ه ـ جلهــة املدعــي ‪....‬‬\n      ‫‪ -2‬بيعــت بتاريــخ ‪1425/06/23‬ه ـ مــع مجموعــة قطــع مــن املخطــط‬\n      ‫نفســه جلهــة ‪ ...‬وصــدر لهــا وللقطــع التــي بيعــت معهــا صــك برقــم ‪ 85‬يف‬\n      ‫‪1425/06/23‬هـ ثم انتقلت بتاريخ ‪1425/10/29‬هـ إلى جهة ‪ ...‬وصدر‬\n      ‫للقطعــة محــل النــزاع صــك مســتقل برقــم ‪ 2508‬يف ‪1425/10/29‬ه‬\n      ‫ثــم انتقلــت بتاريــخ ‪1425/11/29‬ه ـ جلهــة ‪...‬ثــم انتقلــت أخيــرا بتاريــخ‬\n      ‫‪1432/07/02‬ه ـ إلــى جهــة املدعــى عليــه ‪...‬وصــدر لهــذه القطعــة محــل‬\n      ‫النــزاع صــك آلــي برقــم ‪ 320205004789‬يف ‪1432/07/02‬ه ـ ( وهــو‬\n      ‫الــذي بيــد املدعــى عليــه ) كمــا تبــن أن ســبب االزدواجيــة هــو قيــام‬\n      ‫املدعــو ‪...‬ببيــع هــذه القطعــة مرتــن ‪ ،‬وأنــه عندمــا مت البيــع األول‬\n      ‫جلهــة ‪...‬لــم يهمــش علــى املســتند الصحيــح للقطعــة محــل النــزاع وهــو‬\n      ‫الصــك رقــم ‪ 107‬يف ‪1404/03/16‬ه ـ وإمنــا همــش خطــأ علــى ســجل‬\n      ‫الصــك رقــم ‪ ...‬يف ‪1404/03/16‬ه ـ مــن قبــل كتابــة العــدل ولــم يتــم‬\n      ‫تــدارك ذلــك إال بقــرار اللجنــة املختصــة بفحــص الصكــوك رقــم ‪ ...‬يف‬\n      ‫‪1431/06/02‬ه ـ كمــا أن ممــا يؤيــد ذلــك أن القطــع املباعــة مــن ‪...‬على‬\n      ‫‪....‬يف الصــك رقــم ‪ 85‬يف ‪1425/06/23‬ه ـ ‪ -‬وعددهــا إحــدى عشــرة‬\n      ‫قطعــة ‪ -‬لــم ُيفــرغ منهــا ســوى قطعتــان ‪ :‬إحداهمــا القطعــة محــل النــزاع‬\n      ‫‪ ،‬وأنــه مت التهميــش علــى ســجل هــذا الصــك بتاريــخ ‪1432/02/15‬ه ـ‬\n      ‫بأنــه ( مت أخــذ إقــرار البائــع ‪ ...‬واملشــتري ‪...‬علــى العــدول عــن بيــع القطــع‬\n      ‫املتبقيــة نظــرا ألنهــا ســبق وأن أفرغــت مــن الســابق وأن هــذا البيــع قــد‬\n\n\n‫‪383‬‬\n\f‫وقــع يف غيــر محلــه )أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبعــد االطــاع علــى خطابــات فضيلــة رئيــس كتابــة العــدل األولــى‬\n‫مبحافظــة جــدة املرصــودة أعــاه وبعــد االطــاع علــى الصــور الضوئيــة‬\n‫لســجالت الصكــوك املشــار أليهــا أعــاه كلهــا ومتعنهــا ودراســتها وملــا‬\n‫كان املدعــو ‪...‬قــد بــاع قطعــة األرض محــل النــزاع علــى املدعــو ‪...‬بتاريــخ‬\n‫‪1404/09/06‬ه ـ ثــم تناقلــت األيــدي هــذا البيــع حتــى وصــل إلــى املدعــي‬\n‫‪...‬ثــم باعهــا املدعــو ‪...‬مــرة أخــرى علــى املدعــو ‪...‬بتاريــخ ‪1425/06/23‬هـ‬\n‫ثــم تناقلــت األيــدي هــذا البيــع حتــى وصــل إلــى املدعــى عليــه ‪...‬ونظــرا‬\n‫لكــون البيــع الثانــي بيــع باطــل لكــون املدعــو ‪ ...‬قــد بــاع علــى املدعــو‬\n‫‪...‬مــاال ميلــك وقــد قــال احلبيــب صلــى اهلل عليــه وســلم حلكيــم بــن حــزام‬\n‫رضــي اهلل عنــه ( ال تبــع مــا ليــس عنــدك ) لــذا كلــه فقــد ثبــت لــدي‬\n‫عــدم اســتحقاق املدعــى عليــه أصالــة ‪...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬لقطعــة األرض محــل النــزاع وقــررت التهميــش‬\n‫علــى صكــه ذي الرقــم ‪ 320205004789‬يف ‪1432/07/02‬ه ـ الصــادر‬\n‫مــن كتابــة العــدل األولــى مبحافظــة جــدة باإللغــاء كمــا ثبــت لــدي‬\n‫صحــة متلــك املدعــي ‪...‬لقطعــة األرض محــل النــزاع ومبــا تقــدم حكمــت‬\n‫وأفهمــت املدعــى عليــه وكالــة بــأن ملوكلــه الرجــوع علــى مــن باعــه يف‬\n‫املطالبــة بالثمــن وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة‬\n‫وطلــب التمييــز فأجيــب لطلبــه وجــرى إفهامــه بتعليمــات االعتــراض‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                      ‫حــرر يف ‪1434/01/19‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل فضيلــة‬\n\n\n                                                                                     ‫‪384‬‬\n\f      ‫القاضــي ‪ ...‬أثنــاء تواجــده يف الــدورة التدريبيــة ففــي يــوم الثالثــاء املوافــق‬\n      ‫‪1434/03/17‬ه ـ افتتحــت اجللســة بالالئحــة االعتراضيــة املكونــة مــن‬\n      ‫صفحتــن املقيــدة برقــم ‪ 34/410226‬يف ‪1434/02/18‬ه ـ وقــد اطلــع‬\n      ‫عليهــا القاضــي ‪...‬وشــرح عليهــا بأنــه لــم يجــد بهــا مايؤثــر علــى ماحكــم‬\n      ‫بــه فقــررت بعــث املعاملــة حملكمــة االســتئناف حســب النظــام وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                             ‫حــرر يف ‪1434/03/17‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫يــوم االثنــن املوافــق ‪1434/05/27‬ه ـ افتتحــت اجللســة بعــد أن عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34201758‬‬\n      ‫وتاريــخ ‪1434/04/30‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقة علــى احلكم واهلل املوفق)‬\n      ‫قاضــي اســتئناف ‪...‬ختــم وتوقيــع قاضــي اســتئناف ‪...‬ختــم وتوقيــع رئيــس‬\n      ‫الدائــرة ‪...‬ختــم وتوقيــع عليــه فقــد أمــرت بإثباتــه علــى ضبطــه وســجله‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/27‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا احلكــم الص ــادر مــن‬\n      ‫فضي ــلة الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل‬\n      ‫بعــدد ‪ 3417544‬وتاريــخ ‪1434/1/20‬هـ ـ املتضمــن دعــوى ‪ ...‬ضــد ‪...‬يف‬\n                                                ‫أرض احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n\n\n‫‪385‬‬\n\f                 ‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق ‪.‬‬\n‫وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى آل ــه وصحب ــه وس ــلم‬\n                                            ‫‪،،،،،،،،،،،،،،‬‬\n\n\n\n\n                                                                                   ‫‪386‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":376,"source_page_end":386,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"03dcfdf24e1f75b591c7d7b6b8ff393823cd1f862dd8152356264e5e3c6e00be","normalized_text_hash":"39e7ef7758f3bc4697dceb9b4a98b7478cc534e5a4983fbdc1de7dbcf432d33a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p376-3417544"},{"id":"5a7da9e4-88ad-593e-9fba-3ea6bce3e8f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء بيت مرهون -فك الرهن مبوجب مخالصة مع املرهون له -تخلف املدعى عليه البائع وعدم معرفة عنوانه -طلب املدعى عليه عن طريق اجلهات الرسمية واجلريدة وإيقاف خدماته- القضاء بالشاهد واليمن -احلكم بثبوت أن البيت محل الدعوى ملك للمدعي -املدعي عليه الغائب على حجته متى حضر .","document_number":"261568","case_number":"33126862","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام وذكر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"عقار -شراء بيت مرهون -فك الرهن مبوجب مخالصة مع املرهون له -تخلف املدعى عليه البائع وعدم معرفة عنوانه -طلب املدعى عليه عن طريق اجلهات الرسمية واجلريدة وإيقاف خدماته- القضاء بالشاهد واليمن -احلكم بثبوت أن البيت محل الدعوى ملك للمدعي -املدعي عليه الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/8 :‬هـ َر ْق ُم‬\n                              ‫ُ‬               ‫َر ْق ُم َّ‬\n                                  ‫الص ِّك‪261568 :‬‬\n                                   ‫الدعوى‪33126862 :‬‬\n               ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                      ‫‪ 341747031‬تاريخه‪1434/11/6 :‬هـ‬\n\n\n      ‫عقــار‪ -‬شــراء بيــت مرهــون‪ -‬فــك الرهــن مبوجــب مخالصــة مــع املرهون‬\n      ‫لــه‪ -‬تخلــف املدعــى عليــه البائــع وعــدم معرفــة عنوانــه‪ -‬طلــب املدعــى‬\n      ‫عليــه عــن طريــق اجلهــات الرســمية واجلريــدة وإيقــاف خدماتــه‪-‬‬\n      ‫القضــاء بالشــاهد واليمــن ‪ -‬احلكــم بثبــوت أن البيــت محــل الدعــوى‬\n         ‫ملــك للمدعــي ‪ -‬املدعــي عليــه الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫مــا يف صحيــح مســلم مــن حديــث ابــن عبــاس رضــي اهلل عنهمــا أن النبي‬\n                                  ‫صلــى اهلل عليــه وســلم قضــى بشــاهد وميني‬\n\n\n\n      ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــترى مــن املدعــى عليــه بيت ـ ًا (‬\n      ‫ذكــر وصفــة ومســتندا التملــك) بثمــن ذكــر قــدره وانــه جــرى تســليمه‬\n      ‫ا واســتلم موكلــه البيــت يف ‪1409/1/14‬ه ـ ‪ -‬كان الصــك‬             ‫كام ـ ً‬\n      ‫مرهون ـ ًا لشــركة أرامكــو ثــم جــرى فــك الرهــن عنــه مبوجــب الصــك‬\n      ‫الصــادر مــن احملكمــة العامــة بالدمــام وذكــر رقمــه وتاريخــه‪ -‬لــم‬\n      ‫يفــرغ املدعــى عليــه البيــت واختفــي عــن األنظــار وال يعــرف لــه محــل‬\n      ‫إقامــة‪ -‬طلــب املدعــى وكالــة إفــراغ العقــار محــل الدعــوى ملوكلــه‪-‬‬\n      ‫جــرى االطــاع علــى الصــك املذكــور ورصــد مضمــون الصــك ‪ -‬جــرى‬\n      ‫االستفســار عــن ســجل صــك البيــت موضــع الدعــوى وهــو ســاري‬\n‫‪387‬‬\n\f‫املفعــول‪ -‬جــرى الكتابــة للجهــة املعنيــة للبحــث والتحــري عــن املدعــى‬\n‫عليــه وإيقــاف خدماتــه واإلعــان يف اجلريــدة‪ -‬جــرى االطــاع علــى عقــد‬\n‫البيــع ورصــد مضمونــة‪ -‬حضــر أحد شــهود العقد وشــهد بصحته‪ -‬جرى‬\n‫تعديــل الشــاهد‪ -‬حلــف املدعــى أصالــة اليمــن تكملــة لبينتــه‪ -‬أبــرز‬\n‫املدعــى ســندات قبــض الثمــن وأرفقــت صــورة مصدقــه منهــا باملعاملــة‪-‬‬\n‫بنــاء علــى ماجــاء يف الدعــوى والشــاهد املعــدل واليمــن املكملــة وعقــد‬\n‫املبايعــة وملــا يف صحيــح مســلم مــن حديــث ابــن عبــاس رضــي اهلل عنهمــا‬\n‫أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن لــذا فقــد صــدر‬\n‫احلكــم بثبــوت أن البيــت محــل الدعــوى املذكــور ملــك للمدعــي انتقلــت‬\n‫ملكيتــه إليــه مبوجــب املبايعــة املذكــورة والغائــب علــى حجتــه متــى‬\n                         ‫حضــر‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 33126862‬وتاريــخ ‪ 1433/02/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33331989‬وتاريــخ ‪ 1433/02/20‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/03/15‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬الوكيــل الشــرعي عــن ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة عــدل الدمــام الثانيــة برقــم ‪ 15363‬يف ‪1431/3/17‬ه ـ وادعــى‬\n‫علــى الغائــب عــن مجلــس احلكــم ‪...‬قائــا يف دعــواه عليــه إن موكلــي‬\n‫قــد اشــترى مــن املدعــى عليــه البيــت الواقــع علــى قطعــة األرض رقــم‬\n\n                                                                                   ‫‪388‬‬\n\f      ‫‪/222‬د مــن مخطــط ‪ 71‬بالدمــام اململــوك لــه بالصــك رقــم ‪1/904‬ش يف‬\n      ‫‪1395/9/9‬ه ـ الصــادر مــن كتابــة عــدل الدمــام بثمــن قــدره أربعمائــة‬\n      ‫ألــف ريــال وقــد اســتلم الثمــن كامــا واســتلم موكلــي البيــت يف‬\n      ‫‪1409/1/14‬ه ـ ومنــذ هــذا التاريــخ وهــو ســاكن فيــه وقــد كان الصك‬\n      ‫مرهونــا لشــركة أرامكــو ثــم جــرى فــك الرهــن عنــه مبوجــب مخالصــة‬\n      ‫بــن موكلــي والشــركة مبوجــب احلكــم الصــادر مــن احملكمــة‬\n      ‫العامــة بالدمــام برقــم ‪ 3/72‬يف ‪1427/4/23‬ه ـ إال أن املدعــى عليــه‬\n      ‫لــم يقــم بإفــراغ العقــار ملوكلــي وقــد اختفــى املدعــى عليــه ولــم نعــرف‬\n      ‫لــه محــل إقامــة وقــد خاطــب قاضــي األحســاء اجلهــات الرســمية ولــم‬\n      ‫يتوصــل إلــى محــل إقامتــه لــذا فإننــي أطلــب إفــراغ العقــار محــل الدعــوى‬\n      ‫ملوكلــي هــذه دعــواي ثــم جــرى رفــع اجللســة لدراســة املعاملــة ومخاطبــة‬\n      ‫اجلهــات الرســمية إن اقتضــى األمــر ذلــك ويف جلســة أخــرى حضــر‬\n      ‫املدعــي وكالــة وقــد جــرى الرجــوع إلــى املعاملــة فوجــدت علــى اللفــة‬\n      ‫رقــم ‪ 9‬و ‪ 10‬الصــك الصــادر مــن فضيلــة القاضــي الشــيخ ‪...‬مــن هــذه‬\n      ‫احملكمــة بالرقــم املشــار إليــه بعاليــه املتعلــق بدعــوى شــركة ‪...‬ضــد‬\n      ‫املدعــي أصالــة ‪...‬وممــا جــاء يف الصــك أن املدعــى عليــه ‪...‬اقتــرض مــن‬\n      ‫الشــركة بصفتــه أحــد موظفيهــا وبنــى البيــت محــل الدعــوى وأنــه رهــن‬\n      ‫البيــت لصالــح الشــركة ثــم باعــه علــى املدعــي هنــا قبــل ســداد القــرض‬\n      ‫وأن ‪...‬مســافر خــارج اململكــة منــذ مــدة طويلــة ويقــال أنــه هاجــر وتــرك‬\n      ‫البلــد بالكليــة وال يعــرف مــكان جهتــه وانتهــت القضيــة باصطــاح‬\n      ‫الطرفــن علــى أن يدفــع املدعــى عليــه للشــركة املدعيــة مائــة وخمســن‬\n      ‫ألــف ريــال ويكــون مخالصــة نهائيــة بينهمــا كمــا وجــدت علــى اللفــة‬\n      ‫رقــم ‪ 24‬خطــاب مديــر األحــوال املدنيــة يف األحســاء رقــم ‪ 1481‬يف‬\n\n\n‫‪389‬‬\n\f‫‪1432/12/25‬ه ـ ويتضمــن أن عنــوان املدعــى عليــه بالنظــام طرفهــم‬\n‫الدمــام حــي النخيــل كمــا وجــدت علــى اللفــة رقــم ‪ 32‬خطــاب رئيــس‬\n‫كتابــة العــدل األولــى بالدمــام رقــم ‪ 12133‬يف ‪1433/1/4‬ه ـ ويتضمــن‬\n‫أن صــك العقــار محــل الدعــوى ســاري املفعــول ملالكــه ‪ ...‬كمــا وجــدت‬\n‫علــى اللفــة رقــم ‪ 38‬خطــاب مديــر جــوازات محافظــة األحســاء رقــم ‪294‬‬\n‫يف ‪1433/1/19‬ه ـ ويتضمــن أنــه باالستفســار عــن ســفرات املذكــور لــم‬\n‫يتضــح أي معلومــات حيــث إن ســجل احلــدود غيــر موجــود لهــذا الشــخص‬\n‫حســب البرنــت املرفــق كمــا وجــدت علــى اللفــة رقــم ‪ 41‬خطــاب‬\n‫مديــر شــعبة ســجن األحســاء رقــم ‪ 2/11/927/9‬يف ‪1433/1/18‬ه ـ‬\n‫ويتضمــن أن املدعــى عليــه غيــر نزيــل لديهــم وكنــت قــد خاطبــت مديــر‬\n‫شــرطة الدمــام للبحــث عــن املذكــور والتعميــم عليــه وهــل هــو ســجني‬\n‫لديهــم فوردنــي خطابــه رقــم ‪ 2/5118/7/5/21‬يف ‪1433/3/17‬ه ـ‬\n‫ويتضمــن أن املذكــور غيــر ســجني لديهــم كمــا أنــه جــرت مخاطبــة‬\n‫أمــارة املنطقــة الشــرقية للبحــث عــن املذكــور وإيقــاف خدماتــه فتــم‬\n‫إيقافهــا مبوجــب خطــاب مديــر شــرطة الدمــام رقــم‪12812/7/5/21‬‬\n‫يف ‪1433/7/26‬ه ـ ولــم يراجــع املدعــى عليــه حتــى تاريخــه كمــا أنــه‬\n‫قــد مت اإلعــان يف جريــدة ‪...‬يف عددهــا رقــم ‪ 20034‬الصــادر يف يــوم‬\n‫الثالثــاء ‪1433/1/18‬ه ـ مــن قبــل محكمــة األحســاء ولــم يراجــع أحــد‬\n‫ومــا جــاء خبــر عــن املدعــى عليــه لــذا فقــد طلبــت البينــة مــن املدعــي‬\n‫علــى دعــواه فأبــرز عقــد مبايعــة صــادر مــن مكتــب ‪ ...‬للخدمــات‬\n‫العقاريــة ويتضمــن مايلــي ‪ :‬جنــس املبــاع ‪ :‬بيــت مكــون مــن دور واحــد‬\n‫مقــام علــى األرض رقــم ‪/222‬ب يف ‪ 71‬اســم املالــك ‪ ... :‬اســم املشــتري‬\n‫‪... :‬ومقــدار القيمــة ‪ :‬أربعمائــة ألــف ريــال‪ .‬حــدود املبــاع ‪ :‬شــرقا القطعــة‬\n\n\n                                                                                      ‫‪390‬‬\n\f      ‫رقــم ‪ 224‬شــماال القطعــة رقــم ‪ 221‬غربــا شــارع ‪15‬م جنوبــا ممــر نافــذ‬\n      ‫‪8‬م مبوجــب الصــك رقــم ‪ 33‬وتاريــخ ‪1406/6/3‬ه ـ الصــادر مــن كتابــة‬\n      ‫عــدل الدمــام كمــا تضمــن أن املبلــغ الباقــي ثالثمائــة ألــف ريــال وأول‬\n      ‫قســط يف تاريــخ ‪1409/2/2‬ه ـ انتهــى املقصــود منــه شــاهد ‪...‬شــاهد ‪...‬‬\n      ‫املشــتري البائــع وبســؤال املدعــي وكالــة عــن شــهوده قــال إن أحدهمــا‬\n      ‫تــويف رحمــه اهلل والثانــي ‪...‬الزال موجــودا وأطلــب رفــع اجللســة إلحضــاره‬\n      ‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــي أصالــة ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وأحضــرا معهمــا للشــهادة ‪...‬‬\n      ‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫قــال أشــهد أن املدعــي ‪...‬اشــترى البيــت املذكــور يف الدعــوى يف حــي‬\n      ‫‪ 71‬بالدمــام ملالكــه ‪...‬وكان ذلــك يف تاريــخ ‪1409/01/14‬ه ـ مببلــغ‬\n      ‫أربعمائــة ألــف ريــال وقــد كتبــت املبايعــة بينهمــا يف مكتبــي العقــاري‬\n      ‫بيــدي بهــذا أشــهد وعليــه أوقــع كمــا أحضــر املدعــي معدلــن لشــاهده‬\n      ‫وهمــا كل مــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬و‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وباستشــهادهما شــهدا‬\n      ‫بثقــة وعدالــة الشــاهد كمــا أبــرز املدعــي ســندات قبــض باملبالــغ التــي‬\n      ‫دفعهــا للمدعــى عليــه جــرى إرفــاق صــور منهــا مصدقــة باملعاملــة لذا فقد‬\n      ‫قــررت أخــذ ميــن املدعــي أصالــة مــع بينتــه وبعــرض اليمــن عليــه اســتعد‬\n      ‫بهــا وحلــف قائــا واهلل العظيــم عالــم الغيــب والشــهادة أننــي اشــتريت‬\n      ‫البيــت محــل الدعــوى مــن املدعــى عليــه ‪...‬بأربعمائــة ألــف ريــال ودفعتهــا‬\n      ‫لــه واهلل العظيــم هكــذا حلــف وكان قــد وردنــي كذلــك خطــاب‬\n      ‫مديــر شــرطة الدمــام رقــم ‪ 2/11600/7/5/21‬يف ‪1434/06/19‬ه ـ‬\n      ‫املتضمــن أنــه بالبحــث يف ســجالت الســجناء املودعــن شــعبة إصالحيــة‬\n\n\n‫‪391‬‬\n\f‫الدمــام لــم يعثــر علــى املذكــور ضمــن الســجناء حســب كتابهــم املرفــق‬\n‫رقــم ‪ 1547‬يف ‪1434/5/6‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n‫وبنــاء علــى شــهادة الشــاهد املعــدل شــرعا املذكــورة بعاليــه ومــا جــاء يف‬\n‫عقــد املبايعــة املشــار إليــه وملــا يف صحيــح مســلم مــن حديــث ابــن عبــاس‬\n‫رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن‬\n‫وألن املدعــي حلــف علــى صفــة مــا ذكــر بعاليــه فبنــاء علــى كل مــا‬\n‫تقــدم فقــد ثبــت لــدي أن البيــت محــل الدعــوى املذكــورة حــدوده بعاليــه‬\n‫ملــك للمدعــي ‪ ...‬انتقلــت ملكيتــه إليــه مبوجــب املبايعــة املذكــورة‬\n‫بعاليــه وبذلــك حكمــت والغائــب علــى حجتــه متــى حضــر وســيجري‬\n‫بعــث املعاملــة حملكمــة االســتئناف لتدقيقهــا كاملتبــع وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/07/04‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق‪ 1434/11/13‬ه ـ‬\n‫افتتحــت اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية برقــم ‪ 341747031‬يف ‪1434/11/6‬ه ـ وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n‫‪ 34350285‬يف ‪1434/11/4‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/11/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1747031‬ش‪ 2‬وتاريــخ‬\n‫‪1434/7/18‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة‬\n\n\n                                                                                    ‫‪392‬‬\n\f      ‫الدمــام برقــم ‪ 33/331989‬وتاريــخ ‪1434/7/16‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ‪... /‬املســجل برقــم ‪34261568‬‬\n      ‫وتاريــخ ‪1434/7/8‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة إفــراغ‬\n      ‫عقــار وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫حكــم فضيلتــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه‬\n                                                   ‫وســلم حــرر يف ‪1434/11/4‬ه ـ‬\n\n\n\n\n‫‪393‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":387,"source_page_end":393,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4adc461ef0b87bf223bc95815d7507a9d9fbba30f7635c32fdd04350b2ab4897","normalized_text_hash":"d0e2094dc13ec2b8ab1ec217146b173356c8167d8d4e174c2b913e2d4fa63223","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p387-261568"},{"id":"7b99c638-dcac-5b5e-9538-147bc90df23c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء فيا و قطعة أرض -إفراغ صوري -شراء غير املواطن لعقار وتسجيله باسم مواطن -طلب املقاصة القضائية -احلكم بإفراغ العقار للمستثمر غير مواطن املادة األولى من نظام متلك غير السعودي للعقار واستثماره","document_number":"33255495","case_number":"28505","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/18","year":"1434","subject":"عقار -شراء فيا و قطعة أرض -إفراغ صوري -شراء غير املواطن لعقار وتسجيله باسم مواطن -طلب املقاصة القضائية -احلكم بإفراغ العقار للمستثمر غير مواطن املادة األولى من نظام متلك غير السعودي للعقار واستثماره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/18 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33255495 :‬‬\n                       ‫َر ْق ُم الدعوى‪28505 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34193593‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n‫عقــار‪ -‬شــراء فيــا و قطعــة أرض ‪ -‬إفــراغ صــوري ‪ -‬شــراء غيــر املواطــن‬\n‫لعقــار وتســجيله باســم مواطــن‪ -‬طلــب املقاصــة القضائيــة‪ -‬احلكــم‬\n                                 ‫بإفــراغ العقــار للمســتثمر غيــر مواطــن‬\n\n\n\n\n           ‫املادة األولى من نظام متلك غير السعودي للعقار واستثماره‬\n\n\n\n\n‫ادعــى املدعــى وكالــة علــى املدعــى عليهــم بــأن موكلــه اشــتري عقاريــن‬\n‫متالصقــن ودفــع ثمنهمــا وســجلهما باســم مــورث املدعــى عليهــم كــون‬\n‫األجنبــي وقــت تاريــخ الشــراء ال يحــق لــه متلــك العقــار وأن العقاريــن‬\n‫املذكــوران حتــت يــد موكلــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــى وذكــر املدعــى عليــه وكالــة بــأن العقاريــن املذكوريــن ملــك‬\n‫خــاص ملــورث موكليــه وأنــه جعــل للمدعــى أصالــة حــق الســكن فقــط‬\n‫ألنــه كان شــريك ًا ملــورث موكليــه وأنــه قبــل ســبع ســنوات تقريب ـ ًا‬\n‫قــام موكلــوه بشــراء حصــة املدعــى أصالــة مــن الشــركة وترتــب عليهــا‬\n‫ضريبــة دخــل مت تســليمها ملصلحــة الــزكاة‪ -‬طلــب املدعــى عليــه وكالــة‬\n‫ألــزام املدعــى أصالــة بتســليم مبلــغ الضريبــة ملوكليــه‪ -‬قــرر املدعــى‬\n‫وكالــه أن الصحيــح مــا جــاء يف دعــواه ومســألة الضريبــة ال عالقــة لهــا‬\n\n                                                                                ‫‪394‬‬\n\f      ‫بهــذه الدعــوى وللمدعــى عليــه وكالــة إقامــه دعــوى مســتقل بهــا‪ -‬أبــرز‬\n      ‫املدعــى وكالــة أقــرار ًا خطيـ ًا منســوب ًا ملــورث املدعــى عليهــم يتضمــن أن‬\n      ‫العقاريــن موضــع الدعــوى ملــك للمدعــى‪ -‬كمــا أبــرز عقــد تنــازل صــادر‬\n      ‫مــن وكيــل املدعــى عليهــم يتضمن تنازلهم عــن العقارين موضع الدعوى‬\n      ‫حيــث ســبق أن اشــتراهما املدعــى مــن مالــه اخلــاص‪ -‬بعــرض هذيــن‬\n      ‫االقراريــن علــى املدعــي عليــه وكالــة صــادق عليــه‪ -‬جــرت الكتابــة‬\n      ‫للهيئــة العامــة لالســتثمار لإلفــادة عــن املوافقــة لتملــك املدعــى للعقاريــن‬\n      ‫املذكوريــن‪ -‬وردت اإلجابــة بأنــه ال مانــع اســتخدام املنــزل املقــام عليــه‬\n      ‫كســكن خــاص لصاحــب املصنــع ( املدعــى) صــدر احلكــم بإثبــات أن‬\n      ‫كامــل العقاريــن موضــع الدعــوى ومــا أقيــم عليهمــا مــن بنــاء هــو ملــك‬\n      ‫خــاص للمدعــى أصالــة‪ -‬لــم يقتنــع املدعــى عليهــم وكالــة‪ -‬لوحــظ علــى‬\n      ‫احلكــم مــن محكمــة االســتئناف مبالحظــات أهمهــا االستفســار عــن‬\n      ‫ســريان مفعــول الصــك وأن يكــون إثبــات التملــك باســم املصنــع ‪ -‬جــرى‬\n      ‫االستفســار عــن ســريان مفعــول الصــك‪ -‬رجــع القاضــي عــن حكمــة‬\n      ‫وثبــت لديــه متلــك املصنــع للعقاريــن املوصوفــن يف الدعــوى‪ -‬صــدق‬\n                                                   ‫احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 28505‬وتاريــخ ‪ 1430/06/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 3089594‬وتاريــخ ‪ 1430/06/13‬ه ـ و يف يــوم االحــد‬\n      ‫املوافــق ‪1432/9/7‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n\n‫‪395‬‬\n\f‫املدني رقم ‪ ...‬ورخصة محاماة رقم (‪ )26/143‬وتاريخ ‪1426/9/12‬هـ‬\n‫الوكيــل الشــرعي عــن املدعــي ‪ ...‬مبوجــب الوكالــة الشــرعية الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بالريــاض رقــم ‪ 211244000844‬وتاريــخ‬\n‫‪1430/6/6‬ه ـ وحضــر حلضــوره ‪ ...‬الوكيــل الشــرعي عــن ‪ ...‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل جــدة الثانيــة برقــم ‪ 18809‬يف ‪1428/2/27‬ه ـ جلــد ‪ 5747‬و‪...‬‬\n‫املذكــور وكل املدعــي باألصالــة عــن نفســه وبالوكالــة عــن ‪ ...‬و‬\n‫‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب الوكالــة الصــادرة مــن بيــروت‬\n‫برقــم ‪1424/145‬ه ـ يف ‪1424/6/29‬ه ـ واملصــادق عليهــا مــن اجلهــات‬\n‫املختصــة وادعــى االول قائــا لقــد اشــترى موكلــي فيــا بحــي ‪ ...‬بتاريــخ‬\n‫‪1413/5/30‬ه ـ واملقامــة علــى قطعــة االرض رقــم ‪ 83‬باملخطــط رقــم‬\n‫‪ 1371‬مببلــغ وقــدره مليونــا ري ـ ــال مــن مالكهــا ‪ ...‬كمــا اشــترى قطعــة‬\n‫االرض املجــاورة للقطعــة املذكــورة رقــم ‪ 82‬باملخطــط املشــار إليــه‬\n‫مببلــغ وقــدره مليــون ومئــة ألــف ريــال مــن مالكتهــا ‪ ...‬وقــد مت افــراغ‬\n‫القطعتــن املشــار إليهمــا باســم مــورث موكلــي املدعــى عليــه ‪ ...‬وذلــك‬\n                                  ‫نظــرا لكــون موكلــي أجنبــي اجلنســية‬\n\n\n\n\n                                                                                  ‫‪396‬‬\n\f      ‫ويف التاريــخ املذكــور ال يحــق لألجنبــي متلــك العقــار فتــم االفــراغ‬\n      ‫صوريــا ملــورث موكلــي املدعــى عليــه وقــد اســتلم موكلــي العقــار‬\n      ‫املذكــور يف حينــه ومــا زال حتــت يديــه وســاكن فيــه وحيــث أن‬\n      ‫التعليمــات أخيــرا جتيــز متلــك االجنبــي لــذا فإننــي أطلــب اثبــات شــراء‬\n      ‫موكلــي لالرضــن املذكورتــن ومــا اقيــم عليهــا مــن بنــاء وافــراغ‬\n      ‫االرضــن ملوكلــي هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب‬\n      ‫قائــا انــه بالرجــوع إلــى املســتندات التــي وجــدت بحــوزة موكلينــي‬\n      ‫أقــدم هــذا الــرد‪ -1‬اإلقــرار املــؤرخ يف ‪1413/05/30‬ه ـ والصــادر مــن‬\n      ‫مــورث موكلينــي أشــار فيــه صراحــة إلــى أن الفيــا مــكان االدعــاء‬\n      ‫بــأن الشــراء قــد مت مــن أمــوال الشــركة كســكن خــاص بــه حيــث‬\n      ‫كان املدعــي شــريك ًا بهــا إلــى حــن تخارجــه (مرفــق رقــم ‪ )1‬وهــي‬\n      ‫الوثيقــة الشــرعية التــي تثبــت كيفيــة إمتــام الشــراء ‪-2 .‬عقــد التنــازل‬\n      ‫عــن الفيــا املــؤرخ يف ‪1425/02/23‬ه ـ مــن وكيــل ورثــة املرحــوم ‪- ...‬‬\n      ‫لــم تتــم اإلشــارة فيــه إلــى ســند الشــراء الصــادر مــن الشــركة‪-3 .‬مت‬\n      ‫إنهــاء الشــركة مبوجــب نظــام الشــركات بعــد وفــاة مــورث موكلينــي‬\n      ‫وقامــت الشــركة بســداد كافــة االلتزامــات املاليــة التــي ترتبــت علــى‬\n      ‫التخــارج باســم جميــع الشــركاء عنــد إنهــاء هــذه الشــراكة واملدعــي‬\n      ‫علــى علــم بكافــة اجلوانــب املاليــة للشــركة واملطالبــات التــي عليهــا ‪.‬‬\n      ‫‪-4‬الشــركة قامــت بســداد مبلــغ ( ‪ ) 1.865.584‬فقــط مليــون وثمامنائــة‬\n      ‫وخمســة وســتون ألــف وخمســمائة وأربعــة وثمانــون ريــال ملصلحــة‬\n      ‫الــزكاة والدخــل مبوجــب أمــر التحصيــل ‪ 248692‬إبــراء لذمتــه مــن‬\n      ‫أمــوال الشــركة املســتحقة ملصلحــة الــزكاة والدخــل كضريبــة علــى‬\n      ‫الشــريك األجنبــي ‪-5 .‬املدعــي لــم يقــر بهــذه القيمــة املتعلقــة بالــزكاة‬\n\n\n‫‪397‬‬\n\f‫والتــي مت احتســابها مــن قبــل املصلحــة (مرفــق رقــم ‪-6 . ) 2‬علــى املدعــي‬\n‫تقــدمي البينــة التــي تثبــت ســداده لقيمــة الفيــا مــن أموالــه اخلاصــة لــذا‬\n‫فاننــي اطلــب عمــل مقاصــة قضائيــة اســتناد ًا إلــى نــص املــادة الثمانــون‬\n‫يف فقرتهــا ( أ) مــن نظــام املرافعــات الشــرعية ملطالبــة املدعــي بســداد‬\n‫مبلــغ وقــدره ( ‪ ) 1.865.584‬فقــط مليــون وثمامنائــة وخمســة وســتون‬\n‫ألــف وخمســمائة وأربعــة وثمانــون ريــال مت ســدادها عنــه ملصلحــة‬\n‫الــزكاة والدخــل للشــركة التــي ســددتها كضريبــة عــن الشــريك‬\n‫األجنبــي ‪ .‬هكــذا اجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال ان‬\n‫مــا ذكــره املدعــى عليــه يف اجابتــه دعــوى ال عالقــة لهــا باملنــزل املدعــى‬\n‫بــه وانــا ال اقــر مــا ذكــره وال انكــره وعليــه ان يتقــدم بدعــوى مســتقلة‬\n‫فبــاب الشــرع مفتــوح فجــرى افهامــه بــان عليــه االجابــة علــى مــا ذكــره‬\n‫املدعــى عليــه باجابــة مالقيــه فقــال ان جميــع مــا ذكــره املدعــى عليــه‬\n‫يف اجابتــه غيــر صحيــح والصحيــح مــا ذكرتــه يف دعــواي وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال الصحيــح مــا ذكرتــه وعندمــا مت‬\n‫شــراء حصــة مــوكل املدعــي يف الشــركة بقــي العقــار املذكــور معلقــا‬\n‫وقــد وافــق موكلــي علــى تســليم العقــار ملــوكل املدعــي اذا مت تصفيــة‬\n‫مــا بذمتــه مــن التزامــات ماليــة للدولــة وســداد االلتزامــات مــن قبــل‬\n‫الشــركة املذكــورة اعــاه وبعــرض ذلــك علــى املدعــي وكالــة قــال مــا‬\n‫ذكــره املدعــى عليــه غيــر صحيــح وبســؤال املدعــى عليــه وكالــة هــل‬\n‫لديــه بينــة علــى صحــة مــا ذكــره يف اجابتــه فقــال نعــم وســوف احضرهــا‬\n‫يف اجللســة القادمــة ويف يــوم الثالثــاء املوافــق‪ 1433/05/18‬ه ـ لــدي‬\n‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض افتتحــت اجللســة وفيهــا‬\n‫حضــر الطرفــان وبتــاوة مــا مت ضبطــه عليهمــا صادقــا عليــه وحيــث‬\n\n\n                                                                                      ‫‪398‬‬\n\f      ‫لــم تتضــح لــي اجابــة املدعــى عليــه وكالــة لــذا طلبــت منــه اإلجابــة عــن‬\n      ‫دعــوى املدعــي وكالــة فقــال إن مــا ذكــره املدعــي وكالــة يف دعــواه‬\n      ‫مــن العقاريــن الفلــة واألرض اللذيــن ذكــر موقعهمــا صحيــح وهما باســم‬\n      ‫مــورث موكلــي ومــا ذكــره أنهمــا ملــك ملوكلــه وكتبهــا باســم مــورث‬\n      ‫موكلــي ألنــه أجنبــي وال يحــق لــه التلمــك غيــر صحيــح والصحيــح أنهــا‬\n      ‫ملــك ملــورث موكلــي خالــص وإمنــا جعــل للمدعــي أصالــة حــق الســكن‬\n      ‫فيهــا فقــط ألنــه كان شــريكا ملــورث موكلــي يف شــركة ‪ ...‬وقبــل‬\n      ‫ســبع ســنوات تقريبــا قــام موكلــي بشــراء حصتــه مــن الشــركة وترتــب‬\n      ‫عليــه ضريبــة دخــل مت تســليمها ملصلحــة الــزكاه والدخــل مببلــغ قــدره‬\n      ‫مليــون وثمــان مئــة وخمــس وســتون ألــف وخمــس مئــة وأربعــة وثمانــون‬\n      ‫ريــال نطلــب الزامــه بتســليم هــذا املبلــغ ملوكلــي هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا ذكرتــه مــن متلــك موكلــي‬\n      ‫للعقاريــن املذكوريــن مــن مالــه اخلــاص ولــدي البينــة وأمــا ماذكــره مــن‬\n      ‫دفــع ضريبــة الدخــل فهــذه دعــوى مســتقلة ال عالقــة لهــا بدعــواي هكذا‬\n      ‫قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ال مانــع لــدي مــن‬\n      ‫اقامــة دعــوى مســتقلة يف مطالبتــه مببلــغ ضريبــة الدخــل واســأله البينــة‬\n      ‫علــى دعــواه وبطلــب البينــة مــن املدعــي وكالــة ابــرز أصــل ورقــة مؤرخــه‬\n      ‫يف ‪1413/5/30‬ه ـ وهــذا نصهــا اقــرار يوضــح ‪ ...‬أن صكــي الفلــة‬\n      ‫الواقعــة بحــي ‪ ...‬والتــي مت شــراؤها مــن ‪ ...‬مببلــغ ثالثــة ماليــن ريــال ومت‬\n      ‫افراغهــا لــدى كاتــب عــدل الريــاض بســجالت األرقــام التاليــة ‪4/673‬‬\n      ‫مــن ‪ 95‬جلــد وتاريــخ ‪1402/4/29‬ه ـ و ‪ /3/455‬تاريــخ ‪1401/4/26‬ه ـ‬\n      ‫أن هــذه الفلــة املقامــة علــى هاتــن القطعتــن همــا ملــك خــاص لــأخ ‪...‬‬\n      ‫أردنــي اجلنســية حيــث يعمــل معنــا شــريكا يف شــركة ‪ ...‬مت شــراؤها‬\n\n\n‫‪399‬‬\n\f‫لســكنه اخلــاص باســمنا حتــى يتــم احلصــول علــى اجــازة التملــك لــه‬\n‫مــن قبــل اجلهــات املختصــة وخوفــا مــن مفاجــأت احليــاة فإننــي اقــرر أن‬\n‫هذيــن الصكــن ملــك خالــص لــه وقــد تعهــد الرجــل بانهــاء اجــراءات‬\n‫معاملتــه مــن الداخليــة كمــا نصــت بذلــك األنظمــة كتبتــه بخــط يــدي‬\n‫وأنــا بكامــل قــواي العقليــة والبدنيــة واهلل علــى مــا أقــول شــهيد ‪...‬‬\n‫وتوقيعــه مــؤرخ يف ‪1413/5/30‬ه ـ ا‪.‬ه ـ كمــا أبــرز اصــل عقــد تنــازل‬\n‫علــى مطبوعــات مصنــع ‪ ...‬النتــاج الظــروف والبطاقــات البالســتيكية‬\n‫هــذا نصــه ( بعــون اهلل تعالــى يف هــذا اليــوم الثالثــاء املوافــق ‪/2/23‬‬\n‫‪1425‬ه ـ مت االتفــاق بــن كل مــن االطــراف التاليــة الطــرف االول ورثــة‬\n‫املرحــوم ‪ ...‬ســعودي اجلنســية مبوجــب حفيظــة النفــوس رقــم ‪ ...‬وتاريــخ‬\n‫‪1384/10/14‬ه ـ وميثلهــم الســيد ‪ ...‬ســعودي اجلنســية مبوجــب بطاقــة‬\n‫االحــوال املدنيــة رقــم ‪ ...‬وتاريــخ ‪1417/1/21‬ه ـ وكيــا عــن الورثــة‬\n    ‫مبوجــب الوكالــة رقــم ‪1424/145‬بتاريــخ ‪1424/6/29‬ه ـ واملرفــق‬\n‫صــورة منــه الطــرف الثانــي الســيد ‪ ...‬اردنــي اجلنســية مبوجــب جــواز‬\n‫ســفر رقــم ‪ ...‬وتاريــخ ‪ 2003/2/18‬واقامــة رقــم ‪ 2007214196‬صــادرة‬\n‫مــن الريــاض بتاريــخ ‪1423/7/13‬ه ـ علــى ان يتنــازل الطــرف االول عــن‬\n‫ملكيــة الفيــا القائمــة علــى مخطــط ‪ ...‬رقــم ‪ 1371‬بتاريــخ ‪1400‬ه ـ يف‬\n‫القطعتــن رقــم ‪ 83،82‬والتــي يحدهمــا مــن الغــرب القطعتــن ‪85،84‬‬\n‫ومــن اجلنــوب شــارع ‪15‬ومــن الشــرق شــارع ‪ 15‬ومــن الشــمال قطعــة رقــم‬\n‫‪ 81‬حيــث ان العقــار املشــار اليــه يف هــذا التنــازل ســبق وان اشــتراه‬\n‫الســيد ‪ ...‬مــن مالــه اخلــاص يف حيــاة املرحــوم ‪ ...‬وعلــى هــذا مت االتفــاق‬\n‫وان اهلل خيــر الشــاهدين الطــرف االول املتنــازل ورثــة املرحــوم ‪ ...‬وينــوب‬\n‫عنهــم ‪ ...‬مبوجــب صــك الوكالــة توقيعــه الطــرف الثانــي املتنــازل لــه‬\n\n\n                                                                                    ‫‪400‬‬\n\f      ‫‪ ...‬املســتثمر يف مصنــع ‪ ...‬توقيعــه وختمــه شــاهد اول ‪ ...‬توقيعــه شــاهد‬\n      ‫ثانــي ‪ ...‬توقيعــه ) ا‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‬\n      ‫االقــرار اخلطــي االول صــادر مــن مــورث موكلــي وبخــط يــده فعــا‬\n      ‫والتوقيــع توقيعــه وليــس لــدي اعتــراض عليــه ولكــن اطلــب اثبــات ان‬\n      ‫مبلــغ العقاريــن ســلم ملــورث موكلــي وقــدره ثالثــة ماليــن ريــال وامــا‬\n      ‫اقــرار التنــازل الــذي ذكــره صحيــح ايضــا وصــادر مــن موكلــي ‪...‬‬\n      ‫اصالــة عــن نفســه وبوكالتــه عــن بقيــة الورثــة وهــو مخــول يف وكالتــه‬\n      ‫بالتنــازل ولكــن كتــب هــذا التنــازل بنــاء علــى الورقــة االولــى وال زلــت‬\n      ‫اطلــب اثبــات تســليم مبلــغ العقاريــن مــن قبــل املدعــي اصالــة هكــذا‬\n      ‫قــرر هــذا وقــد ســبق الكتابــة حملافــظ الهيئــة العامــة لالســتثمار‬\n      ‫لالفــادة عــن موافقتــه علــى متلــك املدعــي اصالــة للعقاريــن املذكوريــن‬\n      ‫باخلطــاب رقــم ‪ 32/196953‬وتاريــخ ‪1432/3/13‬ه ـ فــورد جــواب‬\n      ‫وكيــل احملافــظ والرئيــس التنفيــذي للعمليــات للخطــاب رقــم ‪23888‬‬\n      ‫وتاريــخ ‪1432/4/23‬ه ـ املتضمــن بانــه ال مانــع لــدى الهيئــة العامــة مــن‬\n      ‫اســتثمار مــن متلــك مصنــع ‪ ...‬للعقــار لغــرض اســتخدام املنــزل املقــام‬\n      ‫عليــه كســكن خــاص لصاحــب املصنــع ‪ ...‬ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واالجابــة املتضمنــة انــكار املدعــى عليــه وكالــة لدعــوى‬\n      ‫املدعــي وكالــة مــن ان موكلــه متلــك العقاريــن املذكوريــن يف الدعــوى‬\n      ‫مــن مالــه اخلــاص واثبــت املدعــي وكالــة باالقــرار اخلطــي الصــادر مــن‬\n      ‫مــورث املدعــى عليهــم اصالــة املرصــود نصــه بعاليــه واملتضمــن اقــراره‬\n      ‫بــان العقاريــن املذكوريــن ملــك خالــص للمدعــي اصالــة وكذلــك مــا‬\n      ‫ابــرزه مــن تنــازل وكيــل الورثــة واقــراره بــان املدعــي اصالــة ســبق وان‬\n      ‫اشــترى العقاريــن املذكوريــن مــن مالــه اخلــاص يف حيــاة مورثهــم وهــو‬\n\n\n‫‪401‬‬\n\f‫مخــول بالتنــازل وصــادق علــى ذلــك املدعــى عليــه وكالــة وقــد جــرى‬\n‫االطــاع علــى وكالتــه املذكــور رقمهــا وتاريخهــا ووجدتهــا تخولــه‬\n‫املدافعــة واملرافعــة والتنــازل واالقــرار وملوافقــة اجلهــة املصــدرة لترخيــص‬\n‫املدعــي اصالــة وهــي الهيئــة العامــة لالســتثمار لتملكــه باســم املصنــع‬\n‫اململــوك لــه و بنــاء علــى املــادة االولــى مــن نظــام متلــك غيــر الســعوديني‬\n‫للعقــار واســتثماره لــذا فقــد ثبــت لــدي ان كامــل العقاريــن املوصوفــن‬\n‫للدعــوى ومــا اقيــم عليهمــا مــن بنــاء هــو ملــك خــاص باملدعــي اصالــة‬\n‫وبذلــك حكمــت وســيهمش علــى صــك امللكيــة بذلــك بعــد اكتســاب‬\n‫احلكــم الصفــة القطعيــة والتأكــد مــن ســريان مفعــول الصكــن مــن‬\n‫اجلهــة املصــدرة لــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة‬\n‫القناعــة واملدعــى عليــه عدمهــا وطلــب االســتئناف واجيــب لطلبــه وافهــم‬\n‫بــان لــه مــدة االعتــراض ثالثــن يومــا ابتــداء مــن اليــوم ويســقط حقــه يف‬\n‫االعتــراض بعــد انتهــاء املــدة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/05/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنني املوافق‪ 1434/01/26‬هـ افتتحت‬\n‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم ‪331405806‬‬\n‫وتاريــخ ‪1433/7/26‬ه ـ شــرحا على خطاب رئيس محكمة االســتئناف‬\n‫رقــم ‪ 1176538‬وتاريــخ ‪1433/7/22‬ه ـ وبرفقهــا قــرار الدائــرة االولــى‬\n‫املســجل برقــم ‪ 33326610‬وتاريــخ ‪1433/7/5‬ه ـ واملتضمــن مــا نصــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة‬\n‫لوحــظ مــا يلــي اوال لــم يطلــب مــن املدعــى عليــه وكالــة حصــر ورثــة‬\n‫مــورث موكلــه وشــركاه ويــدون مضمونــه ويرفــق صــورة طبــق االصــل‬\n‫منــه باملعاملــة ثانيــا لــم يستفســر عــن ســريان مفعــول صكــوك التملــك‬\n\n\n                                                                                       ‫‪402‬‬\n\f      ‫وهــل هــي صاحلــة لالعتمــاد عليهــا يف االفــراغ ام ال ثالثــا حكــم فضيلتــه‬\n      ‫بثبــوت متلــك املدعــي للعقاريــن املوصوفــن يف الدعــوى ومــا حكــم بــه ال‬\n      ‫يتفــق مــع مــا ورده مــن الهيئــة العامــة لالســتثمار مــن ان يكــون اثبــات‬\n      ‫التملــك باســم مصنــع ‪ ...‬فعلــى فضيلتــه مالحظــة مــا ذكــر واكمــال‬\n      ‫مــا يلــزم نحــوه واهلل املوفــق ا‪.‬ه ـ وعليــه فقــد حضــر الطرفــان يف هــذه‬\n      ‫اجللســة وبطلــب صــك حصــر الورثــة مــن املدعــى عليــه وكالــة ابــرز‬\n      ‫الصــك الصــادر مــن ‪ 29/123‬وتاريــخ ‪1422/7/20‬ه ـ وانحصــار ورثتــه‬\n      ‫يف زوجتــه ‪ ...‬واوالده ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ومرفــق صــورة مصدقــة‬\n      ‫منــه يف املعاملــة وبالنســبة للمالحظــة الثانيــة فقــد جــرى االستفســار‬\n      ‫عــن ســريان مفعــول الصــك رقــم ‪1402/4/29 4/673‬ه ـ فوردنــا جــواب‬\n      ‫كتابــة العــدل االولــى برقــم ‪ 331748535‬وتاريــخ ‪1433/10/17‬هـ ـ و‬\n      ‫باالستفســار عــن الصــك رقــم ‪ 3/455‬يف ‪1401/4/26‬ه ـ وردنــا جــواب‬\n      ‫كتابــة العــدل االولــى رقــم ‪ 331748570‬وتاريــخ ‪1433/10/17‬ه ـ‬\n      ‫ووجدتهمــا انهمــا ال يــزاالن ســاريا املفعــول وبالنســبة للمالحظــة الثالثــة‬\n      ‫فلوجاهــة مــا ذكــره اصحــاب الفضيلــة فقــد رجعــت عــن حكمــي بــان‬\n      ‫العقاريــن املوصوفــن يف الدعــوى ملــك للمدعــي اصالــة وثبــت لــدي متلــك‬\n      ‫مصنــع ‪ ...‬للعقاريــن املوصوفــن يف الدعــوى وبذلــك حكمــت وبعرضــه‬\n      ‫علــى الطرفــن قنــع بــه املدعــي وكالــة وامــا املدعــى عليــه وكالــة فــا‬\n      ‫زال علــى اعتراضــه وامــرت باحلــاق ذلــك بالصــك وســجله واعادتــه مــع‬\n      ‫كامل اوراق املعاملة حملكمة االستئناف وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/26‬هـ‬\n      ‫احلمــد هلل وحــده وبعــدويف يــوم االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعه ‪ 2،30‬وقــد وردنــا خطــاب فضيلــة رئيــس احملكمــة‬\n\n\n‫‪403‬‬\n\f‫العامــه املســاعد برقــم ‪ 34547760‬وتاريــخ ‪1434/3/3‬ه ـ شــرحا علــى‬\n‫خطــاب فضيلــة رئيــس محكمــة االســتئناف املســاعد رقــم ‪34278175‬‬\n‫وتاريــخ ‪1434/2/30‬ه ـ املرفــق بــه قــرار الدائــرة احلقوقيــة االولــى رقــم‬\n‫‪ 3445567‬وتاريــخ ‪1434/2/24‬ه ـ املتضمــن ( وباالطــاع علــى مــا‬\n‫أجــاب بــه فضيلــة القاضــي وأحلقــه بذيــل الصــك وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم ‪ 33326610‬وتاريــخ ‪1433/7/5‬ه ـ يلحــظ أن فضيلتــه‬\n‫لــم يــدون مضمــون وكالتــي املدعــي واملدعــى عليــه وهــل تخوالنهمــا‬\n‫الســير يف الدعــوى واإلقــرار كمــا لوحــظ أن فضيلتــه قــال يف حيثيــات‬\n‫احلكــم ( وقــد جــرى اإلطــاع علــى وكالتــه املذكــور رقمهــا وتاريخهــا‬\n‫ووجدتهــا تخولــه املدافعــه واملرافعــه والتنــازل واإلقــرار ) ولــم يذكــر‬\n‫صراحــة الوكالــة املشــار إليهــا والبــد مــن ذلــك كمــا لوحــظ أن فضيلته‬\n‫لــم يــدون مضمــون الوكالــة رقــم ‪ 1424/145‬وتاريــخ ‪1424/6/29‬ه ـ‬\n‫فلمالحظــة ماذكــر وإحلــاق مايتــم بالضبــط والصــك وســجله وإعــادة‬\n‫املعاملــة ‪ .‬واهلل املوفــق ) ا‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة بأنــه جــرى‬\n‫إطالعــي علــى وكالــة املدعــي والتــي حتمــل الرقــم ‪21124400844‬‬\n‫وتاريــخ ‪1430/6/6‬ه ـ تخولــه املطالبــة واملرافعــة واملخاصمــة وإقامــة‬\n‫الدعــوى ضــد ‪ ...‬ولــه حــق االقــرار واإلنــكار والصلــح كمــا جــرى‬\n‫إطالعــي علــى وكالــة املدعى عليه رقــم ‪ 18809‬وتاريخ ‪1428/2/27‬هـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجــده الــذي وكلــه ‪ ...‬أصالــة عــن‬\n‫نفســه وبوكالــة عــن ‪ ...‬وأوالدهــا كل مــن ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد‬\n‫‪ ...‬مبوجــب الوكالــة الصــادرة مــن بيــروت برقــم ‪1424/145‬ه ـ يف‬\n‫‪1424/6/29‬ه ـ واملخــول لــه فيهــا حــق املطالبــة واملدافعــة واملخاصمــة‬\n‫والصلــح والتنــازل واإلقــرار واإلنــكار وأمــا مــا مضمونــه الوكالــة رقــم‬\n\n\n                                                                                    ‫‪404‬‬\n\f      ‫‪1424/145‬ه ـ فهــو ماذكــر يف نــص الوكالــة الســابقه لــذا فلــم يظهــر‬\n      ‫لــي مايؤثــر علــى ماحكمــت بــه وأمــرت باحلــاق ذلــك يف الصــك وســجله‬\n      ‫وإعادتــه إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنــن املوافق‪1434/05/27‬ه ـ افتتحت‬\n      ‫اجللســة بنــاء علــى مــا وردنــا مــن فضيلة الرئيس برقــم ‪ 34944208‬وتاريخ‬\n      ‫‪1434/5/11‬هـ شــرحا على خطاب فضيلة رئيس محكمة االســتئناف‬\n      ‫رقــم ‪ 34547760‬وتاريــخ ‪1434/4/6‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة‬\n      ‫االولــى املســجل برقــم ‪ 34193593‬وتاريــخ ‪1434/4/21‬ه ـ املتضمــن‬\n      ‫« وباالطــاع علــى مــا اجــاب بــه فضيلتــه علــى قرارنــا رقــم ‪3445567‬‬\n      ‫وتاريــخ ‪1434/2/24‬ه ـ تقــرر الدائــرة مــا يلــي اوال املوافقــة علــى رجوعــه‬\n      ‫عــن حكمــه املــؤرخ يف ‪1433/5/18‬ه ـ ثانيــا لــم يظهــر مــا يوجــب‬\n      ‫النقــض بعــد االجــراء االخيــر بتاريــخ ‪1434/1/26‬ه ـ « قاضــي اســتئناف‬\n      ‫‪ ...‬ختمــه وتوقيعــه قاضــي االســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪ ...‬ختمــه وتوقيعــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيق‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪34547760‬‬\n      ‫وتاريــخ ‪1434/4/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ... /‬برقــم ‪ 33255495‬وتاريخ‪1433/5/18‬ه ـ واخلــاص بدعــوى ‪... /‬‬\n      ‫وكالــة ضــد ‪ ... /‬وكالــة بشــأن مطالبــة املدعــي إثبــات شــراء موكليــه‬\n      ‫لألرضيــن املذكورتــن بالصــك واملتضمــن حكــم فضيلتــه إثبــات أن‬\n\n\n‫‪405‬‬\n\f‫كامــل العقاريــن املوصوفــن بالدعــوى ومــا أقيــم عليهمــا مــن بنــاء هــو‬\n‫ملــك خــاص باملدعــي أصالــة وبذلــك حكــم وباإلطــاع علــى مــا أجــاب‬\n‫بــه فضيلتــه علــى قرارنــا رقــم ‪ 3445567‬وتاريــخ ‪1434/2/24‬ه ـ تقــرر‬\n‫الدائــرة مــا يلــي‪ :‬أوالً‪ :‬املوافقــة علــى رجوعــه عــن حكمــه املــؤرخ يف‬\n‫‪1433/5/18‬ه ـ ‪ .‬ثاني ـاً‪ :‬لــم يظهــر مــا يوجــب النقــض بعــد اإلجــراء‬\n                                             ‫األخيــر بتاريــخ ‪1434/1/26‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪406‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":394,"source_page_end":406,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8df4ffff2bb5769c29a5e05406f2f26e5ef0e61ceec913538283d88fc94ca692","normalized_text_hash":"1be8a41e9daa3038562406c5134b58a779661da11e759ff1aae3f562df07a9d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p394-33255495"},{"id":"35bfa6e4-1718-5e12-8269-581bc313fb52","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -طلب إثبات متلك -بيع ما ال ميلك -بيع املجهول - جهالة موقع األرض -حكم برد دعوى .","document_number":"34208586","case_number":"33325715","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/07","year":"1434","subject":"عقار -طلب إثبات متلك -بيع ما ال ميلك -بيع املجهول - جهالة موقع األرض -حكم برد دعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34208586:‬تاريخه ‪1434/05/07:‬ه‬\n                        ‫رقم الدعوى ‪33325715:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34254308:‬تاريخه‪1434/06/28:‬هـ‬\n\n\n      ‫عقــار ‪ -‬طلــب إثبــات متلــك ‪ -‬بيــع مــا ال ميلــك ‪ -‬بيــع املجهــول ‪-‬‬\n                                ‫جهالــة موقــع األرض ‪ -‬حكــم بــرد دعــوى ‪.‬‬\n\n\n\n\n                         ‫قوله صلى اهلل عليه وسلم (( التبع ما ليس عندك ))‬\n\n\n\n\n      ‫دعــوى املدعــي وكالــة ضــد املدعــى عليــه أن املدعــي أصالــة قــد اشــترى‬\n      ‫مــن املدعــى عليــه أرضـ ًا موصوفــة يف نــص القضيــة مببلــغ وقــدره ســتون‬\n      ‫ألــف ريــال وبعــد قبضــه جــزء مــن الثمــن تبــن أن القطعــة متداخلــة مــع‬\n      ‫أمــاك الغيــر فتــم اســتبدالها مــع قطعــة أخــرى وطلــب املدعــى وكالــة‬\n      ‫إثبــات متلــك موكلــه لــأرض البديلــة وســوف يكمــل باقــي الثمــن ‪-‬‬\n      ‫أجــاب املدعــى عليــه أن دعــوى املدعــي وكالــة غيــر صحيحــة ‪ -‬قــرر‬\n      ‫املدعــي وكالــة أن موكلــه لــم يكــن يعلــم موقــع األرض البديلــة ‪-‬‬\n      ‫قــرر ناظــر القضيــة بــأن املدعــي وكالــة قــرر بــأن املدعــي أصالــة قــد‬\n      ‫اشــترى أرضـ ًا منزوعــة ليســت يف ملــك املدعــى عليــه وقــد قصــد أرضـ ًا‬\n      ‫غيــر معلومــة ولقولــه صلــى اهلل عليــه وســلم (( التبــع مــا ليــس عنــدك‬\n      ‫)) ونهيــه عــن بيــع املجهــول فقــد ثبــت لــدى ناظــر القضيــة بطــان بيــع‬\n      ‫األرض محــل الدعــوى ورد دعــوى املدعــي ‪ -‬قــرر املدعــي وكالــة عــدم‬\n\n‫‪407‬‬\n\f‫القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة‬\n                                                          ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة ففــي يــوم الثالثــاء املوافق‪1433/06/24‬ه ـ حضــر‬\n‫‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل عــن ‪/‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املدينــة الثانيــة برقــم‬\n‫‪ 7776/ 32743‬يف ‪1433/5/9‬ه ـ وادعــى علــى احلاضــر معــه ‪ /‬ســعودي‬\n‫ا يف دعــواه إن موكلــي قــد‬      ‫اجلنســية مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n‫اشــترى قطعــة أرض رقــم ‪........‬مــن مخطــط ‪ ........‬بثمــن قــدره ســتون‬\n‫ألــف ريــال مــن املدعــى عليــه وبعــد دفعــه جلــزء مــن الثمــن وقــدره اثنــان‬\n‫وخمســون ألــف ريــال تبــن أن القطعــة املشــار إليهــا متداخلــة مــع أمــاك‬\n‫للغيــر فتــم اســتبدالها مــن قبــل األمانــة بالقطعــة رقــم ‪........‬مــن مخطــط‬\n‫‪........‬لــذا أطلــب منكــم احلكــم بإثبــات موكلــي لــأرض املذكــورة‬\n‫علمـ ًا أن موكلــي مســتعد بدفــع الباقــي مــن الثمــن وقــدره ثمانيــة آالف‬\n‫ا مــا‬\n     ‫ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n‫ذكــره املدعــي غيــر صحيــح والصحيــح أن أخ مــوكل املدعــي حضــر‬\n‫إلــي وطلــب منــي شــراء األرض ذات الرقــم ‪........‬مــن ‪........‬لصالــح إخوانــه‬\n‫القصــر وذلــك لكونهــم بحاجــة إلــى أرض فقلــت لــه أنــه يوجــد أرض‬\n‫مخصصــة لــي يف مخطــط ‪........‬وال زالــت حتــت اإلجــراء وأرغــب يف‬\n‫بيعهــا علــى إخوانــك القصــر وبعــد ذلــك تبــن لــي أنــه يرغــب يف شــراء‬\n‫األرض ألخيــه املدعــي أصالــة وملــا علمــت بذلــك أبلغتهــم بفســخي للبيــع‬\n\n                                                                                      ‫‪408‬‬\n\f      ‫وعــدم إمتامــه علم ـ ًا أن قطعــة األرض املدعــى بهــا صــدر لهــا صــك رقــم‬\n      ‫‪ 340106006940‬يف ‪1433/5/11‬ه ـ مــن كتابــة العــدل األولــى يف‬\n      ‫املدينــة املنــورة باســم هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أفــاد‬\n      ‫ا مــا ذكــره املدعــى عليــه غيــر صحيــح هكــذا أجــاب ثــم أبــرز‬        ‫قائ ـ ً‬\n      ‫املدعــى عليــه الصــك املشــار إليــه للقطعــة املدعــى بهــا فوجــدت فيــه مــا‬\n      ‫نصــه « فــإن قطعــة األرض رقــم ‪........‬مــن املخطــط رقــم ‪/ 1‬ف ‪1411/‬‬\n      ‫الواقــع يف حــي ‪/........‬ب مبدينــة املدينــة املنــورة وحدودهــا وأطوالهــا‬\n      ‫كالتالــي ‪ :‬شــما ًال مواقــف ســيارات بطــول ‪ :‬مــن شــرق إلــى غــرب ‪12‬‬\n      ‫م اثنــي عشــر متــر ًا ثــم مبيــل خفيــف إلــى القبلــة ‪ 17.32‬م ســبعة عشــر‬\n      ‫متــر ًا واثنــان وثالثــون ســنتمتر ًا ‪ ،‬وجنوب ـاً‪ :‬شــارع بعــرض ‪ 30‬م بطــول ‪:‬‬\n      ‫‪ 27‬ســبعة وعشــرون متــر ًا ‪ ،‬وشــرق ًا ‪ :‬القطعــة رقــم ‪ 217‬بطــول ‪27.27 :‬‬\n      ‫ســبعة وعشــرون متــر ًا وســبعة وعشــرون ســنتمتر ًا وغرب ـ ًا ‪ :‬القطعــة‬\n      ‫رقــم ‪ 219‬بطــول ‪ 18.46 :‬ثمانيــة عشــر متــر ًا وســتة وأربعــون ســنتمتر ًا‬\n      ‫ومســاحتها ‪ 669.28 :‬ســتمائة وتســعة وســتون متــر ًا مربع ـ ًا وثمانيــة‬\n      ‫وعشــرون ســنتمتر ًا مربع ـ ًا فقــط واملســتند يف إفراغهــا علــى األمــر‬\n      ‫ـاء علــى قــرار التخصيــص الصــادر‬     ‫الســامي ‪........‬يف ‪1386/5/8‬ه ـ ‪ .‬وبنـ ً‬\n      ‫مــن أمــارة مدينــة املدينــة املنــورة رقــم ‪ 26872‬يف ‪1433/3/15‬ه ـ املبلــغ‬\n      ‫بخطــاب أمانــة مدينــة املدينــة املنــورة رقــم ‪........‬يف ‪1433/4/18‬ه ـ قــد‬\n      ‫أصبحــت يف ملــك ‪ /‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم وعليــه‬\n      ‫ا مــا جــاء يف‬ ‫جــرى التصديــق « أ ‪.‬ه ـ وبعرضــه علــى املدعــي أجــاب قائـ ً‬\n      ‫الصــك صحيــح ولكــن املذكــور قــد باعهــا علــى املدعــى عليــه هكــذا‬\n      ‫ا مــا ذكــره املدعــي‬    ‫أجــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫غيــر صحيــح واألرض التــزال ولــم يبعهــا علــي هكــذا أجــاب ولــذا فقــد‬\n\n\n‫‪409‬‬\n\f‫قــررت إدخــال املذكــور لســماع مــا لديــه ورفعــت اجللســة ويف جلســة‬\n‫أخــرى لــدي أنــا القاضــي يف احملكمــة العامــة باملدينــة املنــورة القائــم‬\n‫بأعمــال املكتــب القضائــي اخلامــس حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه فســألت املدعــي وكالــة هــل كان موكلــك يعلــم موقــع األرض‬\n‫التــي ستســتبدل بهــا األرض املنزوعــة والتــي مت الشــراء مــن أجلهــا قــال‬\n‫ال لــم يكــن يعلــم مكانهــا وإمنــا كان يعلــم أن األرض التــي اشــتراها‬\n‫منزوعــة لوقوعهــا يف ملــك شــخص آخــر وســيعوض عنهــا بقطعــة أخــرى‬\n‫وطلــب موكلــي هــو أن تفــرغ األرض اجلديــدة باســمه واشــترى موكلــي‬\n‫األرض املنزوعــة لقلــة ثمنهــا بســبب أنهــا منزوعــة فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة قــد ذكــر بــأن موكلــه‬\n‫اشــترى أرض ـ ًا منزوعــة ليســت يف ملــك املدعــى عليــه وقصــده أرض ـ ًا‬\n‫غيــر معلومــة ولقولــه صلــى اهلل عليــه وســلم «ال تبــع مــا ليــس عنــدك»‬\n‫ونهيــه عــن بيــع املجهــول لذلــك كلــه فقــد ثبــت لــدي أن البيــع محــل‬\n‫الدعــوى بيــع باطــل ومبوجبــه فقــد رددت دعــوى املدعــي وكالــة وأخليــت‬\n‫ســبيل املدعــى عليــه وبــه حكمــت وبعرضــه علــى الطرفــن قنــع بــه‬\n‫املدعــى عليــه ولــم يقنــع بــه املدعــي وكالــة فأفهــم مبقتضــى تعليمــات‬\n‫االســتئناف‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1434/5/5‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪،‬‬\n‫فلــدي أنــا القاضــي يف احملكمــة العامــة باملدينــة املنــورة القائــم بأعمــال‬\n‫املكتــب القضائــي اخلامــس ‪ ،‬يف يــوم الثالثــاء املوافــق ‪1434/8/9‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الواحــدة وخمــس وأربعــون دقيقــة ظهــر ًا فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف يف مكــة املكرمــة باخلطــاب‬\n\n\n                                                                                     ‫‪410‬‬\n\f      ‫رقــم ( ‪ ) 33/884087‬يف ‪1434/7/2‬ه ـ ‪ ،‬وقيــدت بأســاس احملكمــة‬\n      ‫برقــم ( ‪ ) 33/884087‬يف ‪1434/7/8‬ه ـ ‪ ،‬مرفقـ ًا بهــا اإلعــام الصادر‬\n      ‫مــن فضيلــة ناظــر القضيــة برقــم ( ‪ ) 34208586‬يف ‪1434/5/7‬ه ـ ‪،‬‬\n      ‫مظهــر ًا بالقــرار الصــادر مــن الدائرة احلقوقية األولى برقم ( ‪34254308‬‬\n      ‫) يف ‪1434/6/28‬ه ـ ‪ ،‬واملتضمــن مــا نــص احلاجــة منه مايلي‪ « /‬بدراســة‬\n      ‫احلكــم ‪ ،‬وصــورة ضبطــه ‪ ،‬والالئحــة االعتراضية ‪ ،‬تقررت باألكثرية‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬وبــاهلل تعالــى التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة املكلــف‬\n      ‫برقــم ‪ 33884087‬وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n      ‫واملســجل بعــدد ‪ 34208586‬وتاريــخ ‪1434/5/7‬هـ ـ واملتضمــن دعــوى‪/‬‬\n                                         ‫ضــد‪ /‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n      ‫باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n‫‪411‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":407,"source_page_end":411,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3f8f0a5b5c930d709873b76a7dc8583b617db65902ff90211918a9eccf0aac33","normalized_text_hash":"b74e6a5a0500ad2c48193235d05a0adfaf5cbacf1aa44e5b1d114709e82d9e35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p407-34208586"},{"id":"c5459272-5c69-50c0-933f-56c506f63ca1","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء منحة أرض مبوجب تذكره مراجعة -عدم وجود منحة -بيع املعدوم -بيع ما ال ميلك -أوامر املنح ليست من احلقوق املعنوية املجردة التي يجيز بعض احلنفية بيعها -بطان البيع ورد الثمن .","document_number":"33330892","case_number":"333676","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/7","year":"1434","subject":"عقار -شراء منحة أرض مبوجب تذكره مراجعة -عدم وجود منحة -بيع املعدوم -بيع ما ال ميلك -أوامر املنح ليست من احلقوق املعنوية املجردة التي يجيز بعض احلنفية بيعها -بطان البيع ورد الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33330892 :‬تاريخه ‪1433/7/7 :‬هـ‬\n                      ‫رقم الدعوى ‪333676 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34221029:‬تاريخه‪1434/05/25:‬هـ‬\n\n\n‫عقــار ‪ -‬شــراء منحــة أرض مبوجــب تذكــره مراجعــة ‪ -‬عــدم وجــود‬\n‫منحــة ‪ -‬بيــع املعــدوم ‪ -‬بيــع مــا ال ميلــك ‪ -‬أوامــر املنــح ليســت مــن‬\n‫احلقــوق املعنويــة املجــردة التــي يجيــز بعــض احلنفيــة بيعهــا ‪ -‬بطــان‬\n                                                       ‫البيــع ورد الثمــن ‪.‬‬\n\n\n\n\n‫حديــث حكيــم بــن حــزام أن النبــي صلــى اهلل عليــه وســلم قــال ( التبــع‬\n                                                           ‫مــا ليــس عنــدك )‬\n\n\n\n\n‫ادعــى املدعــى أنــه اشــترى مــن املدعــى عليــه أمــر منحــة أرض مبوجــب‬\n‫تذكــره مراجعــة مبوجــب العقــد املبــرم وأنــه ســلم املدعــى عليــه الثمــن‪-‬‬\n‫وأن املدعــى عليــه وعــد بإعطــاء األمــر الســامي بعــد شــهر مــن تاريــخ‬\n‫العقــد‪ -‬حيــث مضــى علــى العقــد قرابــة الســنتني لــذا طلــب املدعــى إلزام‬\n‫املدعــى عليــه بإعــادة املبلــغ الــذى اســتلمه منــه‪ -‬قــرر املدعــى عليــه بأنــه‬\n‫حضــر لــه شــخص أخــر واســمي نفســه باســم املدعــى واشــترى منــه أمــر‬\n‫املنحــة وأنــه لــم يتــم حتديــد مــده معينــة لتســليم أمــر املنحــة‪ -‬قــرر املدعــى‬\n‫عليــه أنــه غيــر مســتعد بإعــادة املبلــغ ألن البيــع مت‪ -‬قــرر املدعــى أنــه‬\n‫هــو الــذى اشــترى بنفســه والشــخص املذكــور صديقــه‪ -‬مت االطــاع‬\n\n                                                                                           ‫‪412‬‬\n\f      ‫علــى عقــد البيــع ورصــد مضمونــه‪ -‬صــادق الطرفــان علــى أن أمــر املنحــة‬\n      ‫لــم يصــدر بعــد‪ -‬نهــى النبــي صلــى اهلل عليــه وســلم عــن بيــع مــاال ميلــك‬\n      ‫وبيــع أوامــر املنــح مــن هــذا القبيــل لــذا صــدر احلكــم ببطــان عقــد‬\n      ‫البيــع املذكــور والــزام املدعــى عليــه بــأن يدفــع للمدعــى املبلــغ املدعــى‬\n      ‫بــه‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                           ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي القائــم بعمــل املكتــب‬\n      ‫الســادس عشــر يف احملكمــة العامــة بالطائــف وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة بالطائف‪/‬املكلف برقم‬\n      ‫‪ 333676‬وتاريــخ ‪ 1433/01/01‬ه ـ املقيــدة باحملكمــة برقــم ‪338478‬‬\n      ‫وتاريــخ ‪ 1433/01/01‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/03/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10 : 06‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر حلضــوره وكيــل املدعــى‬\n      ‫عليــه ‪ ...‬ســجل مدنــي ‪ ...‬وأبــرز وكالتــه الصــادرة مــن كتابــة عــدل‬\n      ‫الثانيــة بالطائــف برقــم ‪16615‬يف ‪1433/03/20‬ه ـ وادعــى قائــا لقــد‬\n      ‫اشــتريت منــه منحــة أرض مبوجــب تذكــرة مراجعــة رقــم القيــد ‪16523‬‬\n      ‫وتاريــخ ‪1431/03/10‬ه ـ ومبوجــب العقــد املبــرم بيننــا رقــم ‪ 54‬حيــث‬\n      ‫أوعدنــي بإعطائــي األمــر الســامي الكــرمي بعــد شــهر مــن تاريــخ العقــد‬\n      ‫‪1431/08/28‬ه ـ ولــم يــويف مبــا أوعدنــي هــذه دعــواي وأبــرز صــورة‬\n      ‫مــن عقــد املبايعــة متضمنــا توقيــع البائــع ‪ ...‬وتوقيــع املشــتري ‪ ...‬وأبــرز‬\n      ‫صــورة مــن تذكــرة مراجعــة طلــب أرض ســكنية باســم ‪ ...‬وبعــرض‬\n\n‫‪413‬‬\n\f‫الدعــوى علــي وكيــل املدعــى عليــه أجــاب قائــا أنــا ال أعــرف ‪ ...‬وقــد‬\n‫جاءنــي رجــل يدعــى ‪ ...‬وقــال أن ‪ ...‬يريــد شــراء منحــة أرض تخصنــي يف‬\n‫الديــوان امللكــي وقــد قمنــا ببيعــة وكتابــة ورقــة مبايعــة وأعطانــا ســبعة‬\n‫وثالثــن ألــف وخمســمائة ريــال وغيــر مســتعد بإعــادة املبلــغ لــه ألن البيــع‬\n‫مت وال أريــد فســخه ولــم نعــده بوقــت محــدد لتســليمه األرض هكــذا‬\n‫أجــاب وعليــه رفعــت القضيــة للتأمــل وحــدد بهــا موعــد يــوم اإلثنــن‬\n‫بتاريــخ ‪1433/05/24‬ه ـ الســاعة العاشــرة صباحــا واهلل املوفــق وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                            ‫يف ‪ 1433/03/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪1433/01/01‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافق‪1433/05/24‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 29‬وفيهــا حضــر‬\n‫الطرفــان وحضــر والــد املدعــى عليــه وكيلــه ‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل الطائــف الثانيــة رقــم ‪ 16615‬وتاريــخ ‪1433/03/20‬ه ـ اجللــد‬\n‫‪ 5674‬وقــال املدعــي لقــد وعدنــي املدعــى عليــه مبــا ذكــرت قبــل العقــد‬\n‫و‪ ...‬صديقــي وأخبرنــي عــن املنحــة لكنــه لــم يشــتري عنــي بــل أنــا الــذي‬\n‫اشــتريت بنفســي فقــال املدعــى عليــه لــم أعــده مبــا ذكــر والعقــد مت‬\n‫قبــل قرابــة ســنتني فلمــاذا ســكت طــوال هــذه املــدة واملنحــة ال زالــت‬\n‫يف الســرا بالديــوان وبالرجــوع للعقــد املشــار إليــه وجــدت عبــارة نصهــا‬\n‫البيعــة ورقــة منحــة وعلــى البائــع تســوية الوكالــة وبســؤال الطرفــن‬\n\n\n                                                                                     ‫‪414‬‬\n\f      ‫عــن معنــى هــذا قــال املدعــي معناهــا أن املدعــى عليــه البائــع يحضــر‬\n      ‫لــي األمــر الســامي ويعطينــي وكالــة ملتابعــة املنحــة فقــال املدعــى عليــه‬\n      ‫بــل معناهــا أنــي اعطيــه وكالــة ملتابعــة املنحــة والتــي هــي املبيــع وأمــا‬\n      ‫إحضــار األمــر الســامي فــا يلزمنــي والعقــد صريــح وقــد رضــي بــه‬\n      ‫وبســؤال املدعــي عــن بينتــه علــى أن املدعــى عليــه وعــده مبــا ذكــر قبــل‬\n      ‫العقــد وأنــه التــزم لــه بإحضــار األمــر الســامي قــال بينتــي شــهود العقــد‬\n      ‫وســأحضرهم اجللســة القادمــة فرفعــت اجللســة لذلــك وتأجلــت إلــى يــوم‬\n      ‫االثنــن املوافــق ‪1433/07/07‬ه ـ الســاعة التاســعة والنصــف وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪1433/05/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪1433/01/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم االثنــن‬\n      ‫املوافق‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا حضــر‬\n      ‫املدعــي وحضــر حلضــوره املدعــى عليــه ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬وحضــر والــد املدعــى عليــه ووكيلــه وقال املدعي‬\n      ‫لــم أمتكــن مــن إحضــار بينتــي ألنهــم مــن جماعتــه ويخشــون القطيعــة إن‬\n      ‫شــهدوا فلذلــك امتنعــوا وليــس لــدي بينــة أخــرى وال أقبــل ميــن املدعــي‬\n      ‫وهنــاك دعــوى مماثلــه مــن أخــي ضــد املدعــى عليــه لــدى القاضــي ‪...‬‬\n      ‫وقــد حكــم فيهــا علــى املدعــى عليــه ثــم أبــرز صــورة الصــك الصــادر‬\n      ‫مــن القاضــي ‪ ...‬ألخيــه ضــد املدعــى عليــه فــإذا هــو برقــم ‪33312643‬‬\n      ‫وتاريــخ ‪1433/06/23‬ه ـ ويتضمــن احلكــم غيابيــا ضــد املدعــى عليــه‬\n\n\n‫‪415‬‬\n\f‫بإعــادة املبلــغ للمدعــي وجــاء يف الدعــوى أنــه باعــه منحــه فتبــن بــأن‬\n‫الورقــة ورقــة مراجعــة للديــوان وليســت منحــه وبســؤال الطرفــن عــن‬\n‫املبيــع أفــادا بأنــه مجــرد ورقــة منحــه لــم حتصــل بعــد وعليه فبنــاء على ما‬\n‫تقــدم مــن الدعــوى املتضمنــة مصادقــة املدعــى عليــه علــى دعــوى املدعــي‬\n‫باملبايعــة علــى الصفــة املدعــى بهــا وإنــكاره االشــتراط احملــدد للمــدة‬\n‫وملــا جــاء يف احلكــم القضائــي بواقعــة مماثلــة وألن املنحــة لــم حتصــل‬\n‫بعــد فــإن بيعهــا مــن قبيــل بيــع املعــدوم كالســمك يف املــاء والطيــر يف‬\n‫الهــواء مــع عــدم القــدرة علــى تســليمها وعــدم متــام ملــك البائــع لهــا وقــد‬\n‫نهــى النبــي صلــى اهلل عليــه وســلم حكيــم بــن حــزام رضــي اهلل عنــه عــن‬\n‫ذلــك وقــال (ال تبــع مــا ليــس عنــدك) وليســت مــن قبيــل احلقــوق املعنويــة‬\n‫املجــردة التــي يجيــز بعــض احلنفيــة بيعهــا ألن احلــق غيــر معلــوم وال ثابــت‬\n‫فيهــا فهــي مــن قبيــل الغــرر وحصولهــا غيــر متيقــن وقــد نهــى النبــي صلــى‬\n‫اهلل عليــه وســلم عــن بيــع املعــدوم والغــرر ونهــى اهلل ســبحانه وتعالــى قبــل‬\n‫ذلــك عــن أكل املــال بالباطــل وعليــه فقــد حكمــت ببطــان هــذا البيــع‬\n‫وألزمــت املدعــى عليــه بــأن يــرد للمدعــي الثمــن املدعــى بــه وقــدره ســبعة‬\n‫وثالثــون ألــف وخمســمائة ريــال وبعــرض احلكــم علــى الطرفــن لــم‬\n‫يقنــع بــه املدعــي عليــه وطلــب االســتئناف وأســتعد بتقــدمي الئحــة فأجيــب‬\n‫لطلبــه وســلم صــورة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n‫يومــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1433/07/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ويف يــوم األحــد املوافق‪1433/08/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 00‬وقــد وردتنــا الالئحــة االعتراضيــة املقدمــة مــن ‪...‬‬\n\n\n                                                                                        ‫‪416‬‬\n\f      ‫واملقيــدة برقــم ‪ 331444174‬وتاريــخ ‪1433/07/30‬ه ـ واملكونــة مــن‬\n      ‫ورقــة واحــده وباإلطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت‬\n      ‫بــه وللبيــان جــرى رصــده وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 333676‬وتاريــخ ‪ 1433/01/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 338478‬وتاريــخ ‪ 1433/01/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/09/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــر وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 34297383‬وتاريــخ ‪1434/5/19‬ه ـ املرفــق معهــا قــرار رقــم‬\n      ‫‪ 34221029‬وتاريــخ ‪1434/5/25‬ه ـ املــدون علــى ظهــر الصــك املتضمــن‬\n      ‫« املوافقــة علــى احلكــم « وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/02‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫احملكمــة العامــة بالطائــف برقــم ‪ 34297383‬وتاريــخ ‪1434/05/12‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة‬\n      ‫العامــة بالطائــف املســجل برقــم ‪ 33330892‬وتاريــخ ‪1433/07/07‬ه ـ‬\n      ‫املتضمــن دعــوى ‪ ...‬ضــد ‪ ، ...‬وبدراســة الصــك وص ــورة ضبط ــه والئحتــه‬\n                      ‫اإلعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم واهلل املوفــق‪.‬‬\n                  ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم‪،،،،،‬‬\n\n\n‫‪417‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":412,"source_page_end":417,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44d84488f3aab70a260dbe7cdb13ca2dbc2e6629aab0a95755711abac0c84ee8","normalized_text_hash":"094148b4d63f950dd3dd06e6d9f3f775ec0e019525c19ceeee80c9d150b8acf6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p412-33330892"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
